begin;
alter table public.exams disable trigger trg_exams_sync_bank;
do $do$ declare r jsonb; e jsonb; h text; begin
  for r in select * from jsonb_array_elements($j$[{"id":656421,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":2,"options":["2,1.10<sup>4</sup> m²/s².","11,68.10<sup>4</sup> m²/s².","23,37.10<sup>4</sup> m²/s².","4,2.10<sup>4</sup> m²/s²."],"question":"Trong một bình kín có chứa khí oxygen ở nhiệt độ 270C. Khối lượng mol của phân tử oxygen là 32 g/mol. Trung bình của bình phương tốc độ chuyển động nhiệt của các phân tử khí oxygen trong bình là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Động năng tịnh tiến trung bình của phân tử: $\\overline{W_đ} = \\dfrac12 m\\overline{v^2} = \\dfrac32 kT$, nên $\\overline{v^2} = \\dfrac{3kT}{m} = \\dfrac{3RT}{M}$ ($k = R/N_A$, $m = M/N_A$).</p><p class=\"text-base leading-relaxed my-2\">Đề hiểu là nhiệt độ $27^\\circ C$ (\"270C\" mất kí hiệu độ). Đổi $T = 27 + 273 = 300\\ \\text{K}$, $M = 32\\ \\text{g/mol} = 0{,}032\\ \\text{kg/mol}$.</p><p class=\"text-base leading-relaxed my-2\">$\\overline{v^2} = \\dfrac{3\\cdot 8{,}31\\cdot 300}{0{,}032} \\approx 23{,}37\\cdot 10^{4}\\ \\text{m}^2/\\text{s}^2$.</p><p class=\"text-base leading-relaxed my-2\">Sai vì: $2{,}1\\cdot 10^{4}$ là thay $T = 27$ mà không đổi sang kelvin ($\\dfrac{3\\cdot 8{,}31\\cdot 27}{0{,}032} \\approx 2{,}1\\cdot 10^{4}$). $11{,}68\\cdot 10^{4}$ là một nửa kết quả, tức dùng $\\dfrac{3RT}{2M}$ (nhầm $\\dfrac32 kT$ với $kT\\cdot\\overline{v^2}$). $4{,}2\\cdot 10^{4}$ không đúng vì không bằng $\\dfrac{3RT}{M}$ với số liệu của đề.</p><p class=\"text-base leading-relaxed my-2\">Chọn C.</p>","difficultySource":"ai"},"ex":[{"exam":377,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":2,"options":["2,1.10<sup>4</sup> m²/s².","11,68.10<sup>4</sup> m²/s².","23,37.10<sup>4</sup> m²/s².","4,2.10<sup>4</sup> m²/s²."],"question":"Trong một bình kín có chứa khí oxygen ở nhiệt độ 270C. Khối lượng mol của phân tử oxygen là 32 g/mol. Trung bình của bình phương tốc độ chuyển động nhiệt của các phân tử khí oxygen trong bình là","difficulty":"trung-binh","explanation":"$n=\\frac{m}{M}\\Rightarrow m=M.n=M.\\frac{N}{N_A}$ ;  $N=n.N_A$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$E_d=\\frac{3}{2}.k.T=\\frac{m.\\overline{v}^2}{2}$<br>$\\begin{aligned}\\end{aligned}3.\\frac{R}{N_A}.300=M.\\frac{N}{N_A}.\\overline{v}^2Website: thukhoadaihoc.vn$<br>$\\Rightarrow 3.8,31.300=\\frac{32}{1000}.1.\\overline{v}^2$<br>$\\Rightarrow \\overline{v}^2=23,37.10^4\\left(m^2/s^2\\right)$","difficultySource":"ai"}}]},{"id":656426,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["2,54.10<sup>5</sup> J/kg.","3,32.10<sup>5</sup> J/kg.","2,88.10<sup>5</sup> J/kg.","6,65.10<sup>5</sup> J/kg."],"question":"Một học sinh tiến hành thí nghiệm xác định nhiệt nóng chảy riêng của nước đá bằng nhiệt lượng kế có dây nung với công suất P = 24 W, cùng với cân và cốc hứng nước. Sơ đồ thí nghiệm như hình bên.<br>– Bước 1. Cho nước đá tan ở 00C vào nhiệt lượng kế sau thời gian t = 360 s thì thu được khối lượng nước ở cốc là m = 4.10<sup>−3</sup> kg<br>– Bước 2. Bật biến áp nguồn để nung nóng lượng nước đá cũng trong thời gian 360s. Sau đó học sinh ghi nhận tổng lượng nước trong cốc là M = 34.10<sup>−3</sup> kg. Bước 2 được tiến hành ngay sau bước<br>1, xem dây nung không tỏa nhiệt ra môi trường. Nhiệt nóng chảy riêng của nước đá mà học sinh này đo được xấp xỉ<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046456302-hinh-3.jpg\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"34g – 4g (ở bước 1 đã có ở trong cốc) – 4g (trao đổ nhiệt vối môi trường) = 26g = 26.10<sup>−3</sup>kg =  $\\frac{Q}{\\lambda }=\\frac{Pt}{\\lambda }$<br>$\\Rightarrow \\lambda =\\frac{24.360}{26.10^{−3}}=3,32.10^5\\left(J/kg\\right)$","difficultySource":"ai"},"ex":[{"exam":377,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["2,54.10<sup>5</sup> J/kg.","3,32.10<sup>5</sup> J/kg.","2,88.10<sup>5</sup> J/kg.","6,65.10<sup>5</sup> J/kg."],"question":"Một học sinh tiến hành thí nghiệm xác định nhiệt nóng chảy riêng của nước đá bằng nhiệt lượng kế có dây nung với công suất P = 24 W, cùng với cân và cốc hứng nước. Sơ đồ thí nghiệm như hình bên.<br>– Bước 1. Cho nước đá tan ở 00C vào nhiệt lượng kế sau thời gian t = 360 s thì thu được khối lượng nước ở cốc là m = 4.10<sup>−3</sup> kg<br>– Bước 2. Bật biến áp nguồn để nung nóng lượng nước đá cũng trong thời gian 360s. Sau đó học sinh ghi nhận tổng lượng nước trong cốc là M = 34.10<sup>−3</sup> kg. Bước 2 được tiến hành ngay sau bước<br>1, xem dây nung không tỏa nhiệt ra môi trường. Nhiệt nóng chảy riêng của nước đá mà học sinh này đo được xấp xỉ<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046456302-hinh-3.jpg\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"34g – 4g (ở bước 1 đã có ở trong cốc) – 4g (trao đổ nhiệt vối môi trường) = 26g = 26.10<sup>−3</sup>kg =  $\\frac{Q}{\\lambda }=\\frac{Pt}{\\lambda }$<br>$\\Rightarrow \\lambda =\\frac{24.360}{26.10^{−3}}=3,32.10^5\\left(J/kg\\right)$","difficultySource":"ai"}}]},{"id":656432,"nq":{"form":"bai_tap","type":"true_false","topic":"Động năng trung bình phân tử và nhiệt độ","question":"Nhiệt độ của một mol khí lí tưởng (đơn nguyên tử) trong một bình kín được làm tăng từ 120C lên 2970C. Khi đó, nội năng của khí thay đổi, nội năng khí được tính theo công thức  $U=\\frac{3}{2}nRT$  (với n là số mol, T là nhiệt độ tuyệt đối).","difficulty":"trung-binh","statements":[{"text":"Động năng tịnh tiến trung bình của mỗi phân tử khí ở 120C xấp xỉ 5,9.10<sup>−21</sup> J.","answer":true},{"text":"Áp suất khí tăng lên 2 lần.","answer":true},{"text":"Động năng tịnh tiến trung bình của phân tử khí tỉ lệ với nhiệt độ tuyệt đối của khí theo công thức  $W_d=\\frac{2}{3}kT$ (k là hằng số Boltzmann).","answer":false},{"text":"Nội năng của khối khí ở 2970C xấp xỉ 7105 J.","answer":true}],"explanation":"a) đúng<br>$\\overline{E}_d=\\frac{3}{2}k.T=1,5.1,38.10^{−23}.\\left(12+273\\right)=5,9.10^{−21}\\left(J\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>T tăng  $\\frac{297+273}{12+273}=2$  lần  $\\Rightarrow p↑2$<br>c) sai<br>$W_d=\\frac{3}{2}kT$<br>d) đúng<br>$U=\\frac{3}{2}.n.R.T=1,5.1.8,31.\\left(297+273\\right)=7105,05\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":377,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Động năng trung bình phân tử và nhiệt độ","question":"Nhiệt độ của một mol khí lí tưởng (đơn nguyên tử) trong một bình kín được làm tăng từ 120C lên 2970C. Khi đó, nội năng của khí thay đổi, nội năng khí được tính theo công thức  $U=\\frac{3}{2}nRT$  (với n là số mol, T là nhiệt độ tuyệt đối).","difficulty":"trung-binh","statements":[{"text":"Động năng tịnh tiến trung bình của mỗi phân tử khí ở 120C xấp xỉ 5,9.10<sup>−21</sup> J.","answer":true},{"text":"Áp suất khí tăng lên 2 lần.","answer":true},{"text":"Động năng tịnh tiến trung bình của phân tử khí tỉ lệ với nhiệt độ tuyệt đối của khí theo công thức  $W_d=\\frac{2}{3}kT$ (k là hằng số Boltzmann).","answer":false},{"text":"Nội năng của khối khí ở 2970C xấp xỉ 7105 J.","answer":true}],"explanation":"a) đúng<br>$\\overline{E}_d=\\frac{3}{2}k.T=1,5.1,38.10^{−23}.\\left(12+273\\right)=5,9.10^{−21}\\left(J\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>T tăng  $\\frac{297+273}{12+273}=2$  lần  $\\Rightarrow p↑2$<br>c) sai<br>$W_d=\\frac{3}{2}kT$<br>d) đúng<br>$U=\\frac{3}{2}.n.R.T=1,5.1.8,31.\\left(297+273\\right)=7105,05\\left(J\\right)$","difficultySource":"ai"}}]},{"id":656435,"nq":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ áp suất với động năng phân tử","answer":"3,2","question":"Khối lượng riêng của một chất khí là  $\\delta$  = 6.10<sup>−2</sup> kg/m³, vận tốc căn quân phương của các phân tử khí này là 400 m/s. Áp suất của khối khí tác dụng lên thành bình là y.10³ N/m². Xác định giá trị của y (kết quả làm tròn đến hàng phần chục).","difficulty":"de","explanation":"$p=\\frac{1}{3}.\\mu .m.\\overline{v}^2$<br>$\\Rightarrow y.10^3=\\frac{1}{3}.\\frac{N}{V}.m.\\overline{v}^2$  (m là khối lượng 1 phân tử khí)<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow y.10^3=\\frac{1}{3}.\\frac{m_0}{V}.\\overline{v^2}=\\frac{1}{3}.\\delta .\\overline{v}^2=\\frac{1}{3}.6.10^{−2}.400^2$<br>$\\Rightarrow y=3,2$","difficultySource":"ai"},"ex":[{"exam":377,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ áp suất với động năng phân tử","answer":"3,2","question":"Khối lượng riêng của một chất khí là  $\\delta$  = 6.10<sup>−2</sup> kg/m³, vận tốc căn quân phương của các phân tử khí này là 400 m/s. Áp suất của khối khí tác dụng lên thành bình là y.10³ N/m². Xác định giá trị của y (kết quả làm tròn đến hàng phần chục).","difficulty":"de","explanation":"$p=\\frac{1}{3}.\\mu .m.\\overline{v}^2$<br>$\\Rightarrow y.10^3=\\frac{1}{3}.\\frac{N}{V}.m.\\overline{v}^2$  (m là khối lượng 1 phân tử khí)<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow y.10^3=\\frac{1}{3}.\\frac{m_0}{V}.\\overline{v^2}=\\frac{1}{3}.\\delta .\\overline{v}^2=\\frac{1}{3}.6.10^{−2}.400^2$<br>$\\Rightarrow y=3,2$","difficultySource":"ai"}}]},{"id":658060,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":1,"options":["1,290 kg/m3.","1,178 kg/m3.","1,187 kg/m3.","1,920 kg/m3."],"question":"Biết không khí bên ngoài có nhiệt độ 270C và áp suất 1 atm, khối lượng mol của không khí ở điều kiện tiêu chuẩn là 29.10<sup>−3</sup> kg/mol (xem không đổi khi nhiệt độ thay đổi). Cho biết: 1 atm = 1,013.10<sup>5</sup> Pa. Khối lượng riêng của không khí ở nhiệt độ 270C bằng","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng phương trình trạng thái khí lí tưởng cho không khí, coi không khí là khí lí tưởng ở áp suất 1 atm và nhiệt độ 27°C:</p><p class=\"text-base leading-relaxed my-2\">$pV = \\dfrac{m}{M}RT$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\rho = \\dfrac{m}{V} = \\dfrac{pM}{RT}$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $T = 27 + 273 = 300\\ \\text{K}$; $p = 1{,}013\\cdot 10^5\\ \\text{Pa}$; $M = 29\\cdot 10^{-3}\\ \\text{kg/mol}$; $R = 8{,}31\\ \\text{J/(mol·K)}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$\\rho = \\dfrac{1{,}013\\cdot 10^5 \\cdot 29\\cdot 10^{-3}}{8{,}31 \\cdot 300} \\approx 1{,}178\\ \\text{kg/m}^3$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: khối lượng riêng của không khí ở 27°C là $1{,}178\\ \\text{kg/m}^3$, chọn đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":378,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":1,"options":["1,290 kg/m3.","1,178 kg/m3.","1,187 kg/m3.","1,920 kg/m3."],"question":"Biết không khí bên ngoài có nhiệt độ 270C và áp suất 1 atm, khối lượng mol của không khí ở điều kiện tiêu chuẩn là 29.10<sup>−3</sup> kg/mol (xem không đổi khi nhiệt độ thay đổi). Cho biết: 1 atm = 1,013.10<sup>5</sup> Pa. Khối lượng riêng của không khí ở nhiệt độ 270C bằng","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng phương trình trạng thái khí lí tưởng cho không khí, coi không khí là khí lí tưởng ở áp suất 1 atm và nhiệt độ 27°C:</p><p class=\"text-base leading-relaxed my-2\">$pV = \\dfrac{m}{M}RT$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\rho = \\dfrac{m}{V} = \\dfrac{pM}{RT}$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $T = 27 + 273 = 300\\ \\text{K}$; $p = 1{,}013\\cdot 10^5\\ \\text{Pa}$; $M = 29\\cdot 10^{-3}\\ \\text{kg/mol}$; $R = 8{,}31\\ \\text{J/(mol·K)}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$\\rho = \\dfrac{1{,}013\\cdot 10^5 \\cdot 29\\cdot 10^{-3}}{8{,}31 \\cdot 300} \\approx 1{,}178\\ \\text{kg/m}^3$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: khối lượng riêng của không khí ở 27°C là $1{,}178\\ \\text{kg/m}^3$, chọn đáp án B.</p>","difficultySource":"ai"}}]},{"id":658064,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":1,"options":["6,6 m.","3,3 m.","30,3 m.","27,3 m."],"question":"Kênh VOV Giao Thông FM 91 MHz là kênh phát thanh thực tế đầu tiên tại Việt Nam, ra đời năm 2010, trực thuộc Đài tiếng nói Việt Nam. Kênh cung cấp các diễn biến giao thông đang xảy ra trên thực tế giúp các thính giá có cái nhìn toàn cảnh và chính xác nhất về giao thông. Biết tín hiệu sóng vô tuyến này lan truyền trong không khí với tốc độ 3.10<sup>8</sup> m/s thì có bước sóng xấp xỉ bằng","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Bước sóng của sóng vô tuyến được tính theo công thức $\\lambda = \\dfrac{v}{f}$, trong đó $v$ là tốc độ truyền sóng và $f$ là tần số.</p><p class=\"text-base leading-relaxed my-2\">Tốc độ truyền sóng: $v = 3.10^8\\ \\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Tần số của kênh VOV Giao Thông FM: $f = 91\\ \\text{MHz} = 91.10^6\\ \\text{Hz}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $\\lambda = \\dfrac{3.10^8}{91.10^6} \\approx 3,3\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: bước sóng xấp xỉ $3,3\\ \\text{m}$, chọn đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":378,"idx":13,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":1,"options":["6,6 m.","3,3 m.","30,3 m.","27,3 m."],"question":"Kênh VOV Giao Thông FM 91 MHz là kênh phát thanh thực tế đầu tiên tại Việt Nam, ra đời năm 2010, trực thuộc Đài tiếng nói Việt Nam. Kênh cung cấp các diễn biến giao thông đang xảy ra trên thực tế giúp các thính giá có cái nhìn toàn cảnh và chính xác nhất về giao thông. Biết tín hiệu sóng vô tuyến này lan truyền trong không khí với tốc độ 3.10<sup>8</sup> m/s thì có bước sóng xấp xỉ bằng","difficulty":"de","explanation":"$\\lambda =\\frac{v}{f}=\\frac{3.10^8}{91.10^6}\\approx 3,3\\left(m\\right)$","difficultySource":"ai"}}]},{"id":658066,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":1,"options":["0,91.102 kg.","1,91.102 kg.","2,90.102 kg.","1,91.10<sup>3</sup> kg."],"question":"Khối lượng không khí có trong phòng xấp xỉ bằng","difficulty":"de","explanation":"$p_0V=\\frac{m}{M}RT_0\\Rightarrow m=\\frac{p_0VM}{RT_0}=\\frac{10^5.\\left(5.10.3\\right).0,029}{8,31.273}\\approx 191,75\\left(kg\\right)$","difficultySource":"ai"},"ex":[{"exam":378,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":1,"options":["0,91.102 kg.","1,91.102 kg.","2,90.102 kg.","1,91.10<sup>3</sup> kg."],"question":"Khối lượng không khí có trong phòng xấp xỉ bằng","difficulty":"de","explanation":"$p_0V=\\frac{m}{M}RT_0\\Rightarrow m=\\frac{p_0VM}{RT_0}=\\frac{10^5.\\left(5.10.3\\right).0,029}{8,31.273}\\approx 191,75\\left(kg\\right)$","difficultySource":"ai"}}]},{"id":658072,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Bình đun siêu tốc Delites DT15S01 công suất 1500 W, vỏ bình có khối lượng 500 g làm bằng vật liệu có nhiệt dung riêng 480 J/(kgK). Dùng bình này đun 1,20 L nước ở nhiệt độ 25,0°C (nhiệt độ ban đầu của bình cũng 25,00C). Nước có nhiệt dung riêng 4200 J/(kgK) và khối lượng riêng 1,00 kg/L. Khi đun, bình tiêu thụ đúng công suất điện 1500 W thì có 20,0% năng lượng truyền ra môi trường, phần còn lại truyền nhiệt cho vỏ bình và nước trong bình, Biết nước sôi ở 1000C, xem nước chỉ hóa hơi ở nhiệt độ sôi và nhiệt hóa hơi riêng của nước ở nhiệt độ đó là 2,26.10<sup>6</sup> J/kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046496589-hinh-16.jpg\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khi nước đạt đến 1000C thì sự hóa hơi xảy ra đồng thời ở bên trong và trên mặt nước.","answer":true},{"text":"Trong quá trình đun, năng lượng mà nước trong bình hấp thụ và năng lượng mà vỏ bình hấp thụ bằng nhau sau khoảng thời gian bằng nhau.","answer":false},{"text":"Khi bình tiêu thụ đúng công suất điện thì khoảng thời gian để đun nước trong bình vừa sôi là 4,4 phút.","answer":false},{"text":"Khi bình tiêu thụ đúng công suất điện trong 8 phút thì thể tích nước còn lại trong bình là 0,08 L (làm tròn kết quả đến chữ số hàng phần trăm).","answer":false}],"explanation":"a) đúng<br>Đó là sự sôi<br>b) sai<br>Kiểm tra nhiệt dung của nước và của bình có giống nhau không<br>$m_nc_n=1,2.4200=5040$<br>$m_bc_b=0,5.480=240$<br>$\\Rightarrow$  Khắc nhau<br>c) sai<br>$80%Pt=\\left(m_nc_n+m_bc_b\\right)\\left(100−25\\right)$<br>$\\Leftrightarrow 0,8.1500.t=\\left(5040+240\\right).75$<br>$\\Rightarrow t=330\\left(s\\right)=5,5\\left(phut\\right)$<br>d) sai<br>$80%Pt=L\\Delta m$<br>$\\Rightarrow \\Delta m=\\frac{0,8P\\Delta t}{L}=\\frac{0,8.1500.\\left(8−5,5\\right).60}{2,26.10^6}\\approx 0,08kg\\Leftrightarrow 0,08\\left(lit\\right)$<br>$\\Rightarrow$  Còn lại  $1,2−0,08=1,12$  (lít)","difficultySource":"ai"},"ex":[{"exam":378,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Bình đun siêu tốc Delites DT15S01 công suất 1500 W, vỏ bình có khối lượng 500 g làm bằng vật liệu có nhiệt dung riêng 480 J/(kgK). Dùng bình này đun 1,20 L nước ở nhiệt độ 25,0°C (nhiệt độ ban đầu của bình cũng 25,00C). Nước có nhiệt dung riêng 4200 J/(kgK) và khối lượng riêng 1,00 kg/L. Khi đun, bình tiêu thụ đúng công suất điện 1500 W thì có 20,0% năng lượng truyền ra môi trường, phần còn lại truyền nhiệt cho vỏ bình và nước trong bình, Biết nước sôi ở 1000C, xem nước chỉ hóa hơi ở nhiệt độ sôi và nhiệt hóa hơi riêng của nước ở nhiệt độ đó là 2,26.10<sup>6</sup> J/kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046496589-hinh-16.jpg\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khi nước đạt đến 1000C thì sự hóa hơi xảy ra đồng thời ở bên trong và trên mặt nước.","answer":true},{"text":"Trong quá trình đun, năng lượng mà nước trong bình hấp thụ và năng lượng mà vỏ bình hấp thụ bằng nhau sau khoảng thời gian bằng nhau.","answer":false},{"text":"Khi bình tiêu thụ đúng công suất điện thì khoảng thời gian để đun nước trong bình vừa sôi là 4,4 phút.","answer":false},{"text":"Khi bình tiêu thụ đúng công suất điện trong 8 phút thì thể tích nước còn lại trong bình là 0,08 L (làm tròn kết quả đến chữ số hàng phần trăm).","answer":false}],"explanation":"a) đúng<br>Đó là sự sôi<br>b) sai<br>Kiểm tra nhiệt dung của nước và của bình có giống nhau không<br>$m_nc_n=1,2.4200=5040$<br>$m_bc_b=0,5.480=240$<br>$\\Rightarrow$  Khắc nhau<br>c) sai<br>$80%Pt=\\left(m_nc_n+m_bc_b\\right)\\left(100−25\\right)$<br>$\\Leftrightarrow 0,8.1500.t=\\left(5040+240\\right).75$<br>$\\Rightarrow t=330\\left(s\\right)=5,5\\left(phut\\right)$<br>d) sai<br>$80%Pt=L\\Delta m$<br>$\\Rightarrow \\Delta m=\\frac{0,8P\\Delta t}{L}=\\frac{0,8.1500.\\left(8−5,5\\right).60}{2,26.10^6}\\approx 0,08kg\\Leftrightarrow 0,08\\left(lit\\right)$<br>$\\Rightarrow$  Còn lại  $1,2−0,08=1,12$  (lít)","difficultySource":"ai"}}]},{"id":658080,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":"210","question":"Một thùng dựng 20,0 L nước ở nhiệt độ 20,00C. Cho khối lượng riêng của nước là 1,0.10<sup>3</sup> kg/m3; nhiệt dung riêng của nước là 4200 J/(kg.K). Biết chỉ có 80,0% năng lượng điện tiêu thụ được dùng để làm nóng nước. Tính thời gian (theo đơn vị giây) truyền nhiệt lượng cần thiết nếu dùng một thiết bị điện có công suất 25,0 kW để đun lượng nước trên đến 700C (làm tròn kết quả đến chữ số hàng đơn vị).","difficulty":"trung-binh","explanation":"$P.\\tau .H=m.\\Delta .\\Delta t$<br>$\\Rightarrow 25000.\\tau .80%=20.4200.\\left(70−20\\right)$<br>$\\Rightarrow \\tau =210\\left(s\\right)$","difficultySource":"ai"},"ex":[{"exam":378,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":"210","question":"Một thùng dựng 20,0 L nước ở nhiệt độ 20,00C. Cho khối lượng riêng của nước là 1,0.10<sup>3</sup> kg/m3; nhiệt dung riêng của nước là 4200 J/(kg.K). Biết chỉ có 80,0% năng lượng điện tiêu thụ được dùng để làm nóng nước. Tính thời gian (theo đơn vị giây) truyền nhiệt lượng cần thiết nếu dùng một thiết bị điện có công suất 25,0 kW để đun lượng nước trên đến 700C (làm tròn kết quả đến chữ số hàng đơn vị).","difficulty":"trung-binh","explanation":"$P.\\tau .H=m.\\Delta .\\Delta t$<br>$\\Rightarrow 25000.\\tau .80%=20.4200.\\left(70−20\\right)$<br>$\\Rightarrow \\tau =210\\left(s\\right)$","difficultySource":"ai"}}]},{"id":658084,"nq":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ áp suất với động năng phân tử","answer":"1,8","question":"Một khối khí lí tưởng ở áp suất p = 1,0.10<sup>5</sup> Pa có khối lượng riêng là ρ = 0,09 kg/m3. Căn bậc hai của trung bình bình phương tốc độ chuyển động nhiệt của các phân tử khí là x.10<sup>3</sup> m/s. Tìm x (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046497460-hinh-20.png\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>( $p=\\frac{1}{3}\\mu mv^2;$  Mật độ:  $\\mu =\\frac{N}{V}$<br>m là khối lượng phân tử<br>$\\Rightarrow \\mu m=\\frac{N}{V}.m$  (N.m là tổng khối lượng)<br>$\\Rightarrow \\mu m=\\frac{N}{V}.m=\\delta \\left(kg/m^3\\right)$","difficultySource":"ai"},"ex":[{"exam":378,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ áp suất với động năng phân tử","answer":"1,8","question":"Một khối khí lí tưởng ở áp suất p = 1,0.10<sup>5</sup> Pa có khối lượng riêng là ρ = 0,09 kg/m3. Căn bậc hai của trung bình bình phương tốc độ chuyển động nhiệt của các phân tử khí là x.10<sup>3</sup> m/s. Tìm x (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046497460-hinh-20.png\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>( $p=\\frac{1}{3}\\mu mv^2;$  Mật độ:  $\\mu =\\frac{N}{V}$<br>m là khối lượng phân tử<br>$\\Rightarrow \\mu m=\\frac{N}{V}.m$  (N.m là tổng khối lượng)<br>$\\Rightarrow \\mu m=\\frac{N}{V}.m=\\delta \\left(kg/m^3\\right)$","difficultySource":"ai"}}]},{"id":658421,"nq":{"form":"bai_tap","type":"true_false","topic":"Hiện tượng phóng xạ. Chu kì bán rã","question":"Để chụp ảnh PET bên trong cơ thể, người ta tiêm dược chất phóng xạ FDG vào người bệnh. FDG chứa đồng vị  ${}_8^{19}F$ phóng xạ β+ có chu kì bán rã là 110 phút.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046508553-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Tia β+ là dòng các hạt proton.","answer":false},{"text":"Hạt nhân con tạo thành sau khi  ${}_8^{19}F$ phóng xạ β+ có 10 neutron.","answer":true},{"text":"Tỉ số giữa độ phóng xạ ban đầu và số hạt nhân ban đầu của  ${}_8^{19}F$ là 1,05.10<sup>−4</sup>s−1.","answer":true},{"text":"Trước khi chụp ảnh PET, bệnh nhân được tiêm liều lượng FDG thích hợp, tùy theo cân nặng của mỗi người. Giả sử có hai bệnh nhân cùng được tiêm một liều lượng FDG giống nhau và tại thời điểm chẩn đoán, một bệnh nhân có liều lượng  ${}_8^{19}F$ giảm còn 42%, còn bệnh nhân kia có liều lượng   ${}_8^{19}F$ giảm còn 18%. Như vậy, hai bệnh nhân được tiêm dược chất FDG cách nhau 143,5 phút.","answer":false}],"explanation":"a) sai<br>Tia β+ là các dòng hạt positron<br>b) đúng<br>${}_8^{19}F\\rightarrow {}_{+1}^{−0}e+{}_8^{18}X\\Rightarrow X$  có  $18−8=10 neutron$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>$\\begin{aligned}\\end{aligned}\\frac{H_0}{N_0}=\\lambda =\\frac{ln2}{T}=\\frac{ln2}{110.60}\\approx 1,05.10^{−4}.s^{−1}Website: thukhoadaihoc.vn$<br>d) sai<br>$\\begin{aligned}N=N_0.2^{−\\frac{t}{T}}\\Rightarrow \\left\\{\\begin{aligned}0,42=2^{−\\frac{t_1}{T}} <br>0,18=2^{−\\frac{t_2}{T}}\\end{aligned}\\right.\\Rightarrow \\frac{0,42}{0,18}=2^{\\frac{t_2−t_1}{110}}\\Rightarrow t_2−t_1\\approx 134,4phut <br>Website: thukhoadaihoc.vn\\end{aligned}$","difficultySource":"ai"},"ex":[{"exam":379,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Hiện tượng phóng xạ. Chu kì bán rã","question":"Để chụp ảnh PET bên trong cơ thể, người ta tiêm dược chất phóng xạ FDG vào người bệnh. FDG chứa đồng vị  ${}_8^{19}F$ phóng xạ β+ có chu kì bán rã là 110 phút.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046508553-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Tia β+ là dòng các hạt proton.","answer":false},{"text":"Hạt nhân con tạo thành sau khi  ${}_8^{19}F$ phóng xạ β+ có 10 neutron.","answer":true},{"text":"Tỉ số giữa độ phóng xạ ban đầu và số hạt nhân ban đầu của  ${}_8^{19}F$ là 1,05.10<sup>−4</sup>s−1.","answer":true},{"text":"Trước khi chụp ảnh PET, bệnh nhân được tiêm liều lượng FDG thích hợp, tùy theo cân nặng của mỗi người. Giả sử có hai bệnh nhân cùng được tiêm một liều lượng FDG giống nhau và tại thời điểm chẩn đoán, một bệnh nhân có liều lượng  ${}_8^{19}F$ giảm còn 42%, còn bệnh nhân kia có liều lượng   ${}_8^{19}F$ giảm còn 18%. Như vậy, hai bệnh nhân được tiêm dược chất FDG cách nhau 143,5 phút.","answer":false}],"explanation":"a) sai<br>Tia β+ là các dòng hạt positron<br>b) đúng<br>${}_8^{19}F\\rightarrow {}_{+1}^{−0}e+{}_8^{18}X\\Rightarrow X$  có  $18−8=10 neutron$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>$\\begin{aligned}\\end{aligned}\\frac{H_0}{N_0}=\\lambda =\\frac{ln2}{T}=\\frac{ln2}{110.60}\\approx 1,05.10^{−4}.s^{−1}Website: thukhoadaihoc.vn$<br>d) sai<br>$\\begin{aligned}N=N_0.2^{−\\frac{t}{T}}\\Rightarrow \\left\\{\\begin{aligned}0,42=2^{−\\frac{t_1}{T}} <br>0,18=2^{−\\frac{t_2}{T}}\\end{aligned}\\right.\\Rightarrow \\frac{0,42}{0,18}=2^{\\frac{t_2−t_1}{110}}\\Rightarrow t_2−t_1\\approx 134,4phut <br>Website: thukhoadaihoc.vn\\end{aligned}$","difficultySource":"ai"}}]},{"id":659132,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":0,"options":["45g","51g","64g","32g"],"question":"Một bình trụ có thể tích 5.10<sup>3</sup>cm3 chứa khí O2 ở áp suất 8.10<sup>5</sup>Pa. Bình có lỗ rò rỉ nên khí trong bình dần thoát ra ngoài cho đến khi khí trong bình có áp suất bằng áp suất khí quyển. Biết áp suất khí quyển là 1,0. 10<sup>5</sup>Pa. Giả sử nhiệt độ khí được giữ không đổi ở 270. Số gam khí đã thoát ra gần với giá trị nào nhất?","difficulty":"trung-binh","explanation":"$\\frac{pV}{T}=nR=\\frac{m}{M}R$<br>$\\Rightarrow m=\\frac{pVM}{RT}\\Rightarrow \\Delta m=\\frac{\\Delta pVM}{RT}=\\frac{\\left(8−1\\right).10^5.5.10^3.10^{−6}.32}{8,31.\\left(27+273\\right)}\\approx 44,9\\left(g\\right)$","difficultySource":"ai"},"ex":[{"exam":380,"idx":4,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":0,"options":["45g","51g","64g","32g"],"question":"Một bình trụ có thể tích 5.10<sup>3</sup>cm3 chứa khí O2 ở áp suất 8.10<sup>5</sup>Pa. Bình có lỗ rò rỉ nên khí trong bình dần thoát ra ngoài cho đến khi khí trong bình có áp suất bằng áp suất khí quyển. Biết áp suất khí quyển là 1,0. 10<sup>5</sup>Pa. Giả sử nhiệt độ khí được giữ không đổi ở 270. Số gam khí đã thoát ra gần với giá trị nào nhất?","difficulty":"trung-binh","explanation":"$\\frac{pV}{T}=nR=\\frac{m}{M}R$<br>$\\Rightarrow m=\\frac{pVM}{RT}\\Rightarrow \\Delta m=\\frac{\\Delta pVM}{RT}=\\frac{\\left(8−1\\right).10^5.5.10^3.10^{−6}.32}{8,31.\\left(27+273\\right)}\\approx 44,9\\left(g\\right)$","difficultySource":"ai"}}]},{"id":661733,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":2,"options":["2.10<sup>9</sup> hạt.","2.10<sup>8</sup> hạt.","5.10<sup>9</sup> hạt.","5.10<sup>8</sup> hạt."],"question":"Một mẫu chất phóng xạ  ${}_8^{15}O$ có độ phóng xạ 2,8.10<sup>7</sup> Bq. Biết rằng hằng số phóng xạ của  ${}_8^{15}O$ là 5,6.10<sup>−3</sup> s−1. Số hạt nhân chất phóng xạ có trong mẫu khi đó là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Độ phóng xạ của mẫu chất được xác định bởi công thức $H = \\lambda N$, trong đó $\\lambda$ là hằng số phóng xạ và $N$ là số hạt nhân chưa phân rã.</p><p class=\"text-base leading-relaxed my-2\">Suy ra số hạt nhân trong mẫu: $N = \\dfrac{H}{\\lambda}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $N = \\dfrac{2{,}8\\cdot 10^{7}}{5{,}6\\cdot 10^{-3}} = 5\\cdot 10^{9}$ hạt.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: số hạt nhân ${}_8^{15}O$ có trong mẫu là $5\\cdot 10^{9}$ hạt, đáp án C.</p>","difficultySource":"ai"},"ex":[{"exam":382,"idx":1,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":2,"options":["2.10<sup>9</sup> hạt.","2.10<sup>8</sup> hạt.","5.10<sup>9</sup> hạt.","5.10<sup>8</sup> hạt."],"question":"Một mẫu chất phóng xạ  ${}_8^{15}O$ có độ phóng xạ 2,8.10<sup>7</sup> Bq. Biết rằng hằng số phóng xạ của  ${}_8^{15}O$ là 5,6.10<sup>−3</sup> s−1. Số hạt nhân chất phóng xạ có trong mẫu khi đó là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Độ phóng xạ của mẫu chất được xác định bởi công thức $H = \\lambda N$, trong đó $\\lambda$ là hằng số phóng xạ và $N$ là số hạt nhân chưa phân rã.</p><p class=\"text-base leading-relaxed my-2\">Suy ra số hạt nhân trong mẫu: $N = \\dfrac{H}{\\lambda}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $N = \\dfrac{2{,}8\\cdot 10^{7}}{5{,}6\\cdot 10^{-3}} = 5\\cdot 10^{9}$ hạt.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: số hạt nhân ${}_8^{15}O$ có trong mẫu là $5\\cdot 10^{9}$ hạt, đáp án C.</p>","difficultySource":"ai"}}]},{"id":661761,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":3,"options":["0,5 mol.","0,7 mol.","0,6 mol.","0,4 mol."],"question":"Một khối khí lí tưởng với áp suất là 2.10<sup>5</sup> Pa, thể tích là 5 lít, nhiệt độ 250C. Số mol của khối khí lí tưởng là","difficulty":"de","explanation":"$n=\\frac{pV}{RT}=\\frac{2.10^5.5.10^{−3}}{8,31.\\left(25+273\\right)}\\approx 0,4\\left(mol\\right)$","difficultySource":"ai"},"ex":[{"exam":382,"idx":13,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":3,"options":["0,5 mol.","0,7 mol.","0,6 mol.","0,4 mol."],"question":"Một khối khí lí tưởng với áp suất là 2.10<sup>5</sup> Pa, thể tích là 5 lít, nhiệt độ 250C. Số mol của khối khí lí tưởng là","difficulty":"de","explanation":"$n=\\frac{pV}{RT}=\\frac{2.10^5.5.10^{−3}}{8,31.\\left(25+273\\right)}\\approx 0,4\\left(mol\\right)$","difficultySource":"ai"}}]},{"id":661771,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"345","question":"Một bình chứa 40,0dm3 carbon dioxide (CO2) có áp suất 4,8.10<sup>5</sup> Pa ở nhiệt độ 21,660C. Biết khối lượng mol của CO2 là 44 g/mol. Khối lượng CO2 trong bình là x . Tìm giá trị của x (làm tròn kết quả đến chữ số hàng đơn vị).","difficulty":"trung-binh","explanation":"$\\frac{pV}{T}=nR\\Rightarrow \\frac{4,8.10^5.40.10^{−3}}{21,66+273}=n.8,31\\Rightarrow n\\approx 7,84$<br>$m=nM=7,84.44\\approx 345g$","difficultySource":"ai"},"ex":[{"exam":382,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"345","question":"Một bình chứa 40,0dm3 carbon dioxide (CO2) có áp suất 4,8.10<sup>5</sup> Pa ở nhiệt độ 21,660C. Biết khối lượng mol của CO2 là 44 g/mol. Khối lượng CO2 trong bình là x . Tìm giá trị của x (làm tròn kết quả đến chữ số hàng đơn vị).","difficulty":"trung-binh","explanation":"$\\frac{pV}{T}=nR\\Rightarrow \\frac{4,8.10^5.40.10^{−3}}{21,66+273}=n.8,31\\Rightarrow n\\approx 7,84$<br>$m=nM=7,84.44\\approx 345g$","difficultySource":"ai"}}]},{"id":661773,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"5280","question":"Một lượng khí trong một xilanh hình trụ được nung nóng, khí nở ra đẩy pit-tông lên làm thể tích tăng thêm 0,02 m3 và nội năng tăng thêm 1280 J. Biết áp suất của khối khí là 2.10<sup>5</sup> Pa và không đổi trong quá trình dãn nở. Nhiệt lượng đã truyền cho khí bằng bao nhiêu joule (J) (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"$A=−p\\Delta V=−2.10^5.0,02=−4000J$<br>$\\Delta U=Q+A\\Rightarrow 1280=Q−4000\\Rightarrow Q=5280J$","difficultySource":"ai"},"ex":[{"exam":382,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"5280","question":"Một lượng khí trong một xilanh hình trụ được nung nóng, khí nở ra đẩy pit-tông lên làm thể tích tăng thêm 0,02 m3 và nội năng tăng thêm 1280 J. Biết áp suất của khối khí là 2.10<sup>5</sup> Pa và không đổi trong quá trình dãn nở. Nhiệt lượng đã truyền cho khí bằng bao nhiêu joule (J) (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"$A=−p\\Delta V=−2.10^5.0,02=−4000J$<br>$\\Delta U=Q+A\\Rightarrow 1280=Q−4000\\Rightarrow Q=5280J$","difficultySource":"ai"}}]},{"id":662642,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng áp và định luật Charles","answer":2,"options":["265.","248.","233.","235."],"question":"Để mở nút chai bị kẹt, người ta hơ nóng khí trong chai. Biết rằng khí trong chai lúc chưa hơ nóng có áp suất bằng với áp suất khí quyển và bằng 1, 0.10<sup>5</sup> Pa và nhiệt độ 8,00C. Để đẩy được nút chai ra cần có chênh lệch áp suất giữa khí trong chai và bên ngoài là 0,8.105 Pa. Cần hơ để khí trong chai nóng đến nhiệt độ thấp nhất bao nhiêu độ (0C) để nút chai bật ra.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046549431-hinh-4.jpg\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Đẳng tích  $\\Rightarrow \\frac{p}{T}=const\\Rightarrow \\frac{10^5}{8+273}=\\frac{10^5+0,8.10^5}{T}\\Rightarrow T\\approx 506K=233^0C$","difficultySource":"ai"},"ex":[{"exam":383,"idx":12,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng áp và định luật Charles","answer":2,"options":["265.","248.","233.","235."],"question":"Để mở nút chai bị kẹt, người ta hơ nóng khí trong chai. Biết rằng khí trong chai lúc chưa hơ nóng có áp suất bằng với áp suất khí quyển và bằng 1, 0.10<sup>5</sup> Pa và nhiệt độ 8,00C. Để đẩy được nút chai ra cần có chênh lệch áp suất giữa khí trong chai và bên ngoài là 0,8.105 Pa. Cần hơ để khí trong chai nóng đến nhiệt độ thấp nhất bao nhiêu độ (0C) để nút chai bật ra.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046549431-hinh-4.jpg\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Đẳng tích  $\\Rightarrow \\frac{p}{T}=const\\Rightarrow \\frac{10^5}{8+273}=\\frac{10^5+0,8.10^5}{T}\\Rightarrow T\\approx 506K=233^0C$","difficultySource":"ai"}}]},{"id":662643,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":1,"options":["12.10<sup>−3</sup> V.","1,2.10<sup>−3</sup> V.","2,2.10<sup>−3</sup> V.","22.10<sup>−3</sup> V."],"question":"Một vòng dây dẫn phẳng hình tròn có diện tích S = 60 cm2 được đặt trong một từ trường đều có B = 0,2 T. Trong 0,5 s vòng dây quay đều được một góc 60° như hình bên. Độ lớn suất điện động cảm ứng trung bình trong vòng dây là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046549848-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$e=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\left|\\frac{BS\\left(cos\\alpha_2−cos\\alpha_1\\right)}{\\Delta t}\\right|=\\left|\\frac{0,2.60.10^{−4}.\\left(cos60^0−cos0^0\\right)}{0,5}\\right|=1,2.10^{−3}V$","difficultySource":"ai"},"ex":[{"exam":383,"idx":13,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":1,"options":["12.10<sup>−3</sup> V.","1,2.10<sup>−3</sup> V.","2,2.10<sup>−3</sup> V.","22.10<sup>−3</sup> V."],"question":"Một vòng dây dẫn phẳng hình tròn có diện tích S = 60 cm2 được đặt trong một từ trường đều có B = 0,2 T. Trong 0,5 s vòng dây quay đều được một góc 60° như hình bên. Độ lớn suất điện động cảm ứng trung bình trong vòng dây là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046549848-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$e=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\left|\\frac{BS\\left(cos\\alpha_2−cos\\alpha_1\\right)}{\\Delta t}\\right|=\\left|\\frac{0,2.60.10^{−4}.\\left(cos60^0−cos0^0\\right)}{0,5}\\right|=1,2.10^{−3}V$","difficultySource":"ai"}}]},{"id":662647,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật phóng xạ và chu kì bán rã","answer":1,"options":["15 phút.","10 phút.","60 giây.","150 giây."],"question":"Một mẫu magnesium có độ phóng xạ tại thời điểm t1 là 2,4. 10<sup>6</sup> Bq. Vào lúc thời điểm t2, độ phóng xạ của mẫu magnesium đó là 8.10<sup>5</sup> Bq. Số hạt nhân bị phân rã từ thời điểm t1 đến thời điểm t2 là 13, 85.108 hạt nhân. Chu kì bán rã của magnesium xấp xỉ bằng","difficulty":"kho","explanation":"$\\Delta N=N_1−N_2=\\frac{H_1}{\\lambda }−\\frac{H_2^/}{\\lambda }\\Rightarrow \\lambda =\\frac{H_1−H_2}{\\Delta N}=\\frac{2,4.10^6−8.10^5}{13,85.10^8}\\approx 1,155.10^{−3}.s^{−1}$<br>$\\Rightarrow T=\\frac{ln2}{\\lambda }\\approx 600s\\approx 10ph$","difficultySource":"ai"},"ex":[{"exam":383,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật phóng xạ và chu kì bán rã","answer":1,"options":["15 phút.","10 phút.","60 giây.","150 giây."],"question":"Một mẫu magnesium có độ phóng xạ tại thời điểm t1 là 2,4. 10<sup>6</sup> Bq. Vào lúc thời điểm t2, độ phóng xạ của mẫu magnesium đó là 8.10<sup>5</sup> Bq. Số hạt nhân bị phân rã từ thời điểm t1 đến thời điểm t2 là 13, 85.108 hạt nhân. Chu kì bán rã của magnesium xấp xỉ bằng","difficulty":"kho","explanation":"$\\Delta N=N_1−N_2=\\frac{H_1}{\\lambda }−\\frac{H_2^/}{\\lambda }\\Rightarrow \\lambda =\\frac{H_1−H_2}{\\Delta N}=\\frac{2,4.10^6−8.10^5}{13,85.10^8}\\approx 1,155.10^{−3}.s^{−1}$<br>$\\Rightarrow T=\\frac{ln2}{\\lambda }\\approx 600s\\approx 10ph$","difficultySource":"ai"}}]},{"id":662657,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"0,94","question":"Mỗi phản ứng nhiệt hạch   ${}_1^2D+{}_1^2D\\rightarrow {}_2^3He+{}_0^1n$ + 10n toả ra 17,6MeV. Nước biển có chứa 0,0150% nước nặng D2O là nhiên liệu cho phản ứng nhiệt hạch trên. Khi tổng hợp  ${}_2^3He$  từ 2,00 kg nước biển bằng phản ứng trên thì năng lượng toả ra tương đương đốt cháy hoàn toàn a (tấn) than đá. Biết mỗi kg than đá đốt cháy hoàn toàn toả ra năng lượng 27,0.10<sup>6</sup> J. Lấy khối lượng mol của D2O là 20,0 g/mol. Giá trị của a là bao nhiêu (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"kho","explanation":"$m_{D_2O}=\\frac{0,015}{100}.2000=0,3g$<br>$n_{D_2O}=\\frac{m_{D_2O}}{M_{D_2O}}=\\frac{0,3}{20}=0,015 mol$<br>$n_D=2n_{D_2O}=2.0,015=0,03mol$<br>$N_D=n_DN_A=0,03.6,02.10^{23}=1,806.10^{22}$<br>$N=\\frac{N_D}{2}=\\frac{1,806.10^{22}}{2}=9,03.10^{21}$<br>$Q=N\\Delta E=9,03.10^{21}.17,6.1,6.10^{−13}\\approx 2,543.10^{10}J$<br>$m=\\frac{Q}{q}=\\frac{2,543.10^{10}}{27.10^6}\\approx 942kg=0,94$  tấn","difficultySource":"ai"},"ex":[{"exam":383,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"0,94","question":"Mỗi phản ứng nhiệt hạch   ${}_1^2D+{}_1^2D\\rightarrow {}_2^3He+{}_0^1n$ + 10n toả ra 17,6MeV. Nước biển có chứa 0,0150% nước nặng D2O là nhiên liệu cho phản ứng nhiệt hạch trên. Khi tổng hợp  ${}_2^3He$  từ 2,00 kg nước biển bằng phản ứng trên thì năng lượng toả ra tương đương đốt cháy hoàn toàn a (tấn) than đá. Biết mỗi kg than đá đốt cháy hoàn toàn toả ra năng lượng 27,0.10<sup>6</sup> J. Lấy khối lượng mol của D2O là 20,0 g/mol. Giá trị của a là bao nhiêu (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"kho","explanation":"$m_{D_2O}=\\frac{0,015}{100}.2000=0,3g$<br>$n_{D_2O}=\\frac{m_{D_2O}}{M_{D_2O}}=\\frac{0,3}{20}=0,015 mol$<br>$n_D=2n_{D_2O}=2.0,015=0,03mol$<br>$N_D=n_DN_A=0,03.6,02.10^{23}=1,806.10^{22}$<br>$N=\\frac{N_D}{2}=\\frac{1,806.10^{22}}{2}=9,03.10^{21}$<br>$Q=N\\Delta E=9,03.10^{21}.17,6.1,6.10^{−13}\\approx 2,543.10^{10}J$<br>$m=\\frac{Q}{q}=\\frac{2,543.10^{10}}{27.10^6}\\approx 942kg=0,94$  tấn","difficultySource":"ai"}}]},{"id":663895,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":0,"options":["5 m.","180 m.","18 m.","50 m."],"question":"Sóng điện từ có tần số 60 MHz truyền trong chân không với tốc độ 3.10<sup>8</sup> m/s thì có bước sóng là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Bước sóng của sóng điện từ trong chân không được xác định bởi hệ thức $\\lambda = \\dfrac{c}{f}$, trong đó $c$ là tốc độ truyền sóng trong chân không và $f$ là tần số.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $c = 3\\cdot 10^{8}\\ \\text{m/s}$ và $f = 60\\ \\text{MHz} = 60\\cdot 10^{6}\\ \\text{Hz}$:</p><p class=\"text-base leading-relaxed my-2\">$\\lambda = \\dfrac{3\\cdot 10^{8}}{60\\cdot 10^{6}} = 5\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">Vậy bước sóng là $5\\ \\text{m}$, đáp án <strong>A</strong>.</p>","difficultySource":"ai"},"ex":[{"exam":384,"idx":11,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":0,"options":["5 m.","180 m.","18 m.","50 m."],"question":"Sóng điện từ có tần số 60 MHz truyền trong chân không với tốc độ 3.10<sup>8</sup> m/s thì có bước sóng là","difficulty":"de","explanation":"$\\lambda =\\frac{v}{f}=\\frac{3.10^8}{60.10^6}=5m$","difficultySource":"ai"}}]},{"id":663900,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":0,"options":["6,5. 10<sup>−2</sup> T.","6,5. 10<sup>−3</sup> T.","5, 6.10<sup>−2</sup> T.","5,6.10<sup>−3</sup>T."],"question":"Một đoạn dây dẫn thẳng bằng đồng đặt nằm ngang vuông góc với từ trường đều có véc tơ cảm ứng từ nằm ngang. Trong đoạn dây có dòng điện có cường độ 7,0 A ở trong từ trường đều. Bỏ qua ảnh hưởng của từ trường Trái Đất lên đoạn dây. Biết khối lượng của một đơn vị chiều dài của đoạn dây đồng là 46,6.10<sup>−3</sup> kg/m; lấy g = 9,8 $m/s^2$. Độ lớn của cảm ứng từ để lực từ cân bằng với lực hút Trái Đất tác dụng lên đoạn dây là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Dây nằm ngang vuông góc với $\\vec B$ nằm ngang, để lực từ cân bằng trọng lực thì $F = P$, tức $BI\\ell = mg$, nên $B = \\dfrac{mg}{I\\ell} = \\dfrac{(m/\\ell)g}{I}$.</p><p class=\"text-base leading-relaxed my-2\">Khối lượng trên một đơn vị chiều dài $\\dfrac{m}{\\ell} = 46{,}6\\cdot 10^{-3}\\ \\mathrm{kg/m}$.</p><p class=\"text-base leading-relaxed my-2\">$B = \\dfrac{46{,}6\\cdot 10^{-3}\\cdot 9{,}8}{7{,}0}\\approx 6{,}5\\cdot 10^{-2}\\ \\mathrm{T}$.</p><p class=\"text-base leading-relaxed my-2\">Sai vì: B ($6{,}5\\cdot 10^{-3}$ T) nhỏ hơn 10 lần kết quả, ra khi nhầm bậc của $46{,}6\\cdot 10^{-3}$. C và D ($5{,}6\\cdot 10^{-2}$ T, $5{,}6\\cdot 10^{-3}$ T) không đúng vì $\\dfrac{0{,}0466\\cdot 9{,}8}{7} = 0{,}0652$ chứ không phải $0{,}056$.</p><p class=\"text-base leading-relaxed my-2\">Chọn A.</p>","difficultySource":"ai"},"ex":[{"exam":384,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":0,"options":["6,5. 10<sup>−2</sup> T.","6,5. 10<sup>−3</sup> T.","5, 6.10<sup>−2</sup> T.","5,6.10<sup>−3</sup>T."],"question":"Một đoạn dây dẫn thẳng bằng đồng đặt nằm ngang vuông góc với từ trường đều có véc tơ cảm ứng từ nằm ngang. Trong đoạn dây có dòng điện có cường độ 7,0 A ở trong từ trường đều. Bỏ qua ảnh hưởng của từ trường Trái Đất lên đoạn dây. Biết khối lượng của một đơn vị chiều dài của đoạn dây đồng là 46,6.10<sup>−3</sup> kg/m; lấy g = 9,8 m/s2. Độ lớn của cảm ứng từ để lực từ cân bằng với lực hút Trái Đất tác dụng lên đoạn dây là","difficulty":"de","explanation":"$F=P\\Rightarrow IℓI=mg\\Rightarrow B=\\frac{mg}{ℓI}=\\frac{46,6.10^{−3}.9,8}{7}\\approx 6,5.10^{−2}T$","difficultySource":"ai"}}]},{"id":663910,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Hình bên là ngôi nhà dã chiến do Quân đội nhân dân Việt Nam sản xuất. Các cột trụ và thanh đỡ của ngôi nhà được làm bằng các ống cao su rỗng nối thông với nhau tạo thành. Để dựng nhà thì ta cần bơm khí vào để làm căng cứng các ống cao su. Tổng thể tích của các ống cao su là<br>1,4 m3. Người ta dùng máy bơm có công suất bơm là 1 lít/s để bơm không khí vào. Xem nhiệt độ của khối khí bơm vào thay đổi không đáng kể; nhiệt độ khối khí trong các ống luôn bằng nhiệt độ ngoài trời và bỏ qua sự dãn nở vì nhiệt của các ống cao su. Biết không khí được bơm vào có áp suất 105 Pa ở nhiệt độ 270C và ban đầu trong các ống chưa có khí. Để ngôi nhà được vững chắc thì áp suất khối khí trong các ống cao su phải là 6.10<sup>5</sup> Pa.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046557826-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Lượng khí được bơm vào trong mỗi giây có số mol xấp xỉ bằng 0,04 mol.","answer":true},{"text":"Thể tích khí ở áp suất 105 Pa đã bơm vào cho đến khi áp suất khối khí đạt 6.10<sup>5</sup> Pa là 8,4 m3.","answer":true},{"text":"Thời gian bơm khí kể từ thời điểm bắt đầu bơm đến khi áp suất khối khí đạt 6.10<sup>5</sup> Pa là 140 phút.","answer":true},{"text":"Khi nhiệt độ ngoài trời tăng đến 370C thì áp suất khối khí trong các ống cao su là 6,2.10<sup>5</sup> Pa.","answer":true}],"explanation":"a) đúng<br>$\\begin{aligned}\\end{aligned}n_0=\\frac{pV_0}{RT}=\\frac{10^5.10^{−3}}{8,31.\\left(27+273\\right)}\\approx 0,04molWebsite: thukhoadaihoc.vn$<br>b) đúng<br>$pV=p^/V^/\\Rightarrow 10^5.V=6.10^5.1,4\\Rightarrow V=8,4m^3$<br>c) đúng<br>$t=8,4.10^3s=140$  phút<br>d) đúng<br>Đẳng tích  $\\frac{p^/}{T^/}=\\frac{p^{//}}{T^{//}}\\Rightarrow \\frac{6.10^5}{27+273}=\\frac{p^{//}}{37+273}\\Rightarrow p^{//}=6,2.10^5Pa$","difficultySource":"ai"},"ex":[{"exam":384,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Hình bên là ngôi nhà dã chiến do Quân đội nhân dân Việt Nam sản xuất. Các cột trụ và thanh đỡ của ngôi nhà được làm bằng các ống cao su rỗng nối thông với nhau tạo thành. Để dựng nhà thì ta cần bơm khí vào để làm căng cứng các ống cao su. Tổng thể tích của các ống cao su là<br>1,4 m3. Người ta dùng máy bơm có công suất bơm là 1 lít/s để bơm không khí vào. Xem nhiệt độ của khối khí bơm vào thay đổi không đáng kể; nhiệt độ khối khí trong các ống luôn bằng nhiệt độ ngoài trời và bỏ qua sự dãn nở vì nhiệt của các ống cao su. Biết không khí được bơm vào có áp suất 105 Pa ở nhiệt độ 270C và ban đầu trong các ống chưa có khí. Để ngôi nhà được vững chắc thì áp suất khối khí trong các ống cao su phải là 6.10<sup>5</sup> Pa.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046557826-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Lượng khí được bơm vào trong mỗi giây có số mol xấp xỉ bằng 0,04 mol.","answer":true},{"text":"Thể tích khí ở áp suất 105 Pa đã bơm vào cho đến khi áp suất khối khí đạt 6.10<sup>5</sup> Pa là 8,4 m3.","answer":true},{"text":"Thời gian bơm khí kể từ thời điểm bắt đầu bơm đến khi áp suất khối khí đạt 6.10<sup>5</sup> Pa là 140 phút.","answer":true},{"text":"Khi nhiệt độ ngoài trời tăng đến 370C thì áp suất khối khí trong các ống cao su là 6,2.10<sup>5</sup> Pa.","answer":true}],"explanation":"a) đúng<br>$\\begin{aligned}\\end{aligned}n_0=\\frac{pV_0}{RT}=\\frac{10^5.10^{−3}}{8,31.\\left(27+273\\right)}\\approx 0,04molWebsite: thukhoadaihoc.vn$<br>b) đúng<br>$pV=p^/V^/\\Rightarrow 10^5.V=6.10^5.1,4\\Rightarrow V=8,4m^3$<br>c) đúng<br>$t=8,4.10^3s=140$  phút<br>d) đúng<br>Đẳng tích  $\\frac{p^/}{T^/}=\\frac{p^{//}}{T^{//}}\\Rightarrow \\frac{6.10^5}{27+273}=\\frac{p^{//}}{37+273}\\Rightarrow p^{//}=6,2.10^5Pa$","difficultySource":"ai"}}]},{"id":665049,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Trong vật lý hạt nhân, máy đo phóng xạ (máy đếm/ống đếm) Geiger-Muller được sử dụng rộng rãi trong việc đo số lượng hạt α, β bằng cách ứng dụng khả năng ion hoá của các tia phóng xạ này. Xét hai máy đếm Geiger-Muller giống nhau lần lượt được chiếu xạ bởi hai mẫu chất phóng xạ  ${}_{84}^{210}Po$  và  ${}_{53}^{131}I$  (mỗi hạt nhân khi phân rã chỉ phát ra một tia phóng xạ). Biết rằng các mẫu chất phóng xạ được đặt ở cùng một khoảng cách so với các máy đếm tại hai phòng khác nhau. Cho khối lượng của từng mẫu phóng xạ tại thời điểm ban đầu đều bằng 1,5 g. Biết khối lượng mol nguyên tử của  ${}_{84}^{210}Po$ và  ${}_{53}^{131}I$ lần lượt là 210 g/mol và 131 g/mol. Chu kì bán rã của  ${}_{84}^{210}Po$ và  ${}_{53}^{131}I$ lần lượt là 138,4 ngày và 8,02 ngày.","difficulty":"kho","statements":[{"text":"Ban đầu, số nguyên tử  ${}_{84}^{210}Po$  có trong 1,5 g là 4,3.10<sup>21</sup> nguyên tử.","answer":true},{"text":"Số lượng hạt nhân  ${}_{53}^{131}I$ phân rã trong vòng 1 ngày đầu tiên xấp xỉ bằng 6,3.10<sup>21</sup> hạt.","answer":false},{"text":"Sau 1 ngày đầu tiên, máy đo phóng xạ ứng với mẫu chất chứa  ${}_{53}^{131}I$ đếm được nhiều tín hiệu hơn mẫu chất chứa  ${}_{84}^{210}Po$","answer":true},{"text":"Độ phóng xạ của hạt nhân  ${}_{53}^{131}I$ sau 1 ngày đầu tiên xấp xỉ bằng 2,14.10<sup>19</sup> Bq.","answer":false}],"explanation":"a) đúng<br>$n_{Po}=\\frac{m}{M_{Po}}=\\frac{1,5}{210}=\\frac{1}{140}mol$<br>$N_{Po}=n_{Po}N_A=\\frac{1}{140}.6,02.10^{23}=4,3.10^{21}$<br>b) sai<br>$n_I=\\frac{m}{M_I}=\\frac{1,5}{131}=\\frac{3}{262}mol$<br>$N_I=n_IN_A=\\frac{3}{262}.6,02.10^{23}\\approx 6,9.10^{21}$<br>$\\Delta N_I=N_I\\left(1−2^{−\\frac{t}{T_I}}\\right)=6,9.10^{21}.\\left(1−2^{−\\frac{1}{8,02}}\\right)\\approx 5,7.10^{20}$<br>c) đúng<br>$\\Delta N_{Po}=N_{Po}\\left(1−2^{\\frac{−t}{T_{Po}}}\\right)=4,3.10^{21}.\\left(1−2^{\\frac{−1}{138,4}}\\right)\\approx 2,15.10^{19}<\\Delta N_I$<br>d) sai<br>$H_I=\\lambda_I.N_I.2^{−\\frac{t}{T_I}}=\\frac{ln2}{8,02.24.60.60}.6,9.10^{21}.2^{−\\frac{1}{8,02}}\\approx 6,33.10^{15}$","difficultySource":"ai"},"ex":[{"exam":385,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Trong vật lý hạt nhân, máy đo phóng xạ (máy đếm/ống đếm) Geiger-Muller được sử dụng rộng rãi trong việc đo số lượng hạt α, β bằng cách ứng dụng khả năng ion hoá của các tia phóng xạ này. Xét hai máy đếm Geiger-Muller giống nhau lần lượt được chiếu xạ bởi hai mẫu chất phóng xạ  ${}_{84}^{210}Po$  và  ${}_{53}^{131}I$  (mỗi hạt nhân khi phân rã chỉ phát ra một tia phóng xạ). Biết rằng các mẫu chất phóng xạ được đặt ở cùng một khoảng cách so với các máy đếm tại hai phòng khác nhau. Cho khối lượng của từng mẫu phóng xạ tại thời điểm ban đầu đều bằng 1,5 g. Biết khối lượng mol nguyên tử của  ${}_{84}^{210}Po$ và  ${}_{53}^{131}I$ lần lượt là 210 g/mol và 131 g/mol. Chu kì bán rã của  ${}_{84}^{210}Po$ và  ${}_{53}^{131}I$ lần lượt là 138,4 ngày và 8,02 ngày.","difficulty":"kho","statements":[{"text":"Ban đầu, số nguyên tử  ${}_{84}^{210}Po$  có trong 1,5 g là 4,3.10<sup>21</sup> nguyên tử.","answer":true},{"text":"Số lượng hạt nhân  ${}_{53}^{131}I$ phân rã trong vòng 1 ngày đầu tiên xấp xỉ bằng 6,3.10<sup>21</sup> hạt.","answer":false},{"text":"Sau 1 ngày đầu tiên, máy đo phóng xạ ứng với mẫu chất chứa  ${}_{53}^{131}I$ đếm được nhiều tín hiệu hơn mẫu chất chứa  ${}_{84}^{210}Po$","answer":true},{"text":"Độ phóng xạ của hạt nhân  ${}_{53}^{131}I$ sau 1 ngày đầu tiên xấp xỉ bằng 2,14.10<sup>19</sup> Bq.","answer":false}],"explanation":"a) đúng<br>$n_{Po}=\\frac{m}{M_{Po}}=\\frac{1,5}{210}=\\frac{1}{140}mol$<br>$N_{Po}=n_{Po}N_A=\\frac{1}{140}.6,02.10^{23}=4,3.10^{21}$<br>b) sai<br>$n_I=\\frac{m}{M_I}=\\frac{1,5}{131}=\\frac{3}{262}mol$<br>$N_I=n_IN_A=\\frac{3}{262}.6,02.10^{23}\\approx 6,9.10^{21}$<br>$\\Delta N_I=N_I\\left(1−2^{−\\frac{t}{T_I}}\\right)=6,9.10^{21}.\\left(1−2^{−\\frac{1}{8,02}}\\right)\\approx 5,7.10^{20}$<br>c) đúng<br>$\\Delta N_{Po}=N_{Po}\\left(1−2^{\\frac{−t}{T_{Po}}}\\right)=4,3.10^{21}.\\left(1−2^{\\frac{−1}{138,4}}\\right)\\approx 2,15.10^{19}<\\Delta N_I$<br>d) sai<br>$H_I=\\lambda_I.N_I.2^{−\\frac{t}{T_I}}=\\frac{ln2}{8,02.24.60.60}.6,9.10^{21}.2^{−\\frac{1}{8,02}}\\approx 6,33.10^{15}$","difficultySource":"ai"}}]},{"id":665052,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một khối khí lí tưởng được chứa trong một xilanh có pit-tông di chuyển được (như hình bên), pit-tông có khối lượng 200 g, tiết diện 25 cm2. Ban đầu khối khí có nhiệt độ 270C và pit-tông cách đáy xilanh 18 cm. Người ta cung cấp nhiệt lượng cho khối khí đều đặn, khối khí nở ra và đẩy pittông di chuyển một đoạn thì ngừng cung cấp nhiệt lượng. Sau đó pit-tông ngừng chuyển động và cách vị trí ban đầu 6 cm. Biết lực ma sát giữa pittông và xilanh không đáng kể, áp suất khí quyển là 105 Pa. Lấy gia tốc trọng trường g = 10 $m/s^2$.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046567683-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Áp suất khí trong xilanh lúc đầu nhỏ hơn áp suất khí trong xilanh khi pit-tông cách vị trí ban đầu 6 cm.","answer":false},{"text":"Ban đầu áp suất của khối khí trong xilanh là 100,8.10<sup>3</sup> Pa.","answer":true},{"text":"Khi pit-tông cách vị trí ban đầu 6 cm, nhiệt độ khối khí là 4000C.","answer":false},{"text":"Số mol khí chứa trong xilanh xấp xỉ bằng 0,2 mol.","answer":false}],"explanation":"a) sai<br>Đều bằng  $p=p_0+\\frac{mg}{S}=10^5+\\frac{0,2.10}{25.10^{−4}}=100800Pa$<br>b) đúng<br>$p=100,8.10^3Pa$<br>c) sai<br>Đẳng áp $\\frac{V}{T}=const\\Rightarrow \\frac{S.18}{27+273}=\\frac{S.\\left(18−6\\right)}{T}\\Rightarrow T=200K$<br>d) sai<br>$\\frac{pV}{T}=nR\\Rightarrow \\frac{100800.25.10^{−4}.0,18}{27+273}=n.8,31\\Rightarrow n\\approx 0,02\\left(mol\\right)$","difficultySource":"ai"},"ex":[{"exam":385,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một khối khí lí tưởng được chứa trong một xilanh có pit-tông di chuyển được (như hình bên), pit-tông có khối lượng 200 g, tiết diện 25 cm2. Ban đầu khối khí có nhiệt độ 270C và pit-tông cách đáy xilanh 18 cm. Người ta cung cấp nhiệt lượng cho khối khí đều đặn, khối khí nở ra và đẩy pittông di chuyển một đoạn thì ngừng cung cấp nhiệt lượng. Sau đó pit-tông ngừng chuyển động và cách vị trí ban đầu 6 cm. Biết lực ma sát giữa pittông và xilanh không đáng kể, áp suất khí quyển là 105 Pa. Lấy gia tốc trọng trường g = 10 m/s2.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046567683-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Áp suất khí trong xilanh lúc đầu nhỏ hơn áp suất khí trong xilanh khi pit-tông cách vị trí ban đầu 6 cm.","answer":false},{"text":"Ban đầu áp suất của khối khí trong xilanh là 100,8.10<sup>3</sup> Pa.","answer":true},{"text":"Khi pit-tông cách vị trí ban đầu 6 cm, nhiệt độ khối khí là 4000C.","answer":false},{"text":"Số mol khí chứa trong xilanh xấp xỉ bằng 0,2 mol.","answer":false}],"explanation":"a) sai<br>Đều bằng  $p=p_0+\\frac{mg}{S}=10^5+\\frac{0,2.10}{25.10^{−4}}=100800Pa$<br>b) đúng<br>$p=100,8.10^3Pa$<br>c) sai<br>Đẳng áp $\\frac{V}{T}=const\\Rightarrow \\frac{S.18}{27+273}=\\frac{S.\\left(18−6\\right)}{T}\\Rightarrow T=200K$<br>d) sai<br>$\\frac{pV}{T}=nR\\Rightarrow \\frac{100800.25.10^{−4}.0,18}{27+273}=n.8,31\\Rightarrow n\\approx 0,02\\left(mol\\right)$","difficultySource":"ai"}}]},{"id":665056,"nq":{"form":"bai_tap","type":"short_answer","topic":"Lực từ tác dụng lên khung dây. Ngẫu lực từ","answer":"1,25","question":"Mô hình động cơ điện sử dụng dòng điện không đổi như hình bên dưới. Khung dây được đặt trong từ trường đều của nam châm. Khi cho dòng điện không đổi qua khung dây thì khung dây sẽ quay dưới tác dụng của lực từ. Biết khung dây có 100 vòng dây, diện tích khung dây 50 cm2 và dòng điện qua khung dây là 5A. Từ trường đều do nam châm tạo ra có độ lớn cảm ứng từ 0,5 T. Momen ngẫu lực từ cực đại của khung dây có độ lớn bao nhiêu N.m?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046567864-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"Công thức: momen ngẫu lực từ cực đại tác dụng lên khung dây N vòng, diện tích S, dòng điện I, đặt trong từ trường đều B: Mmax = N.B.I.S.<br>Thay số: N = 100, B = 0,5 T, I = 5 A, S = 50 cm² = 50.10^-4 m² = 5.10^-3 m² → Mmax = 100 . 0,5 . 5 . 5.10^-3 = 1,25 N.m.<br>Kết quả: Đáp số: Mmax = 1,25 N.m.<br>$M=NIBS=100.5.0,5.50.10^{−4}=1,25Nm$<br>Sử dụng các thông tin sau cho câu 5 và câu 6: Để chế tạo tritium ( ${}_1^3T$ ) dùng cho lò phản ứng nhiệt hạch lớn người ta sử dụng phản ứng tổng hợp hai hạt nhân deuterium ( ${}_1^2D$ ). Phản ứng này có thể xảy ra 2 trường hợp sau:<br>${}_1^2D+{}_1^2D\\rightarrow {}_1^3T+p$ tỏa ra năng lượng 4,03 MeV.<br>${}_1^2D+{}_1^2D\\rightarrow {}_2^3He+n$ tỏa ra năng lượng 3,27 MeV.<br>Theo điều kiện lí tưởng, khả năng xảy ra của mỗi phản ứng trên là 50 % và chỉ 1 % số  ${}_1^2D$  tham gia phản ứng trong tổng khối lượng  ${}_1^2D$  được sử dụng. Có thể tìm thấy  ${}_1^2D$  trong nước biển và mỗi mét khối nước biển có 33 gam  ${}_1^2D$ . Khối lượng riêng nước biển trung bình là 1025 kg/m3. Cho 1 eV = 1,6.10<sup>−19</sup>J. Khối lượng mol nguyên tử của  ${}_1^2D$  và  ${}_1^3T$  lần lượt là 2 g/mol và 3 g/mol. Người ta sử dụng 5 tấn nước biển để tạo ra  ${}_1^2D$  dùng cho phản ứng nêu trên.<br>Sử dụng các thông tin sau cho câu 5 và câu 6: Để chế tạo tritium ( ${}_1^3T$ ) dùng cho lò phản ứng nhiệt hạch lớn người ta sử dụng phản ứng tổng hợp hai hạt nhân deuterium ( ${}_1^2D$ ). Phản ứng này có thể xảy ra 2 trường hợp sau:<br>${}_1^2D+{}_1^2D\\rightarrow {}_1^3T+p$ tỏa ra năng lượng 4,03 MeV.<br>${}_1^2D+{}_1^2D\\rightarrow {}_2^3He+n$ tỏa ra năng lượng 3,27 MeV.<br>Theo điều kiện lí tưởng, khả năng xảy ra của mỗi phản ứng trên là 50 % và chỉ 1 % số  ${}_1^2D$  tham gia phản ứng trong tổng khối lượng  ${}_1^2D$  được sử dụng. Có thể tìm thấy  ${}_1^2D$  trong nước biển và mỗi mét khối nước biển có 33 gam  ${}_1^2D$ . Khối lượng riêng nước biển trung bình là 1025 kg/m3. Cho 1 eV = 1,6.10<sup>−19</sup>J. Khối lượng mol nguyên tử của  ${}_1^2D$  và  ${}_1^3T$  lần lượt là 2 g/mol và 3 g/mol. Người ta sử dụng 5 tấn nước biển để tạo ra  ${}_1^2D$  dùng cho phản ứng nêu trên.","difficultySource":"ai"},"ex":[{"exam":385,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Lực từ tác dụng lên khung dây. Ngẫu lực từ","answer":"1,25","question":"Mô hình động cơ điện sử dụng dòng điện không đổi như hình bên dưới. Khung dây được đặt trong từ trường đều của nam châm. Khi cho dòng điện không đổi qua khung dây thì khung dây sẽ quay dưới tác dụng của lực từ. Biết khung dây có 100 vòng dây, diện tích khung dây 50 cm2 và dòng điện qua khung dây là 5A. Từ trường đều do nam châm tạo ra có độ lớn cảm ứng từ 0,5 T. Momen ngẫu lực từ cực đại của khung dây có độ lớn bao nhiêu N.m?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046567864-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"Công thức: momen ngẫu lực từ cực đại tác dụng lên khung dây N vòng, diện tích S, dòng điện I, đặt trong từ trường đều B: Mmax = N.B.I.S.<br>Thay số: N = 100, B = 0,5 T, I = 5 A, S = 50 cm² = 50.10^-4 m² = 5.10^-3 m² → Mmax = 100 . 0,5 . 5 . 5.10^-3 = 1,25 N.m.<br>Kết quả: Đáp số: Mmax = 1,25 N.m.<br>$M=NIBS=100.5.0,5.50.10^{−4}=1,25Nm$<br>Sử dụng các thông tin sau cho câu 5 và câu 6: Để chế tạo tritium ( ${}_1^3T$ ) dùng cho lò phản ứng nhiệt hạch lớn người ta sử dụng phản ứng tổng hợp hai hạt nhân deuterium ( ${}_1^2D$ ). Phản ứng này có thể xảy ra 2 trường hợp sau:<br>${}_1^2D+{}_1^2D\\rightarrow {}_1^3T+p$ tỏa ra năng lượng 4,03 MeV.<br>${}_1^2D+{}_1^2D\\rightarrow {}_2^3He+n$ tỏa ra năng lượng 3,27 MeV.<br>Theo điều kiện lí tưởng, khả năng xảy ra của mỗi phản ứng trên là 50 % và chỉ 1 % số  ${}_1^2D$  tham gia phản ứng trong tổng khối lượng  ${}_1^2D$  được sử dụng. Có thể tìm thấy  ${}_1^2D$  trong nước biển và mỗi mét khối nước biển có 33 gam  ${}_1^2D$ . Khối lượng riêng nước biển trung bình là 1025 kg/m3. Cho 1 eV = 1,6.10<sup>−19</sup>J. Khối lượng mol nguyên tử của  ${}_1^2D$  và  ${}_1^3T$  lần lượt là 2 g/mol và 3 g/mol. Người ta sử dụng 5 tấn nước biển để tạo ra  ${}_1^2D$  dùng cho phản ứng nêu trên.<br>Sử dụng các thông tin sau cho câu 5 và câu 6: Để chế tạo tritium ( ${}_1^3T$ ) dùng cho lò phản ứng nhiệt hạch lớn người ta sử dụng phản ứng tổng hợp hai hạt nhân deuterium ( ${}_1^2D$ ). Phản ứng này có thể xảy ra 2 trường hợp sau:<br>${}_1^2D+{}_1^2D\\rightarrow {}_1^3T+p$ tỏa ra năng lượng 4,03 MeV.<br>${}_1^2D+{}_1^2D\\rightarrow {}_2^3He+n$ tỏa ra năng lượng 3,27 MeV.<br>Theo điều kiện lí tưởng, khả năng xảy ra của mỗi phản ứng trên là 50 % và chỉ 1 % số  ${}_1^2D$  tham gia phản ứng trong tổng khối lượng  ${}_1^2D$  được sử dụng. Có thể tìm thấy  ${}_1^2D$  trong nước biển và mỗi mét khối nước biển có 33 gam  ${}_1^2D$ . Khối lượng riêng nước biển trung bình là 1025 kg/m3. Cho 1 eV = 1,6.10<sup>−19</sup>J. Khối lượng mol nguyên tử của  ${}_1^2D$  và  ${}_1^3T$  lần lượt là 2 g/mol và 3 g/mol. Người ta sử dụng 5 tấn nước biển để tạo ra  ${}_1^2D$  dùng cho phản ứng nêu trên.","difficultySource":"ai"}}]},{"id":665123,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":2,"options":["19,3 1010 MeV.","6,02.10<sup>23</sup> MeV.","12,4.10<sup>23</sup> MeV.","16,4.10<sup>23</sup> MeV."],"question":"Cho rằng một hạt nhân Uranium  ${}_{92}^{235}U$  khi phân hạch thì tỏa ra năng lượng là 200 MeV. Năng lượng tỏa ra khi 2,35 g Uranium  ${}_{92}^{235}U$  phân hạch hết gần giá trị nào nhất sau đây?","difficulty":"trung-binh","explanation":"Công thức: số mol n = m/M; số hạt nhân N = n·N_A; năng lượng tỏa ra Q = N·ΔE (ΔE là năng lượng một hạt nhân tỏa ra khi phân hạch).<br>Thay số: n = 2,35/235 = 0,01 mol ⇒ N = 0,01 × 6,02×10²³ = 6,02×10²¹ hạt; Q = 6,02×10²¹ × 200 ≈ 12,4×10²³ MeV.<br>Kết quả: chọn C.<br>$n=\\frac{m}{M}=\\frac{2,35}{235}=0,01 mol$<br>$N=nN_A=0,01.6,02.10^{23}=6,02.10^{21}$<br>$Q=N\\Delta E=6,02.10^{21}.200\\approx 12,4.10^{23}MeV$","difficultySource":"ai"},"ex":[{"exam":386,"idx":8,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":2,"options":["19,3 1010 MeV.","6,02.10<sup>23</sup> MeV.","12,4.10<sup>23</sup> MeV.","16,4.10<sup>23</sup> MeV."],"question":"Cho rằng một hạt nhân Uranium  ${}_{92}^{235}U$  khi phân hạch thì tỏa ra năng lượng là 200 MeV. Năng lượng tỏa ra khi 2,35 g Uranium  ${}_{92}^{235}U$  phân hạch hết gần giá trị nào nhất sau đây?","difficulty":"trung-binh","explanation":"Công thức: số mol n = m/M; số hạt nhân N = n·N_A; năng lượng tỏa ra Q = N·ΔE (ΔE là năng lượng một hạt nhân tỏa ra khi phân hạch).<br>Thay số: n = 2,35/235 = 0,01 mol ⇒ N = 0,01 × 6,02×10²³ = 6,02×10²¹ hạt; Q = 6,02×10²¹ × 200 ≈ 12,4×10²³ MeV.<br>Kết quả: chọn C.<br>$n=\\frac{m}{M}=\\frac{2,35}{235}=0,01 mol$<br>$N=nN_A=0,01.6,02.10^{23}=6,02.10^{21}$<br>$Q=N\\Delta E=6,02.10^{21}.200\\approx 12,4.10^{23}MeV$","difficultySource":"ai"}}]},{"id":665135,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Trong vật lý hạt nhân, máy đo bức xạ (máy đếm/ống đếm) Geiger-Muller được sử dụng rộng rãi trong việc đo số lượng hạt α, β, bằng cách ứng dụng khả năng ion hoá của các tia bức xạ này. Số tín hiệu máy đếm được tỉ lệ thuận với số lượng hạt nhân bị phân rã. Xét hai máy đếm Geiger-Muller giống nhau lần lượt được chiếu xạ bởi hai mẫu chất phóng xạ  ${}_{84}^{210}Po$  và  ${}_{53}^{131}I$ (mỗi hạt nhân khi phân rã chỉ phát ra một tia phóng xạ). Biết rằng các mẫu chất phóng xạ được đặt ở cùng một khoảng cách so với các máy đếm tại hai phòng khác nhau. Cho khối lượng của từng mẫu phóng xạ tại thời điểm ban đầu đều là<br>1,5 g . Lấy khối lượng của các hạt nhân gần bằng số khối của chúng tính theo amu; chu kì bán rã của  ${}_{84}^{210}Po$ và  ${}_{53}^{131}I$ lần lượt là 138,4 ngày và 8,02 ngày<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046573906-hinh-12.jpg\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Số lượng hạt nhân  ${}_{53}^{131}I$ đã phân rã trong vòng 1 ngày đầu tiên xấp xỉ bằng 6,3.10<sup>21</sup> hạt.","answer":false},{"text":"Sau 1 ngày đầu tiên, máy đo bức xạ ứng với mẫu chất chứa  ${}_{53}^{131}I$ đếm được nhiều tín hiệu hơn.","answer":true},{"text":"Độ phóng xạ của hạt nhân  ${}_{84}^{210}Po$  sau 1 ngày đầu tiên xấp xỉ bằng 2,14.10<sup>19</sup> Bq","answer":false},{"text":"Hạt  ${}_{84}^{210}Po$  sau khi phóng ra hạt α thì biến thành hạt nhân  ${}_{82}^{206}Pb$","answer":true}],"explanation":"Công thức: số mol ban đầu n₀ = m₀/A; số hạt nhân ban đầu N₀ = n₀·N_A; số hạt đã phân rã sau thời gian t: ΔN = N₀(1 − 2^(−t/T)).<br>Thay số cho I-131: n₀ = 1,5/131 mol ⇒ N₀I = (1,5/131)×6,02×10²³ ≈ 6,9×10²¹ hạt. Sau t = 1 ngày: ΔN_I = N₀I(1 − 2^(−1/8,02)) ≈ 6,9×10²¹ × 0,0836 ≈ 5,8×10²⁰ hạt, không phải 6,3×10²¹ hạt như phát biểu ⇒ ý a) sai.<br>Thay số cho Po-210: N₀Po = (1,5/210)×6,02×10²³ ≈ 4,3×10²¹ hạt. Sau t = 1 ngày: ΔN_Po = N₀Po(1 − 2^(−1/138,4)) ≈ 4,3×10²¹ × 0,00501 ≈ 2,1×10¹⁹ hạt, nhỏ hơn nhiều so với ΔN_I ≈ 5,8×10²⁰ hạt của I-131 (vì I-131 có chu kì bán rã ngắn hơn nhiều nên phân rã nhanh hơn) ⇒ máy đo ứng với mẫu I-131 đếm được nhiều tín hiệu hơn ⇒ ý b) đúng.<br>Độ phóng xạ của Po-210 sau 1 ngày: H_Po = λ·N_Po = (ln2/T_Po)·N₀Po·2^(−t/T_Po) = (ln2/(138,4×24×3600))×4,3×10²¹×2^(−1/138,4) ≈ 2,48×10¹⁴ Bq, không phải 2,14×10¹⁹ Bq như phát biểu ⇒ ý c) sai.<br>Phản ứng phân rã α của Po-210: ₈₄²¹⁰Po → ₂⁴He + ₈₂²⁰⁶Pb — đúng như phát biểu ⇒ ý d) đúng.<br>Kết quả: a) Sai, b) Đúng, c) Sai, d) Đúng.<br>a) sai<br>$n_{0P_0}=\\frac{m_0}{A_{P0}}=\\frac{1,5}{210}=\\frac{1}{140}mol\\Rightarrow N_{0Po}=n_{0Po}N_A=\\frac{1}{140}.6,02.10^{23}=4,3.10^{21}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$n_{0I}=\\frac{m_0}{A_I}=\\frac{1,5}{131}=\\frac{3}{262}mol\\Rightarrow N_{0I}=n_{0I}N_A=\\frac{3}{362}.6,02.10^{23}\\approx 6,9.10^{21}$<br>$\\begin{aligned}\\end{aligned}\\Delta N_I=N_{0I}.\\left(1−2^{−\\frac{t}{T_1}}\\right)=6,9.10^{21}.\\left(1−2^{\\frac{−1}{8,02}}\\right)\\approx 5,7.10^{20}Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>$\\Delta N_{Po}=N_{0Pb}.\\left(1−2^{−\\frac{t}{T_{Po}}}\\right)=4,3.10^{21}.\\left(1−2^{\\frac{−1}{138,4}}\\right)\\approx 2,1.10^{19}<\\Delta N_I$<br>c) sai<br>$H_{Po}=\\lambda N_{Po}=\\frac{ln2}{T_{Po}}.N_{0Po}.2^{\\frac{−t}{T_{Po}}}=\\frac{ln2}{138,4.24.60.60}.4,3.10^{21}.2^{\\frac{−1}{138,4}}\\approx 2,48.10^{14}Bq$<br>d) đúng<br>${}_{84}^{210}Po\\rightarrow_2^4He+_{82}^{206}Pb$","difficultySource":"ai"},"ex":[{"exam":386,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Trong vật lý hạt nhân, máy đo bức xạ (máy đếm/ống đếm) Geiger-Muller được sử dụng rộng rãi trong việc đo số lượng hạt α, β, bằng cách ứng dụng khả năng ion hoá của các tia bức xạ này. Số tín hiệu máy đếm được tỉ lệ thuận với số lượng hạt nhân bị phân rã. Xét hai máy đếm Geiger-Muller giống nhau lần lượt được chiếu xạ bởi hai mẫu chất phóng xạ  ${}_{84}^{210}Po$  và  ${}_{53}^{131}I$ (mỗi hạt nhân khi phân rã chỉ phát ra một tia phóng xạ). Biết rằng các mẫu chất phóng xạ được đặt ở cùng một khoảng cách so với các máy đếm tại hai phòng khác nhau. Cho khối lượng của từng mẫu phóng xạ tại thời điểm ban đầu đều là<br>1,5 g . Lấy khối lượng của các hạt nhân gần bằng số khối của chúng tính theo amu; chu kì bán rã của  ${}_{84}^{210}Po$ và  ${}_{53}^{131}I$ lần lượt là 138,4 ngày và 8,02 ngày<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046573906-hinh-12.jpg\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Số lượng hạt nhân  ${}_{53}^{131}I$ đã phân rã trong vòng 1 ngày đầu tiên xấp xỉ bằng 6,3.10<sup>21</sup> hạt.","answer":false},{"text":"Sau 1 ngày đầu tiên, máy đo bức xạ ứng với mẫu chất chứa  ${}_{53}^{131}I$ đếm được nhiều tín hiệu hơn.","answer":true},{"text":"Độ phóng xạ của hạt nhân  ${}_{84}^{210}Po$  sau 1 ngày đầu tiên xấp xỉ bằng 2,14.10<sup>19</sup> Bq","answer":false},{"text":"Hạt  ${}_{84}^{210}Po$  sau khi phóng ra hạt α thì biến thành hạt nhân  ${}_{82}^{206}Pb$","answer":true}],"explanation":"Công thức: số mol ban đầu n₀ = m₀/A; số hạt nhân ban đầu N₀ = n₀·N_A; số hạt đã phân rã sau thời gian t: ΔN = N₀(1 − 2^(−t/T)).<br>Thay số cho I-131: n₀ = 1,5/131 mol ⇒ N₀I = (1,5/131)×6,02×10²³ ≈ 6,9×10²¹ hạt. Sau t = 1 ngày: ΔN_I = N₀I(1 − 2^(−1/8,02)) ≈ 6,9×10²¹ × 0,0836 ≈ 5,8×10²⁰ hạt, không phải 6,3×10²¹ hạt như phát biểu ⇒ ý a) sai.<br>Thay số cho Po-210: N₀Po = (1,5/210)×6,02×10²³ ≈ 4,3×10²¹ hạt. Sau t = 1 ngày: ΔN_Po = N₀Po(1 − 2^(−1/138,4)) ≈ 4,3×10²¹ × 0,00501 ≈ 2,1×10¹⁹ hạt, nhỏ hơn nhiều so với ΔN_I ≈ 5,8×10²⁰ hạt của I-131 (vì I-131 có chu kì bán rã ngắn hơn nhiều nên phân rã nhanh hơn) ⇒ máy đo ứng với mẫu I-131 đếm được nhiều tín hiệu hơn ⇒ ý b) đúng.<br>Độ phóng xạ của Po-210 sau 1 ngày: H_Po = λ·N_Po = (ln2/T_Po)·N₀Po·2^(−t/T_Po) = (ln2/(138,4×24×3600))×4,3×10²¹×2^(−1/138,4) ≈ 2,48×10¹⁴ Bq, không phải 2,14×10¹⁹ Bq như phát biểu ⇒ ý c) sai.<br>Phản ứng phân rã α của Po-210: ₈₄²¹⁰Po → ₂⁴He + ₈₂²⁰⁶Pb — đúng như phát biểu ⇒ ý d) đúng.<br>Kết quả: a) Sai, b) Đúng, c) Sai, d) Đúng.<br>a) sai<br>$n_{0P_0}=\\frac{m_0}{A_{P0}}=\\frac{1,5}{210}=\\frac{1}{140}mol\\Rightarrow N_{0Po}=n_{0Po}N_A=\\frac{1}{140}.6,02.10^{23}=4,3.10^{21}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$n_{0I}=\\frac{m_0}{A_I}=\\frac{1,5}{131}=\\frac{3}{262}mol\\Rightarrow N_{0I}=n_{0I}N_A=\\frac{3}{362}.6,02.10^{23}\\approx 6,9.10^{21}$<br>$\\begin{aligned}\\end{aligned}\\Delta N_I=N_{0I}.\\left(1−2^{−\\frac{t}{T_1}}\\right)=6,9.10^{21}.\\left(1−2^{\\frac{−1}{8,02}}\\right)\\approx 5,7.10^{20}Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>$\\Delta N_{Po}=N_{0Pb}.\\left(1−2^{−\\frac{t}{T_{Po}}}\\right)=4,3.10^{21}.\\left(1−2^{\\frac{−1}{138,4}}\\right)\\approx 2,1.10^{19}<\\Delta N_I$<br>c) sai<br>$H_{Po}=\\lambda N_{Po}=\\frac{ln2}{T_{Po}}.N_{0Po}.2^{\\frac{−t}{T_{Po}}}=\\frac{ln2}{138,4.24.60.60}.4,3.10^{21}.2^{\\frac{−1}{138,4}}\\approx 2,48.10^{14}Bq$<br>d) đúng<br>${}_{84}^{210}Po\\rightarrow_2^4He+_{82}^{206}Pb$","difficultySource":"ai"}}]},{"id":665136,"nq":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Biết không khí trong môi trường sống có nhiệt độ 00C và thể tích mol 22,4 lít/mol, thể tích không khí mà vận động viên hít vào khi hít sâu là 2,73 lít. Nhiệt độ phổi của vận động viên luôn ở mức 370C. Khi hít vào, không khí được đẩy vào phổi có nhiệt độ 370C sau khi qua mũi, họng, đồng thời nhanh chóng đạt được sự cân bằng áp suất bên trong và bên ngoài. Biết chênh lệch áp suất của không khí bên trong và bên ngoài phổi tối đa mà vận động viên chịu được là 150 mmHg.","difficulty":"kho","statements":[{"text":"Độ chênh lệch nhiệt độ của không khí trong phổi và bên ngoài là 310 K.","answer":false},{"text":"Tổng số phân tử không khí mà vận động viên hít vào khi hít sâu xấp xỉ là 7,34.10<sup>22</sup>.","answer":true},{"text":"Thể tích không khí trong phổi của vận động viên sau khi hít sâu là 3,1 lít.","answer":true},{"text":"Nếu sau khi hít sâu vào, vận động viên nín thở và phổi co lại thì giá trị nhỏ nhất của thể tích khí trong phổi vận động viên này đạt được có thể ít hơn 2,5 lít.","answer":false}],"explanation":"Công thức: số mol khí n = V/22,4 (ở đktc); số phân tử N = n·N_A; định luật Gay-Lussac (đẳng áp) V/T = hằng số khi hít vào với áp suất cân bằng.<br>Xét ý a): độ chênh lệch nhiệt độ giữa phổi (37°C = 310 K) và bên ngoài (0°C = 273 K) tính theo độ chênh lệch trực tiếp là 37°C, tức 37 K (chênh lệch nhiệt độ theo độ C và độ K bằng nhau về độ lớn), không phải 310 K như phát biểu ⇒ ý a) sai.<br>Xét ý b): n = 2,73/22,4 mol ⇒ N = (2,73/22,4)×6,02×10²³ ≈ 7,34×10²² phân tử — đúng như phát biểu ⇒ ý b) đúng.<br>Xét ý c): áp dụng đẳng áp V/T = hằng số: 2,73/273 = V_c/(37+273) ⇒ V_c = 2,73×310/273 ≈ 3,1 lít — đúng như phát biểu ⇒ ý c) đúng.<br>Xét ý d): khi nín thở, phổi co lại tối đa cho tới khi áp suất bên trong giảm 150 mmHg so với áp suất khí quyển tiêu chuẩn 760 mmHg (còn 610 mmHg); ở nhiệt độ không đổi 310 K (đẳng nhiệt): p·V = hằng số ⇒ 760×3,1 = (760−150)×V_min ⇒ V_min ≈ 2,589 lít, nhỏ hơn 2,5 lít không đúng (2,589 > 2,5) nên giá trị nhỏ nhất của thể tích khí trong phổi KHÔNG THỂ ít hơn 2,5 lít ⇒ ý d) sai.<br>Kết quả: a) Sai, b) Đúng, c) Đúng, d) Sai.<br>a) sai<br>Độ chênh lệch nhiệt độ của không khí trong phổi và bên ngoài là 37K<br>b) đúng<br>$n=\\frac{V}{22,4}=\\frac{2,73}{22,4}mol$<br>$\\begin{aligned}\\end{aligned}N=nN_A=\\frac{2,73}{22,4}.6,02.10^{23}\\approx 7,34.10^{22}Website: thukhoadaihoc.vn$<br>c) đúng<br>Đẳng áp  $\\frac{V}{T}\\Rightarrow \\frac{1,73}{273}=\\frac{V_c}{37+273}\\Rightarrow V_c=3,1\\left(ℓ\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>Ban đầu ở điều kiện tiêu chuẩn  $\\Rightarrow p=760 mmHg$<br>Đẳng nhiệt  $pV=const\\Rightarrow 760.3,1=\\left(760+150\\right).V_d\\Rightarrow V_d\\approx 2,589\\left(ℓ\\right)$","difficultySource":"ai"},"ex":[{"exam":386,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Biết không khí trong môi trường sống có nhiệt độ 00C và thể tích mol 22,4 lít/mol, thể tích không khí mà vận động viên hít vào khi hít sâu là 2,73 lít. Nhiệt độ phổi của vận động viên luôn ở mức 370C. Khi hít vào, không khí được đẩy vào phổi có nhiệt độ 370C sau khi qua mũi, họng, đồng thời nhanh chóng đạt được sự cân bằng áp suất bên trong và bên ngoài. Biết chênh lệch áp suất của không khí bên trong và bên ngoài phổi tối đa mà vận động viên chịu được là 150 mmHg.","difficulty":"kho","statements":[{"text":"Độ chênh lệch nhiệt độ của không khí trong phổi và bên ngoài là 310 K.","answer":false},{"text":"Tổng số phân tử không khí mà vận động viên hít vào khi hít sâu xấp xỉ là 7,34.10<sup>22</sup>.","answer":true},{"text":"Thể tích không khí trong phổi của vận động viên sau khi hít sâu là 3,1 lít.","answer":true},{"text":"Nếu sau khi hít sâu vào, vận động viên nín thở và phổi co lại thì giá trị nhỏ nhất của thể tích khí trong phổi vận động viên này đạt được có thể ít hơn 2,5 lít.","answer":false}],"explanation":"Công thức: số mol khí n = V/22,4 (ở đktc); số phân tử N = n·N_A; định luật Gay-Lussac (đẳng áp) V/T = hằng số khi hít vào với áp suất cân bằng.<br>Xét ý a): độ chênh lệch nhiệt độ giữa phổi (37°C = 310 K) và bên ngoài (0°C = 273 K) tính theo độ chênh lệch trực tiếp là 37°C, tức 37 K (chênh lệch nhiệt độ theo độ C và độ K bằng nhau về độ lớn), không phải 310 K như phát biểu ⇒ ý a) sai.<br>Xét ý b): n = 2,73/22,4 mol ⇒ N = (2,73/22,4)×6,02×10²³ ≈ 7,34×10²² phân tử — đúng như phát biểu ⇒ ý b) đúng.<br>Xét ý c): áp dụng đẳng áp V/T = hằng số: 2,73/273 = V_c/(37+273) ⇒ V_c = 2,73×310/273 ≈ 3,1 lít — đúng như phát biểu ⇒ ý c) đúng.<br>Xét ý d): khi nín thở, phổi co lại tối đa cho tới khi áp suất bên trong giảm 150 mmHg so với áp suất khí quyển tiêu chuẩn 760 mmHg (còn 610 mmHg); ở nhiệt độ không đổi 310 K (đẳng nhiệt): p·V = hằng số ⇒ 760×3,1 = (760−150)×V_min ⇒ V_min ≈ 2,589 lít, nhỏ hơn 2,5 lít không đúng (2,589 > 2,5) nên giá trị nhỏ nhất của thể tích khí trong phổi KHÔNG THỂ ít hơn 2,5 lít ⇒ ý d) sai.<br>Kết quả: a) Sai, b) Đúng, c) Đúng, d) Sai.<br>a) sai<br>Độ chênh lệch nhiệt độ của không khí trong phổi và bên ngoài là 37K<br>b) đúng<br>$n=\\frac{V}{22,4}=\\frac{2,73}{22,4}mol$<br>$\\begin{aligned}\\end{aligned}N=nN_A=\\frac{2,73}{22,4}.6,02.10^{23}\\approx 7,34.10^{22}Website: thukhoadaihoc.vn$<br>c) đúng<br>Đẳng áp  $\\frac{V}{T}\\Rightarrow \\frac{1,73}{273}=\\frac{V_c}{37+273}\\Rightarrow V_c=3,1\\left(ℓ\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>Ban đầu ở điều kiện tiêu chuẩn  $\\Rightarrow p=760 mmHg$<br>Đẳng nhiệt  $pV=const\\Rightarrow 760.3,1=\\left(760+150\\right).V_d\\Rightarrow V_d\\approx 2,589\\left(ℓ\\right)$","difficultySource":"ai"}}]},{"id":666556,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":0,"options":["6,27.10<sup>−21</sup> J.","6,21.10<sup>−22</sup> J.","6,11.10<sup>−22</sup> J.","6,17.10<sup>−21</sup> J."],"question":"Động năng trung bình của phân tử khí lí tưởng ở 300C có giá trị là","difficulty":"de","explanation":"Công thức: động năng tịnh tiến trung bình của phân tử khí lí tưởng W_đ = (3/2)k·T, với k = 1,38×10⁻²³ J/K.<br>Thay số: T = 30+273 = 303 K. W_đ = (3/2)×1,38×10⁻²³×303 ≈ 6,275×10⁻²¹ J.<br>Kết quả: W_đ ≈ 6,27×10⁻²¹ J. Chọn A.<br>$\\begin{aligned}\\end{aligned}\\overline{E}_d=\\frac{3}{2}.k.T=\\frac{3}{2}.1,38.10^{−23}.\\left(30+273\\right)=6,275.10^{−21}\\left(J\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":387,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":0,"options":["6,27.10<sup>−21</sup> J.","6,21.10<sup>−22</sup> J.","6,11.10<sup>−22</sup> J.","6,17.10<sup>−21</sup> J."],"question":"Động năng trung bình của phân tử khí lí tưởng ở 300C có giá trị là","difficulty":"de","explanation":"Công thức: động năng tịnh tiến trung bình của phân tử khí lí tưởng W_đ = (3/2)k·T, với k = 1,38×10⁻²³ J/K.<br>Thay số: T = 30+273 = 303 K. W_đ = (3/2)×1,38×10⁻²³×303 ≈ 6,275×10⁻²¹ J.<br>Kết quả: W_đ ≈ 6,27×10⁻²¹ J. Chọn A.<br>$\\begin{aligned}\\end{aligned}\\overline{E}_d=\\frac{3}{2}.k.T=\\frac{3}{2}.1,38.10^{−23}.\\left(30+273\\right)=6,275.10^{−21}\\left(J\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":666566,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["460 kJ.","690 kJ","230 kJ.","767 kJ."],"question":"Lượng nước sôi có trong một chiếc ấm có khối lượng m = 300 g. Đun nước tới nhiệt độ sôi dưới áp suất khí quyển bằng 1 atm. Cho nhiệt hóa hơi riêng của nước là 2,3.10<sup>6</sup> J/kg. Nhiệt lượng cần thiết để m' = 100 g nước sôi hóa thành hơi có giá trị bằng bao nhiêu kJ?","difficulty":"de","explanation":"Công thức: nhiệt lượng cần để hóa hơi một khối lượng nước ở nhiệt độ sôi Q = L·m, với L là nhiệt hóa hơi riêng.<br>Thay số: L = 2,3×10⁶ J/kg, m' = 100 g = 0,1 kg. Q = 2,3×10⁶ × 0,1 = 2,3×10⁵ J = 230 kJ.<br>Kết quả: Q = 230 kJ. Chọn C.<br>$0,1.2,3.10^6=2,3.10^5\\left(J\\right)=230\\left(kJ\\right)$","difficultySource":"ai"},"ex":[{"exam":387,"idx":13,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":2,"options":["460 kJ.","690 kJ","230 kJ.","767 kJ."],"question":"Lượng nước sôi có trong một chiếc ấm có khối lượng m = 300 g. Đun nước tới nhiệt độ sôi dưới áp suất khí quyển bằng 1 atm. Cho nhiệt hóa hơi riêng của nước là 2,3.10<sup>6</sup> J/kg. Nhiệt lượng cần thiết để m' = 100 g nước sôi hóa thành hơi có giá trị bằng bao nhiêu kJ?","difficulty":"de","explanation":"Công thức: nhiệt lượng cần để hóa hơi một khối lượng nước ở nhiệt độ sôi Q = L·m, với L là nhiệt hóa hơi riêng.<br>Thay số: L = 2,3×10⁶ J/kg, m' = 100 g = 0,1 kg. Q = 2,3×10⁶ × 0,1 = 2,3×10⁵ J = 230 kJ.<br>Kết quả: Q = 230 kJ. Chọn C.<br>$0,1.2,3.10^6=2,3.10^5\\left(J\\right)=230\\left(kJ\\right)$","difficultySource":"ai"}}]},{"id":666574,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":"170","question":"Tính nhiệt lượng (theo đơn vị kJ) cần cung cấp để làm nóng chảy hoàn toàn 500 gam nước đá ở 00C.<br>Biết nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg.","difficulty":"de","explanation":"Công thức: nhiệt lượng cần để nóng chảy hoàn toàn một khối chất rắn ở nhiệt độ nóng chảy Q = λ·m, với λ là nhiệt nóng chảy riêng.<br>Thay số: m = 500 g = 0,5 kg, λ = 3,4×10⁵ J/kg. Q = 0,5 × 3,4×10⁵ = 1,7×10⁵ J = 170 kJ.<br>Kết quả: Q = 170 kJ. Đáp số: 170.<br>$Q=mc\\Delta t=0,5.3,4.10^5=1,7.10^5\\left(J\\right)=170\\left(kJ\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":387,"idx":21,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":"170","question":"Tính nhiệt lượng (theo đơn vị kJ) cần cung cấp để làm nóng chảy hoàn toàn 500 gam nước đá ở 00C.<br>Biết nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg.","difficulty":"de","explanation":"Công thức: nhiệt lượng cần để nóng chảy hoàn toàn một khối chất rắn ở nhiệt độ nóng chảy Q = λ·m, với λ là nhiệt nóng chảy riêng.<br>Thay số: m = 500 g = 0,5 kg, λ = 3,4×10⁵ J/kg. Q = 0,5 × 3,4×10⁵ = 1,7×10⁵ J = 170 kJ.<br>Kết quả: Q = 170 kJ. Đáp số: 170.<br>$Q=mc\\Delta t=0,5.3,4.10^5=1,7.10^5\\left(J\\right)=170\\left(kJ\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":666580,"nq":{"form":"bai_tap","type":"short_answer","topic":"Động năng trung bình phân tử và nhiệt độ","answer":"77,2","question":"Để động năng tịnh tiến trung bình của các phân tử khí bằng 1,0 eV thì nhiệt độ của khối khí đó bằng bao nhiêu theo thang đo Kelvin? Lấy 1 eV = 1,6. 10<sup>−19</sup> J. (Kết quả làm tròn đến hàng đơn vị).","difficulty":"de","explanation":"Công thức: động năng tịnh tiến trung bình của phân tử khí lí tưởng W_đ = (3/2)k·T, với k = 1,38×10⁻²³ J/K; đổi đơn vị năng lượng 1 eV = 1,6×10⁻¹⁹ J.<br>Thay số: W_đ = 1,0 eV = 1,6×10⁻¹⁹ J. Từ 1,6×10⁻¹⁹ = (3/2)×1,38×10⁻²³×T ⇒ T = (1,6×10⁻¹⁹)/(1,5×1,38×10⁻²³) ≈ 77,29 K.<br>Kết quả: T ≈ 77,29 K. Đáp số: 77,29.<br>$\\overline{E}_d=\\frac{3}{2}.k.T\\Rightarrow 1,6.10^{−19}=1,5.1,38.10^{−23}T$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow T=77,29\\left(K\\right)$","difficultySource":"ai"},"ex":[{"exam":387,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Động năng trung bình phân tử và nhiệt độ","answer":"77,2","question":"Để động năng tịnh tiến trung bình của các phân tử khí bằng 1,0 eV thì nhiệt độ của khối khí đó bằng bao nhiêu theo thang đo Kelvin? Lấy 1 eV = 1,6. 10<sup>−19</sup> J. (Kết quả làm tròn đến hàng đơn vị).","difficulty":"de","explanation":"Công thức: động năng tịnh tiến trung bình của phân tử khí lí tưởng W_đ = (3/2)k·T, với k = 1,38×10⁻²³ J/K; đổi đơn vị năng lượng 1 eV = 1,6×10⁻¹⁹ J.<br>Thay số: W_đ = 1,0 eV = 1,6×10⁻¹⁹ J. Từ 1,6×10⁻¹⁹ = (3/2)×1,38×10⁻²³×T ⇒ T = (1,6×10⁻¹⁹)/(1,5×1,38×10⁻²³) ≈ 77,29 K.<br>Kết quả: T ≈ 77,29 K. Đáp số: 77,29.<br>$\\overline{E}_d=\\frac{3}{2}.k.T\\Rightarrow 1,6.10^{−19}=1,5.1,38.10^{−23}T$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow T=77,29\\left(K\\right)$","difficultySource":"ai"}}]},{"id":667750,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Radon là khí không màu, không mùi và không vị do đó không thể phát hiện chỉ bằng giác quan con người. Radon  ${}_{86}^{222}Rn$ là một đồng vị phóng xạ alpha và sinh ra hạt nhân con X với chu kỳ 3,82 ngày đêm. Nguyên tố   ${}_{86}^{222}Rn$ có trong đất đá, bốc lên trong không khí và tích tụ trong các ngôi nhà, hầm kín, trường học. Theo tổ chức WHO,  ${}_{86}^{222}Rn$ được cho là nguyên nhân thứ hai gây ra bệnh ung thư phổi sau thuốc lá. Trong một khảo sát tại một khu công nghiệp, người ta đo được độ phóng xạ trong 1 lít không khí chứa khoảng 10,8.10<sup>3</sup> nguyên tử khí radon   ${}_{86}^{222}Rn$ . Biết rằng nồng độ phóng xạ an toàn của radon trong không khí vào khoảng 150 Bq/m3","difficulty":"kho","statements":[{"text":"Độ phóng xạ của một lượng radon  ${}_{86}^{222}Rn$ tăng dần theo thời gian.","answer":false},{"text":"Số hạt phóng xạ của  ${}_{86}^{222}Rn$ còn lại N tại thời điểm t được xác định bằng biểu thức  $N=N_0.2^{−\\frac{t}{T}}$ (N0 là số hạt nhân ban đầu).","answer":true},{"text":"Cho khối lượng các hạt nhân  ${}_{86}^{222}Rn$ ,  ${}_2^4He$  và hạt X lần lượt là 222,0175amu; 4,0026 amu; 218,0089 amu và ban đầu hạt nhân Radon đứng yên khi phân rã. Nếu bỏ qua phóng xạ gamma thì mỗi phân rã  ${}_{86}^{222}Rn$ toả ra năng lượng là 5,589MeV.","answer":true},{"text":"Nồng độ phóng xạ của khí radon ở khu công nghiệp trên tại thời điểm khảo sát đang ở mức nguy hiểm.","answer":false}],"explanation":"a) sai<br>Độ phóng xạ của một lượn radon  ${}_{86}^{222}Rn$  giảm dần theo thời gian<br>b) đúng<br>Số hạt phóng xạ của  ${}_{86}^{222}Rn$ còn lại N tại thời điểm t được xác định bằng biểu thức  $N=N_0.2^{−\\frac{t}{T}}$ (N0 là số hạt nhân ban đầu).<br>c) đúng<br>$\\Delta E=\\left(m_{Rn}−m_{He}−m_X\\right)c^2=\\left(22,0175−4,0026−218,0089\\right).931,5=5,589\\left(MeV\\right)$<br>d) sai<br>1m3 không khí chứa khoảng 10,8.10<sup>6</sup> nguyên tử khí radon  ${}_{86}^{222}Rn$<br>$H=\\lambda N=\\frac{ln2}{T}N=\\frac{ln2}{3,82.24.60.60}.10,8.10^6\\approx 22,7Bq<150Bq$","difficultySource":"ai"},"ex":[{"exam":388,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Radon là khí không màu, không mùi và không vị do đó không thể phát hiện chỉ bằng giác quan con người. Radon  ${}_{86}^{222}Rn$ là một đồng vị phóng xạ alpha và sinh ra hạt nhân con X với chu kỳ 3,82 ngày đêm. Nguyên tố   ${}_{86}^{222}Rn$ có trong đất đá, bốc lên trong không khí và tích tụ trong các ngôi nhà, hầm kín, trường học. Theo tổ chức WHO,  ${}_{86}^{222}Rn$ được cho là nguyên nhân thứ hai gây ra bệnh ung thư phổi sau thuốc lá. Trong một khảo sát tại một khu công nghiệp, người ta đo được độ phóng xạ trong 1 lít không khí chứa khoảng 10,8.10<sup>3</sup> nguyên tử khí radon   ${}_{86}^{222}Rn$ . Biết rằng nồng độ phóng xạ an toàn của radon trong không khí vào khoảng 150 Bq/m3","difficulty":"kho","statements":[{"text":"Độ phóng xạ của một lượng radon  ${}_{86}^{222}Rn$ tăng dần theo thời gian.","answer":false},{"text":"Số hạt phóng xạ của  ${}_{86}^{222}Rn$ còn lại N tại thời điểm t được xác định bằng biểu thức  $N=N_0.2^{−\\frac{t}{T}}$ (N0 là số hạt nhân ban đầu).","answer":true},{"text":"Cho khối lượng các hạt nhân  ${}_{86}^{222}Rn$ ,  ${}_2^4He$  và hạt X lần lượt là 222,0175amu; 4,0026 amu; 218,0089 amu và ban đầu hạt nhân Radon đứng yên khi phân rã. Nếu bỏ qua phóng xạ gamma thì mỗi phân rã  ${}_{86}^{222}Rn$ toả ra năng lượng là 5,589MeV.","answer":true},{"text":"Nồng độ phóng xạ của khí radon ở khu công nghiệp trên tại thời điểm khảo sát đang ở mức nguy hiểm.","answer":false}],"explanation":"a) sai<br>Độ phóng xạ của một lượn radon  ${}_{86}^{222}Rn$  giảm dần theo thời gian<br>b) đúng<br>Số hạt phóng xạ của  ${}_{86}^{222}Rn$ còn lại N tại thời điểm t được xác định bằng biểu thức  $N=N_0.2^{−\\frac{t}{T}}$ (N0 là số hạt nhân ban đầu).<br>c) đúng<br>$\\Delta E=\\left(m_{Rn}−m_{He}−m_X\\right)c^2=\\left(22,0175−4,0026−218,0089\\right).931,5=5,589\\left(MeV\\right)$<br>d) sai<br>1m3 không khí chứa khoảng 10,8.10<sup>6</sup> nguyên tử khí radon  ${}_{86}^{222}Rn$<br>$H=\\lambda N=\\frac{ln2}{T}N=\\frac{ln2}{3,82.24.60.60}.10,8.10^6\\approx 22,7Bq<150Bq$","difficultySource":"ai"}}]},{"id":668232,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Thuyết động học phân tử chất khí","answer":1,"options":["8,2.10<sup>9</sup> lần.","4,1.10<sup>9</sup> lần.","2,0.10<sup>9</sup> lần.","5,0.10<sup>9</sup> lần."],"question":"Ở điều kiện nhiệt độ phòng 270C và áp suất khí quyển 1,0 atm, một phân tử oxygen có tốc độ trung bình 450 m/s và quãng đường tự do trung bình (quãng đường đi giữa giữa hai lần va chạm liên tiếp) là 1,1.10<sup>−7</sup> m. Trung bình mỗi giây, một phân tử oxy thực hiện khoảng bao nhiêu va chạm?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Quãng đường tự do trung bình $\\lambda$ là quãng đường trung bình phân tử đi được giữa hai va chạm liên tiếp. Trong thời gian $t$, phân tử đi được quãng đường xấp xỉ $\\bar{v}\\,t$, nên số va chạm trung bình trong thời gian đó là $N = \\dfrac{\\bar{v}\\,t}{\\lambda}$.</p><p class=\"text-base leading-relaxed my-2\">Số va chạm trung bình mỗi giây:</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{N}{t} = \\dfrac{\\bar{v}}{\\lambda}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{N}{t} = \\dfrac{450}{1{,}1\\cdot 10^{-7}} \\approx 4{,}1\\cdot 10^{9}\\ \\text{(lần/s)}$</p><p class=\"text-base leading-relaxed my-2\">Vậy mỗi giây một phân tử oxygen thực hiện khoảng $4{,}1\\cdot 10^{9}$ va chạm. Chọn đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":389,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Thuyết động học phân tử chất khí","answer":1,"options":["8,2.10<sup>9</sup> lần.","4,1.10<sup>9</sup> lần.","2,0.10<sup>9</sup> lần.","5,0.10<sup>9</sup> lần."],"question":"Ở điều kiện nhiệt độ phòng 270C và áp suất khí quyển 1,0 atm, một phân tử oxygen có tốc độ trung bình 450 m/s và quãng đường tự do trung bình (quãng đường đi giữa giữa hai lần va chạm liên tiếp) là 1,1.10<sup>−7</sup> m. Trung bình mỗi giây, một phân tử oxy thực hiện khoảng bao nhiêu va chạm?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Quãng đường tự do trung bình $\\lambda$ là quãng đường trung bình phân tử đi được giữa hai va chạm liên tiếp. Trong thời gian $t$, phân tử đi được quãng đường xấp xỉ $\\bar{v}\\,t$, nên số va chạm trung bình trong thời gian đó là $N = \\dfrac{\\bar{v}\\,t}{\\lambda}$.</p><p class=\"text-base leading-relaxed my-2\">Số va chạm trung bình mỗi giây:</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{N}{t} = \\dfrac{\\bar{v}}{\\lambda}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{N}{t} = \\dfrac{450}{1{,}1\\cdot 10^{-7}} \\approx 4{,}1\\cdot 10^{9}\\ \\text{(lần/s)}$</p><p class=\"text-base leading-relaxed my-2\">Vậy mỗi giây một phân tử oxygen thực hiện khoảng $4{,}1\\cdot 10^{9}$ va chạm. Chọn đáp án B.</p>","difficultySource":"ai"}}]},{"id":668242,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["1 kg nước sẽ tỏa ra một lượng nhiệt là 2,3.10<sup>6</sup> J để bay hơi hoàn toàn ở nhiệt độ 1000C","1 kg nước cần thu một lượng nhiệt là 2,3.10<sup>6</sup> J để bay hơi hoàn toàn ở nhiệt độ 1000C","1 m3 nước bất kì sẽ tỏa ra một lượng nhiệt là 2,3.10<sup>6</sup> J để hóa hơi hoàn toàn.","1 m3 nước bất kì cần thu một lượng nhiệt là 2,3.10<sup>6</sup> J để hóa hơi hoàn toàn."],"question":"Nhiệt hóa hơi riêng của nước ở nhiệt độ 1000C là 2,3.10<sup>6</sup> J/kg có nghĩa là","difficulty":"de","explanation":"Nhiệt hóa hơi riêng của nước ở nhiệt độ 1000C là 2,3.10<sup>6</sup> J/kg có nghĩa là → 1 kg nước cần thu một lượng nhiệt là 2,3.10<sup>6</sup> J để bay hơi hoàn toàn ở nhiệt độ 1000C","difficultySource":"ai"},"ex":[{"exam":389,"idx":13,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["1 kg nước sẽ tỏa ra một lượng nhiệt là 2,3.10<sup>6</sup> J để bay hơi hoàn toàn ở nhiệt độ 1000C","1 kg nước cần thu một lượng nhiệt là 2,3.10<sup>6</sup> J để bay hơi hoàn toàn ở nhiệt độ 1000C","1 m3 nước bất kì sẽ tỏa ra một lượng nhiệt là 2,3.10<sup>6</sup> J để hóa hơi hoàn toàn.","1 m3 nước bất kì cần thu một lượng nhiệt là 2,3.10<sup>6</sup> J để hóa hơi hoàn toàn."],"question":"Nhiệt hóa hơi riêng của nước ở nhiệt độ 1000C là 2,3.10<sup>6</sup> J/kg có nghĩa là","difficulty":"de","explanation":"Nhiệt hóa hơi riêng của nước ở nhiệt độ 1000C là 2,3.10<sup>6</sup> J/kg có nghĩa là → 1 kg nước cần thu một lượng nhiệt là 2,3.10<sup>6</sup> J để bay hơi hoàn toàn ở nhiệt độ 1000C","difficultySource":"ai"}}]},{"id":668246,"nq":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một nhóm học sinh thực hiện thí nghiệm thực hành đo nhiệt hóa hơi riêng của nước. Họ lựa chọn phương án sử dụng ấm siêu tốc có vỏ cách nhiệt tốt để đun sôi nước. Họ tiến hành các bước như sau:<br>− Lấy 1 lượng nước vào ấm, đặt ấm lên cân điện tử và bắt bầu đun.<br>Khi nước trong ấm sôi, mở nắp để hơi nước thoát ra ngoài.<br>− Đọc số chỉ của cân ở các thời điểm khác nhau theo thời gian.<br>Biết ấm có công suất P = 1,50.10<sup>3</sup> W; cân điện tử có độ chính xác là 1 g; số chỉ của cân ở thời điểm mốc t0 = 0,00 s là m0  = 1,873 kg.<br>Kết quả thu được như bảng:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046607463-hinh-14.jpg\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Số chỉ của cân là khối lượng của nước chứa trong ấm.","answer":false},{"text":"Sai số dụng cụ đo khối lượng (cân điện tử) trong thí nghiệm trên là 0,5 g.","answer":false},{"text":"Khối lượng nước hóa hơi trong thời gian 162,05 s (kể từ t0 = 0,00s ) là 0,100 kg.","answer":true},{"text":"Giá trị trung bình của nhiệt hóa hơi riêng của nước đo được bởi nhóm học sinh này là L = 2,42.10<sup>6</sup> J/kg.","answer":true}],"explanation":"a) sai<br>Số chỉ của cân là khối lượng của ấm và nước chứa trong ấm<br>b) sai<br>Độ chính xác của cân điện tử chính là sai số dụng cụ là 1g<br>c) đúng<br>$\\Delta m_1=m_0−m_1=1,873−1,773=0,1kg$<br>d) đúng<br>$\\begin{aligned}\\end{aligned}L=\\frac{Pt}{\\Delta m}=\\frac{1,5.10^3.805,22}{1,873−1,373}\\approx 2,42.10^6\\left(J/kg\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":389,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một nhóm học sinh thực hiện thí nghiệm thực hành đo nhiệt hóa hơi riêng của nước. Họ lựa chọn phương án sử dụng ấm siêu tốc có vỏ cách nhiệt tốt để đun sôi nước. Họ tiến hành các bước như sau:<br>− Lấy 1 lượng nước vào ấm, đặt ấm lên cân điện tử và bắt bầu đun.<br>Khi nước trong ấm sôi, mở nắp để hơi nước thoát ra ngoài.<br>− Đọc số chỉ của cân ở các thời điểm khác nhau theo thời gian.<br>Biết ấm có công suất P = 1,50.10<sup>3</sup> W; cân điện tử có độ chính xác là 1 g; số chỉ của cân ở thời điểm mốc t0 = 0,00 s là m0  = 1,873 kg.<br>Kết quả thu được như bảng:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046607463-hinh-14.jpg\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Số chỉ của cân là khối lượng của nước chứa trong ấm.","answer":false},{"text":"Sai số dụng cụ đo khối lượng (cân điện tử) trong thí nghiệm trên là 0,5 g.","answer":false},{"text":"Khối lượng nước hóa hơi trong thời gian 162,05 s (kể từ t0 = 0,00s ) là 0,100 kg.","answer":true},{"text":"Giá trị trung bình của nhiệt hóa hơi riêng của nước đo được bởi nhóm học sinh này là L = 2,42.10<sup>6</sup> J/kg.","answer":true}],"explanation":"a) sai<br>Số chỉ của cân là khối lượng của ấm và nước chứa trong ấm<br>b) sai<br>Độ chính xác của cân điện tử chính là sai số dụng cụ là 1g<br>c) đúng<br>$\\Delta m_1=m_0−m_1=1,873−1,773=0,1kg$<br>d) đúng<br>$\\begin{aligned}\\end{aligned}L=\\frac{Pt}{\\Delta m}=\\frac{1,5.10^3.805,22}{1,873−1,373}\\approx 2,42.10^6\\left(J/kg\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":668250,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"6,7","question":"Trong quá trình lập trình máy thở, một kỹ sư cần xác định khối lượng không khí có trong phổi bệnh nhân tại thời điểm hít vào. Biết dung tích phổi là 5,9 lít, áp suất khí là 1,01.10<sup>5</sup> Pa, nhiệt độ cơ thể là 370C. Không khí là khí lý tưởng có khối lượng mol trung bình 29 g/mol. Khối lượng không khí trong phổi tại thời điểm đó bằng bao nhiêu gam (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Công thức: coi không khí là khí lí tưởng, dùng phương trình trạng thái pV = nRT = (m/M)RT → m = pVM/(RT).<br>Thay số: p = 1,01.10^5 Pa, V = 5,9 lít = 5,9.10^-3 m³, T = 37+273 = 310 K, M = 29 g/mol → m = (1,01.10^5 . 5,9.10^-3 . 29)/(8,31 . 310) = 17280,1/2576,1 ≈ 6,708 g.<br>Kết quả: làm tròn đến hàng phần mười, Đáp số: 6,7 g.<br>$\\begin{aligned}\\end{aligned}\\frac{pV}{T}=nR\\Rightarrow \\frac{1,01010^5.5,9.10^{−3}}{37+273}=n.8,31\\Rightarrow n\\approx 0,231molWebsite: thukhoadaihoc.vn$<br>$m=nM=0,231.29\\approx 6,7g$","difficultySource":"ai"},"ex":[{"exam":389,"idx":21,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"6,7","question":"Trong quá trình lập trình máy thở, một kỹ sư cần xác định khối lượng không khí có trong phổi bệnh nhân tại thời điểm hít vào. Biết dung tích phổi là 5,9 lít, áp suất khí là 1,01.10<sup>5</sup> Pa, nhiệt độ cơ thể là 370C. Không khí là khí lý tưởng có khối lượng mol trung bình 29 g/mol. Khối lượng không khí trong phổi tại thời điểm đó bằng bao nhiêu gam (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Công thức: coi không khí là khí lí tưởng, dùng phương trình trạng thái pV = nRT = (m/M)RT → m = pVM/(RT).<br>Thay số: p = 1,01.10^5 Pa, V = 5,9 lít = 5,9.10^-3 m³, T = 37+273 = 310 K, M = 29 g/mol → m = (1,01.10^5 . 5,9.10^-3 . 29)/(8,31 . 310) = 17280,1/2576,1 ≈ 6,708 g.<br>Kết quả: làm tròn đến hàng phần mười, Đáp số: 6,7 g.<br>$\\begin{aligned}\\end{aligned}\\frac{pV}{T}=nR\\Rightarrow \\frac{1,01010^5.5,9.10^{−3}}{37+273}=n.8,31\\Rightarrow n\\approx 0,231molWebsite: thukhoadaihoc.vn$<br>$m=nM=0,231.29\\approx 6,7g$","difficultySource":"ai"}}]},{"id":668251,"nq":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng áp và định luật Charles","answer":"348","question":"Nam cần dùng một chai thủy tinh chứa khí ở điều kiện phòng (áp suất 1,0.10<sup>5</sup> Pa, nhiệt độ 170C) nhưng nút chai bị kẹt do ma sát hoặc co cứng. Nam hơ nóng chai để tăng áp suất khí bên trong, nút chai bật ra khi chênh lệch áp suất trong và ngoài đạt tối thiểu 0,2.105 Pa. Biết thể tích khí trong chai không đổi trong quá trình nung. Hỏi nhiệt độ của khí trong chai bằng bao nhiêu K để nút bật ra (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Công thức: thể tích không đổi (đẳng tích) nên áp dụng định luật Charles: p1/T1 = p2/T2 → T2 = T1.p2/p1.<br>Thay số: T1 = 17+273 = 290 K, p1 = 1,0.10^5 Pa, p2 = p1 + 0,2.10^5 = 1,2.10^5 Pa → T2 = 290 . (1,2.10^5/1,0.10^5) = 290 . 1,2 = 348 K.<br>Kết quả: Đáp số: T2 = 348 K.<br>$\\begin{aligned}\\end{aligned}\\frac{p}{T}=const\\Rightarrow \\frac{10^5}{17+273}=\\frac{10^5+0,2.10^5}{T}\\Rightarrow T=348KWebsite: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":389,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng áp và định luật Charles","answer":"348","question":"Nam cần dùng một chai thủy tinh chứa khí ở điều kiện phòng (áp suất 1,0.10<sup>5</sup> Pa, nhiệt độ 170C) nhưng nút chai bị kẹt do ma sát hoặc co cứng. Nam hơ nóng chai để tăng áp suất khí bên trong, nút chai bật ra khi chênh lệch áp suất trong và ngoài đạt tối thiểu 0,2.105 Pa. Biết thể tích khí trong chai không đổi trong quá trình nung. Hỏi nhiệt độ của khí trong chai bằng bao nhiêu K để nút bật ra (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Công thức: thể tích không đổi (đẳng tích) nên áp dụng định luật Charles: p1/T1 = p2/T2 → T2 = T1.p2/p1.<br>Thay số: T1 = 17+273 = 290 K, p1 = 1,0.10^5 Pa, p2 = p1 + 0,2.10^5 = 1,2.10^5 Pa → T2 = 290 . (1,2.10^5/1,0.10^5) = 290 . 1,2 = 348 K.<br>Kết quả: Đáp số: T2 = 348 K.<br>$\\begin{aligned}\\end{aligned}\\frac{p}{T}=const\\Rightarrow \\frac{10^5}{17+273}=\\frac{10^5+0,2.10^5}{T}\\Rightarrow T=348KWebsite: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":668679,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":1,"options":["5,2.10<sup>−22</sup> J.","6,2. 10<sup>−21</sup> J.","6,2. 1023 J.","3,2.1023 J."],"question":"Cho hằng số Boltzmann là k = 1,38.10<sup>−23</sup>J/K. Động năng tịnh tiến trung bình của phân tử khí lí tưởng ở 250C có giá trị là","difficulty":"de","explanation":"$W_d=\\frac{3}{2}kT=\\frac{3}{2}.1,38.10^{−23}.\\left(25+273\\right)\\approx 6,2.10^{−21}J$","difficultySource":"ai"},"ex":[{"exam":390,"idx":4,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":1,"options":["5,2.10<sup>−22</sup> J.","6,2. 10<sup>−21</sup> J.","6,2. 1023 J.","3,2.1023 J."],"question":"Cho hằng số Boltzmann là k = 1,38.10<sup>−23</sup>J/K. Động năng tịnh tiến trung bình của phân tử khí lí tưởng ở 250C có giá trị là","difficulty":"de","explanation":"$W_d=\\frac{3}{2}kT=\\frac{3}{2}.1,38.10^{−23}.\\left(25+273\\right)\\approx 6,2.10^{−21}J$","difficultySource":"ai"}}]},{"id":668693,"nq":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một học sinh làm thí nghiệm xác định nhiệt nóng chảy riêng của nước đá với bộ dụng cụ gồm: Biến áp nguồn; oát kế; nhiệt lượng kế kèm dây điện trở; cốc và cân; đồng hồ bấm giây.<br>Bước 1:<br>+ Cho nước đá vào nhiệt lượng kế và hứng nước chảy ra bằng một chiếc cốc.<br>+ Sau khi nước chảy vào cốc khoảng một phút thì bỏ chiếc cốc này, bắt đầu cho nước chảy vào cốc ở trên cân trong thời gian 𝑡, xác định khối lượng 𝑚 của nước trong cốc trên cân. \\<br>Bước 2:<br>+ Bật biến áp nguồn, đọc số chỉ 𝒫 của oát kế.<br>+ Cho nước chảy thêm vào cốc trong thời gian 𝑡. Xác định khối lượng 𝑀 của nước trong cốc lúc này.<br>+ Ghi các số liệu theo mẫu Bảng bên dưới.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046618334-hinh-17.jpg\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Ở điều kiện tiêu chuẩn, nước đá tinh khiết tan ở nhiệt độ 00𝐶.","answer":true},{"text":"𝑚 là khối lượng nước đá tan do nhiệt lượng từ môi trường trong thời gian 𝑡.","answer":true},{"text":"𝑀 − 𝑚 là khối lượng nước đá tan do nhiệt lượng từ dây điện trở có dòng điện trong thời gian t.","answer":false},{"text":"Nhiệt nóng chảy riêng của nước đá đo được trong thí nghiệm là 2,8.10<sup>5</sup> 𝐽/𝑘𝑔.","answer":false}],"explanation":"a) đúng<br>Ở điều kiện tiêu chuẩn, nước đá tinh khiết tan ở nhiệt độ 00𝐶.<br>b) đúng<br>𝑚 là khối lượng nước đá tan do nhiệt lượng từ môi trường trong thời gian 𝑡.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) sai<br>𝑀 − 2𝑚 là khối lượng nước đá tan do nhiệt lượng từ dây điện trở có dòng điện trong thời gian t.<br>d) sai<br>$\\lambda =\\frac{Pt}{M−2m}=\\frac{24.180}{17,5.10^{−3}−2.2.10^{−3}}=3,2.10^5\\left(J/kg\\right)$","difficultySource":"ai"},"ex":[{"exam":390,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một học sinh làm thí nghiệm xác định nhiệt nóng chảy riêng của nước đá với bộ dụng cụ gồm: Biến áp nguồn; oát kế; nhiệt lượng kế kèm dây điện trở; cốc và cân; đồng hồ bấm giây.<br>Bước 1:<br>+ Cho nước đá vào nhiệt lượng kế và hứng nước chảy ra bằng một chiếc cốc.<br>+ Sau khi nước chảy vào cốc khoảng một phút thì bỏ chiếc cốc này, bắt đầu cho nước chảy vào cốc ở trên cân trong thời gian 𝑡, xác định khối lượng 𝑚 của nước trong cốc trên cân. \\<br>Bước 2:<br>+ Bật biến áp nguồn, đọc số chỉ 𝒫 của oát kế.<br>+ Cho nước chảy thêm vào cốc trong thời gian 𝑡. Xác định khối lượng 𝑀 của nước trong cốc lúc này.<br>+ Ghi các số liệu theo mẫu Bảng bên dưới.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046618334-hinh-17.jpg\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Ở điều kiện tiêu chuẩn, nước đá tinh khiết tan ở nhiệt độ 00𝐶.","answer":true},{"text":"𝑚 là khối lượng nước đá tan do nhiệt lượng từ môi trường trong thời gian 𝑡.","answer":true},{"text":"𝑀 − 𝑚 là khối lượng nước đá tan do nhiệt lượng từ dây điện trở có dòng điện trong thời gian t.","answer":false},{"text":"Nhiệt nóng chảy riêng của nước đá đo được trong thí nghiệm là 2,8.10<sup>5</sup> 𝐽/𝑘𝑔.","answer":false}],"explanation":"a) đúng<br>Ở điều kiện tiêu chuẩn, nước đá tinh khiết tan ở nhiệt độ 00𝐶.<br>b) đúng<br>𝑚 là khối lượng nước đá tan do nhiệt lượng từ môi trường trong thời gian 𝑡.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) sai<br>𝑀 − 2𝑚 là khối lượng nước đá tan do nhiệt lượng từ dây điện trở có dòng điện trong thời gian t.<br>d) sai<br>$\\lambda =\\frac{Pt}{M−2m}=\\frac{24.180}{17,5.10^{−3}−2.2.10^{−3}}=3,2.10^5\\left(J/kg\\right)$","difficultySource":"ai"}}]},{"id":668694,"nq":{"form":"bai_tap","type":"true_false","topic":"Điện từ trường và sóng điện từ","question":"Sóng vô tuyến cực ngắn tần số 20 MHz có thể được sử dụng để đo khoảng cách từ Trái Đất đến Mặt Trăng, bằng cách phát một tín hiệu từ Trái Đất tới Mặt Trăng và thu tín hiệu trở lại, đo khoảng thời gian từ khi phát đến khi nhận tín hiệu. Khoảng thời gian từ khi phát tới khi nhận được tín hiệu trở lại là 2,5 𝑠. Cho tốc độ của sóng này trong không khí ≈ 3.10<sup>8</sup> 𝑚/𝑠.","difficulty":"trung-binh","statements":[{"text":"Sóng vô tuyến cực ngắn được sử dụng để đo khoảng cách từ Trái Đất đến Mặt Trăng bởi khả năng đi xuyên qua tầng điện li của Trái Đất.","answer":true},{"text":"Sóng vô tuyến này thuộc loại sóng dọc.","answer":false},{"text":"Bước sóng của sóng vô tuyến này là 15 m.","answer":true},{"text":"Khoảng cách từ Trái Đất tới Mặt Trăng đo được là 750000 km.","answer":false}],"explanation":"a) đúng<br>Sóng vô tuyến cực ngắn được sử dụng để đo khoảng cách từ Trái Đất đến Mặt Trăng bởi khả năng đi xuyên qua tầng điện li của Trái Đất.  $Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>Sóng vô tuyến là sóng điện từ ⇒ sóng ngang<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>$\\lambda =\\frac{c}{f}=\\frac{3.10^8}{20.10^6}=15\\left(m\\right)$<br>d) sai<br>$s=c.\\frac{t}{2}=3.10^8.\\frac{2,5}{2}=375000.10^3m=375000km$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":390,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Điện từ trường và sóng điện từ","question":"Sóng vô tuyến cực ngắn tần số 20 MHz có thể được sử dụng để đo khoảng cách từ Trái Đất đến Mặt Trăng, bằng cách phát một tín hiệu từ Trái Đất tới Mặt Trăng và thu tín hiệu trở lại, đo khoảng thời gian từ khi phát đến khi nhận tín hiệu. Khoảng thời gian từ khi phát tới khi nhận được tín hiệu trở lại là 2,5 𝑠. Cho tốc độ của sóng này trong không khí ≈ 3.10<sup>8</sup> 𝑚/𝑠.","difficulty":"trung-binh","statements":[{"text":"Sóng vô tuyến cực ngắn được sử dụng để đo khoảng cách từ Trái Đất đến Mặt Trăng bởi khả năng đi xuyên qua tầng điện li của Trái Đất.","answer":true},{"text":"Sóng vô tuyến này thuộc loại sóng dọc.","answer":false},{"text":"Bước sóng của sóng vô tuyến này là 15 m.","answer":true},{"text":"Khoảng cách từ Trái Đất tới Mặt Trăng đo được là 750000 km.","answer":false}],"explanation":"a) đúng<br>Sóng vô tuyến cực ngắn được sử dụng để đo khoảng cách từ Trái Đất đến Mặt Trăng bởi khả năng đi xuyên qua tầng điện li của Trái Đất.  $Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>Sóng vô tuyến là sóng điện từ ⇒ sóng ngang<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>$\\lambda =\\frac{c}{f}=\\frac{3.10^8}{20.10^6}=15\\left(m\\right)$<br>d) sai<br>$s=c.\\frac{t}{2}=3.10^8.\\frac{2,5}{2}=375000.10^3m=375000km$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":668699,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình trạng thái khí lí tưởng","answer":"1,8","question":"Ở điều kiện tiêu chuẩn (nhiệt độ 00C và áp suất 1,0.10<sup>5</sup> Pa), không khí có khối lượng riêng là 1,29 kg/m3. Khối lượng riêng của không khí ở 200C và áp suất 1,5.10<sup>5</sup> Pa bằng bao nhiêu kg/m3 (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"de","explanation":"Công thức: từ phương trình trạng thái khí lí tưởng ở hai điều kiện (khối lượng khí không đổi): ρ = $\\rho_0$.(p/p0).(T0/T).<br>Thay số: $\\rho_0$ = 1,29 kg/m³, p0 = 1,0.10^5 Pa, T0 = 273 K, p = 1,5.10^5 Pa, T = 293 K → ρ = 1,29 . (1,5) . (273/293) ≈ 1,29 . 1,5 . 0,9317 ≈ 1,803 kg/m³.<br>Kết quả: làm tròn đến hàng phần mười, Đáp số: ρ ≈ 1,8 kg/m³.<br>$\\frac{p}{DT}=const\\Rightarrow \\frac{10^5}{1,29.273}=\\frac{1,5.10^5}{D.\\left(20+273\\right)}\\Rightarrow D\\approx 1,8\\left(kg/m^3\\right)$","difficultySource":"ai"},"ex":[{"exam":390,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình trạng thái khí lí tưởng","answer":"1,8","question":"Ở điều kiện tiêu chuẩn (nhiệt độ 00C và áp suất 1,0.10<sup>5</sup> Pa), không khí có khối lượng riêng là 1,29 kg/m3. Khối lượng riêng của không khí ở 200C và áp suất 1,5.10<sup>5</sup> Pa bằng bao nhiêu kg/m3 (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"de","explanation":"Công thức: từ phương trình trạng thái khí lí tưởng ở hai điều kiện (khối lượng khí không đổi): ρ = $\\rho_0$.(p/p0).(T0/T).<br>Thay số: $\\rho_0$ = 1,29 kg/m³, p0 = 1,0.10^5 Pa, T0 = 273 K, p = 1,5.10^5 Pa, T = 293 K → ρ = 1,29 . (1,5) . (273/293) ≈ 1,29 . 1,5 . 0,9317 ≈ 1,803 kg/m³.<br>Kết quả: làm tròn đến hàng phần mười, Đáp số: ρ ≈ 1,8 kg/m³.<br>$\\frac{p}{DT}=const\\Rightarrow \\frac{10^5}{1,29.273}=\\frac{1,5.10^5}{D.\\left(20+273\\right)}\\Rightarrow D\\approx 1,8\\left(kg/m^3\\right)$","difficultySource":"ai"}}]},{"id":669041,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Các tính chất của phân rã phóng xạ được ứng dụng để chế tạo pin nguyên tử. Pin nguyên tử có độ tin cậy cao, dung lượng pin có thể duy trì ở mức cao trong thời gian dài khi sử dụng nguồn phóng xạ có chu kì bán rã lớn. Pin thường được sử dụng cho các nhiệm vụ đòi hỏi yêu cầu cao như thiết bị y tế, các chuyến du hành vũ trụ dài ngày. Một pin nguyên tử có các thông số kĩ thuật:<br>Pu − 238; 2,5Ci. Biết chu kì bán rã của đồng vị phóng xạ sử dụng là 87,7 năm.","difficulty":"kho","statements":[{"text":"Pin nguyên tử này sử dụng đồng vị phóng xạ  238Pu.","answer":true},{"text":"Thông số 2,5Ci cho biết độ phóng xạ của lượng chất phóng xạ tại thời điểm ban đầu đưa vào pin.","answer":true},{"text":"Pin được sử dụng cho thiết bị điều hòa nhịp tim trong cơ thể bệnh nhân. Suất điện động của pin tỉ lệ thuận với độ phóng xạ. Người ta sẽ thay pin khi công suất giảm 50% so với giá trị công suất ban đầu. Sau 43,3 năm người bệnh cần thay pin cho thiết bị điều hòa nhịp tim.","answer":false},{"text":"Cho: 1 năm có 365 ngày; NA = 6, 02.1023 mol−1; 1Ci = 3, 7.10<sup>10</sup> Bq. Khối lượng tối thiểu của đồng vị phóng xạ đưa vào pin xấp xỉ là 0,05 g.","answer":false}],"explanation":"a) đúng<br>Pin nguyên tử này sử dụng đồng vị phóng xạ  238Pu.<br>b) đúng<br>Thông số 2,5Ci cho biết độ phóng xạ của lượng chất phóng xạ tại thời điểm ban đầu đưa vào pin.<br>c) sai<br>$P=\\frac{E^2}{R}\\Rightarrow \\frac{P}{P_0}={\\left(\\frac{E}{E_0}\\right)}^2=0,5\\Rightarrow \\frac{E}{E_0}=\\frac{1}{\\sqrt2}$<br>$\\frac{H}{H_0}=\\frac{E}{E_0}=2^{−\\frac{t}{T}}\\Rightarrow \\frac{1}{\\sqrt2}=2^{\\frac{−t}{87,3}}\\Rightarrow t=43,85$  năm<br>d) sai<br>$n=\\frac{m}{M}=\\frac{0,05}{238}=\\frac{1}{4760}mol$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$N=nN_A=\\frac{1}{4760}.6,02.10^{23}\\approx 1,265.10^{20}$<br>$H=\\lambda N=\\frac{ln2}{T}.N=\\frac{ln2}{87,7.365.24.60.60}.1,265.10^{20}\\approx 3,17.10^{10}Bq\\approx 0,86Ci$<br>Độ phóng xạ này không đạt yêu cầu để đưa vào pin","difficultySource":"ai"},"ex":[{"exam":391,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Các tính chất của phân rã phóng xạ được ứng dụng để chế tạo pin nguyên tử. Pin nguyên tử có độ tin cậy cao, dung lượng pin có thể duy trì ở mức cao trong thời gian dài khi sử dụng nguồn phóng xạ có chu kì bán rã lớn. Pin thường được sử dụng cho các nhiệm vụ đòi hỏi yêu cầu cao như thiết bị y tế, các chuyến du hành vũ trụ dài ngày. Một pin nguyên tử có các thông số kĩ thuật:<br>Pu − 238; 2,5Ci. Biết chu kì bán rã của đồng vị phóng xạ sử dụng là 87,7 năm.","difficulty":"kho","statements":[{"text":"Pin nguyên tử này sử dụng đồng vị phóng xạ  238Pu.","answer":true},{"text":"Thông số 2,5Ci cho biết độ phóng xạ của lượng chất phóng xạ tại thời điểm ban đầu đưa vào pin.","answer":true},{"text":"Pin được sử dụng cho thiết bị điều hòa nhịp tim trong cơ thể bệnh nhân. Suất điện động của pin tỉ lệ thuận với độ phóng xạ. Người ta sẽ thay pin khi công suất giảm 50% so với giá trị công suất ban đầu. Sau 43,3 năm người bệnh cần thay pin cho thiết bị điều hòa nhịp tim.","answer":false},{"text":"Cho: 1 năm có 365 ngày; NA = 6, 02.1023 mol−1; 1Ci = 3, 7.10<sup>10</sup> Bq. Khối lượng tối thiểu của đồng vị phóng xạ đưa vào pin xấp xỉ là 0,05 g.","answer":false}],"explanation":"a) đúng<br>Pin nguyên tử này sử dụng đồng vị phóng xạ  238Pu.<br>b) đúng<br>Thông số 2,5Ci cho biết độ phóng xạ của lượng chất phóng xạ tại thời điểm ban đầu đưa vào pin.<br>c) sai<br>$P=\\frac{E^2}{R}\\Rightarrow \\frac{P}{P_0}={\\left(\\frac{E}{E_0}\\right)}^2=0,5\\Rightarrow \\frac{E}{E_0}=\\frac{1}{\\sqrt2}$<br>$\\frac{H}{H_0}=\\frac{E}{E_0}=2^{−\\frac{t}{T}}\\Rightarrow \\frac{1}{\\sqrt2}=2^{\\frac{−t}{87,3}}\\Rightarrow t=43,85$  năm<br>d) sai<br>$n=\\frac{m}{M}=\\frac{0,05}{238}=\\frac{1}{4760}mol$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$N=nN_A=\\frac{1}{4760}.6,02.10^{23}\\approx 1,265.10^{20}$<br>$H=\\lambda N=\\frac{ln2}{T}.N=\\frac{ln2}{87,7.365.24.60.60}.1,265.10^{20}\\approx 3,17.10^{10}Bq\\approx 0,86Ci$<br>Độ phóng xạ này không đạt yêu cầu để đưa vào pin","difficultySource":"ai"}}]},{"id":669043,"nq":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một xi lanh đặt nằm ngang có pit-tông chuyển động được. Xi lanh chứa 2 g khí Helium (He), khối khí thực hiện chu trình biến đổi trạng thái từ (1) → (2) → (3) → (4) → (1) được biểu diễn trên đồ thị p − T như hình vẽ. Cho p0 = 1, 5.10<sup>5</sup> Pa, T0 = 300 K. Biết khối lượng mol của Helium là 4 g/mol; R = 8,31 J/(mol.K). Bỏ qua ma sát giữa xi lanh và pit-tông.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046625299-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quá trình biến đổi trạng thái của khối khí từ (1) → (2) là quá trình đẳng áp","answer":true},{"text":"Lượng khí Helium chứa trong bình là 0,25 mol.","answer":false},{"text":"Thể tích của khối khí khi ở trạng thái (4) là V4 = 2,77 lít.","answer":true},{"text":"Trong quá trình biến đổi từ trạng thái (1) sang trạng thái (2) thì công khối khí đã thực hiện là 831 J.","answer":false}],"explanation":"a) đúng<br>Quá trình biến đổi trạng thái của khối khí từ (1) → (2) là quá trình đẳng áp<br>b) sai<br>$n=\\frac{m}{M}=\\frac{2}{4}=0,5 mol$<br>c) đúng<br>$\\begin{aligned}\\end{aligned}\\frac{3p_0V_1}{T_0}=nR\\Rightarrow \\frac{3.1,5.10^5.V_1}{300}=0,5.8,31\\Rightarrow V_1=2,77.10^{−3}m^3=2,71ℓ=V_4Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>$A^/=p_{12}\\left(V_2−V_1\\right)=nR\\left(3T_0−T_0\\right)=2nRT_0=2.0,5.8,31.300=2493J$","difficultySource":"ai"},"ex":[{"exam":391,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một xi lanh đặt nằm ngang có pit-tông chuyển động được. Xi lanh chứa 2 g khí Helium (He), khối khí thực hiện chu trình biến đổi trạng thái từ (1) → (2) → (3) → (4) → (1) được biểu diễn trên đồ thị p − T như hình vẽ. Cho p0 = 1, 5.10<sup>5</sup> Pa, T0 = 300 K. Biết khối lượng mol của Helium là 4 g/mol; R = 8,31 J/(mol.K). Bỏ qua ma sát giữa xi lanh và pit-tông.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046625299-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quá trình biến đổi trạng thái của khối khí từ (1) → (2) là quá trình đẳng áp","answer":true},{"text":"Lượng khí Helium chứa trong bình là 0,25 mol.","answer":false},{"text":"Thể tích của khối khí khi ở trạng thái (4) là V4 = 2,77 lít.","answer":true},{"text":"Trong quá trình biến đổi từ trạng thái (1) sang trạng thái (2) thì công khối khí đã thực hiện là 831 J.","answer":false}],"explanation":"a) đúng<br>Quá trình biến đổi trạng thái của khối khí từ (1) → (2) là quá trình đẳng áp<br>b) sai<br>$n=\\frac{m}{M}=\\frac{2}{4}=0,5 mol$<br>c) đúng<br>$\\begin{aligned}\\end{aligned}\\frac{3p_0V_1}{T_0}=nR\\Rightarrow \\frac{3.1,5.10^5.V_1}{300}=0,5.8,31\\Rightarrow V_1=2,77.10^{−3}m^3=2,71ℓ=V_4Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>$A^/=p_{12}\\left(V_2−V_1\\right)=nR\\left(3T_0−T_0\\right)=2nRT_0=2.0,5.8,31.300=2493J$","difficultySource":"ai"}}]},{"id":669046,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"2,3","question":"Cho nhiệt hoá hơi của nước là 2,3.10<sup>6</sup> J/kg. Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 1 kg nước ở nhiệt độ sôi là bao nhiêu MJ (Làm tròn kết quả đến 1 chũ số sau dấu phảy thập phân)?","difficulty":"de","explanation":"Công thức: nhiệt lượng cần để hoá hơi hoàn toàn khối lượng m ở nhiệt độ sôi: Q = m.L (L là nhiệt hoá hơi riêng).<br>Thay số: m = 1 kg, L = 2,3.10^6 J/kg → Q = 1.2,3.10^6 = 2,3.10^6 J = 2,3 MJ.<br>Kết quả: Đáp số: Q = 2,3 MJ.<br>$\\begin{aligned}\\end{aligned}Q=mL=2,3.10^6J=2,3\\left(MJ\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":391,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"2,3","question":"Cho nhiệt hoá hơi của nước là 2,3.10<sup>6</sup> J/kg. Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 1 kg nước ở nhiệt độ sôi là bao nhiêu MJ (Làm tròn kết quả đến 1 chũ số sau dấu phảy thập phân)?","difficulty":"de","explanation":"Công thức: nhiệt lượng cần để hoá hơi hoàn toàn khối lượng m ở nhiệt độ sôi: Q = m.L (L là nhiệt hoá hơi riêng).<br>Thay số: m = 1 kg, L = 2,3.10^6 J/kg → Q = 1.2,3.10^6 = 2,3.10^6 J = 2,3 MJ.<br>Kết quả: Đáp số: Q = 2,3 MJ.<br>$\\begin{aligned}\\end{aligned}Q=mL=2,3.10^6J=2,3\\left(MJ\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":669050,"nq":{"form":"bai_tap","type":"short_answer","topic":"Động năng trung bình phân tử và nhiệt độ","answer":"155","question":"Một khối khí lí tưởng có động năng tịnh tiến trung bình của các phân tử khí bằng 0,02eV. Cho hằng số Boltzmann k = 1, 38.10<sup>−23</sup> J/K; 1eV = 1, 6.10<sup>−19</sup>J. Nhiệt độ của khối khí là bao nhiêu K (Làm tròn kết quả đến chữ số phần nguyên)?","difficulty":"de","explanation":"Công thức: động năng tịnh tiến trung bình của phân tử khí lí tưởng liên hệ với nhiệt độ: Wđ = (3/2)kT → T = 2Wđ/(3k).<br>Thay số: Wđ = 0,02 eV = 0,02.1,6.10^-19 = 3,2.10^-21 J; k = 1,38.10^-23 J/K → T = (2.3,2.10^-21)/(3.1,38.10^-23) = 6,4.10^-21/4,14.10^-23 ≈ 154,6 K.<br>Kết quả: làm tròn đến phần nguyên, Đáp số: T ≈ 155 K.<br>$W_d=\\frac{3}{2}kT\\Rightarrow 0,02.1,6.10^{−19}=\\frac{3}{2}.1,38.10^{−23}.T\\Rightarrow T\\approx 155K$","difficultySource":"ai"},"ex":[{"exam":391,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Động năng trung bình phân tử và nhiệt độ","answer":"155","question":"Một khối khí lí tưởng có động năng tịnh tiến trung bình của các phân tử khí bằng 0,02eV. Cho hằng số Boltzmann k = 1, 38.10<sup>−23</sup> J/K; 1eV = 1, 6.10<sup>−19</sup>J. Nhiệt độ của khối khí là bao nhiêu K (Làm tròn kết quả đến chữ số phần nguyên)?","difficulty":"de","explanation":"Công thức: động năng tịnh tiến trung bình của phân tử khí lí tưởng liên hệ với nhiệt độ: Wđ = (3/2)kT → T = 2Wđ/(3k).<br>Thay số: Wđ = 0,02 eV = 0,02.1,6.10^-19 = 3,2.10^-21 J; k = 1,38.10^-23 J/K → T = (2.3,2.10^-21)/(3.1,38.10^-23) = 6,4.10^-21/4,14.10^-23 ≈ 154,6 K.<br>Kết quả: làm tròn đến phần nguyên, Đáp số: T ≈ 155 K.<br>$W_d=\\frac{3}{2}kT\\Rightarrow 0,02.1,6.10^{−19}=\\frac{3}{2}.1,38.10^{−23}.T\\Rightarrow T\\approx 155K$","difficultySource":"ai"}}]},{"id":669090,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Hình sau mô tả sơ đồ hoạt động đơn giản hóa của cảm biến báo khói ion hóa. Nguồn phóng xạ α americium  ${}_{95}^{241}Am$  có hằng số phóng xạ 5,081.10<sup>−11</sup>s−1 được đặt giữa hai bản kim loại kết nối với một pin. Các hạt α phóng ra làm ion hóa không khí giữa hai bản kim loại và chuông báo không kêu. Nếu có khói chui vào buồng ion hoá, các ion sẽ kết hợp với các phần tử khói làm giảm dòng điện giữa 2 điện cực. Một mạch phát hiện sự suy giảm dòng điện và phát tín hiệu báo động.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046631892-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Một nguyên tử chứa hạt nhân  ${}_{95}^{241}Am$ có tất cả 95 hạt mang điện.","answer":false},{"text":"Không khí bị ion hóa tạo ra các hạt mang điện, các hạt mang điện dương chuyển động về bản A và hạt mang điện âm chuyển động về bản B","answer":false},{"text":"Nguồn americium ${}_{95}^{241}Am$  (khối lượng mol 241 g/mol) có khối lượng 0,20μg có độ phóng xạ là 25,4 kBq (làm tròn kết quả đến chữ số hàng phần mười).","answer":true},{"text":"Nếu một năm có 365 ngày thì sau 15 năm kể từ lúc bắt đầu sử dụng, độ phóng xạ của nguồn americium  ${}_{95}^{241}Am$ trong nguồn phóng xạ giảm còn 97,6% (làm tròn kết quả đến chữ số hàng phần mười).","answer":true}],"explanation":"a) sai<br>Nguyên tử có 95 proton và 95 electron là mang điện<br>b) sai<br>Hạt mang điện dương chuyển động về bản dương và hạt mang điện âm chuyển động về bản âm<br>c) đúng<br>$n=\\frac{m}{M}=\\frac{0,2.10^{−6}}{241}\\approx 8,3.10^{−10}mol$<br>$N=nN_A=8,3.10^{−10}.6,02.10^{23}\\approx 5.10^{14}$<br>$H=\\lambda N=5,081.10^{−11}.5.10^{14}\\approx 25,4.10^3Bq=25,4kBq$<br>d) đúng<br>$\\frac{H}{H_0}=e^{−\\lambda t}=e^{−5,081.10^{−11}.15.365.24.60.60}\\approx 0,976=97,6%$","difficultySource":"ai"},"ex":[{"exam":392,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Hình sau mô tả sơ đồ hoạt động đơn giản hóa của cảm biến báo khói ion hóa. Nguồn phóng xạ α americium  ${}_{95}^{241}Am$  có hằng số phóng xạ 5,081.10<sup>−11</sup>s−1 được đặt giữa hai bản kim loại kết nối với một pin. Các hạt α phóng ra làm ion hóa không khí giữa hai bản kim loại và chuông báo không kêu. Nếu có khói chui vào buồng ion hoá, các ion sẽ kết hợp với các phần tử khói làm giảm dòng điện giữa 2 điện cực. Một mạch phát hiện sự suy giảm dòng điện và phát tín hiệu báo động.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046631892-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Một nguyên tử chứa hạt nhân  ${}_{95}^{241}Am$ có tất cả 95 hạt mang điện.","answer":false},{"text":"Không khí bị ion hóa tạo ra các hạt mang điện, các hạt mang điện dương chuyển động về bản A và hạt mang điện âm chuyển động về bản B","answer":false},{"text":"Nguồn americium ${}_{95}^{241}Am$  (khối lượng mol 241 g/mol) có khối lượng 0,20μg có độ phóng xạ là 25,4 kBq (làm tròn kết quả đến chữ số hàng phần mười).","answer":true},{"text":"Nếu một năm có 365 ngày thì sau 15 năm kể từ lúc bắt đầu sử dụng, độ phóng xạ của nguồn americium  ${}_{95}^{241}Am$ trong nguồn phóng xạ giảm còn 97,6% (làm tròn kết quả đến chữ số hàng phần mười).","answer":true}],"explanation":"a) sai<br>Nguyên tử có 95 proton và 95 electron là mang điện<br>b) sai<br>Hạt mang điện dương chuyển động về bản dương và hạt mang điện âm chuyển động về bản âm<br>c) đúng<br>$n=\\frac{m}{M}=\\frac{0,2.10^{−6}}{241}\\approx 8,3.10^{−10}mol$<br>$N=nN_A=8,3.10^{−10}.6,02.10^{23}\\approx 5.10^{14}$<br>$H=\\lambda N=5,081.10^{−11}.5.10^{14}\\approx 25,4.10^3Bq=25,4kBq$<br>d) đúng<br>$\\frac{H}{H_0}=e^{−\\lambda t}=e^{−5,081.10^{−11}.15.365.24.60.60}\\approx 0,976=97,6%$","difficultySource":"ai"}}]},{"id":669097,"nq":{"form":"bai_tap","type":"short_answer","topic":"Cường độ điện trường của điện tích điểm","answer":"27,7","question":"Khói thải từ một số nhà máy có thể chứa nhiều hạt bụi gây ô nhiễm môi trường. Để giảm thiểu tác hại của hạt bụi người ta dùng máy lọc bụi tĩnh điện theo nguyên tắc cơ bản như sau: Hai bản kim loại phẳng tích điện trái dấu và đặt song song với nhau trong không khí được đặt thẳng đứng, cách nhau 40 cm chiều cao mỗi bản là L, hiệu điện thế giữa hai bản là 3.10<sup>4</sup> V. Không khí chứa các hạt bụi được thổi lên theo phương thẳng đứng qua khoảng giữa hai bản kim loại. Cho khối lượng mỗi hạt bụi là m = 10−9 kg; q = −2.10<sup>−15</sup>C. Khi bắt đầu đi vào giữa hai bản kim loại, các hạt bụi có vận tốc v0 = 12 m/s theo phương thẳng đứng hướng lên. Bỏ qua tác dụng của trọng lực. Để mọi hạt bụi đều bị dính vào bản kim loại thì giá trị nhỏ nhất của L là bao nhiêu mét (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"kho","explanation":"Công thức: hạt bụi chuyển động vào giữa hai bản với vận tốc thẳng đứng v0 không đổi (bỏ qua trọng lực) đồng thời chịu gia tốc ngang do lực điện a = |q|E/m = |q|U/(d.m); thời gian đi hết chiều cao bản t = L/v0; để mọi hạt (kể cả hạt ở sát một bản, cần lệch ngang hết cả khoảng cách d mới chắc chắn dính vào bản còn lại) đều bị hút dính trước khi ra khỏi vùng giữa hai bản: quãng đường lệch ngang x = 0,5.a.t² phải đạt ít nhất d ngay khi t = L/v0 → L_min = v0.√(2d/a).<br>Thay số: E = U/d = 3.10^4/0,4 = 7,5.10^4 V/m; a = |q|E/m = (2.10^-15.7,5.10^4)/10^-9 = 0,15 m/s² → L_min = 12.√(2.0,4/0,15) = 12.√5,333 = 12.2,309 ≈ 27,71 m.<br>Kết quả: làm tròn 1 chữ số thập phân, Đáp số: L_min ≈ 27,7 m.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224499731-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:217.1px;height:auto\" /><br>$E=\\frac{U}{d}=\\frac{3.10^4}{0,4}=75.10^3\\left(V/m\\right)$<br>$F=\\left|q\\right|E=2.10^{−15}.75.10^3=1,5.10^{−10}N$<br>$a=\\frac{F}{m}=\\frac{1,5.10^{−10}}{10^{−9}}=0,15\\left(m/s^2\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\left\\{\\begin{aligned}L\\ge v_0t <br>d=\\frac{1}{2}at^2\\end{aligned}\\right.\\Rightarrow L\\ge v_0\\sqrt{\\frac{2d}{a}}=12.\\sqrt{\\frac{2.0,4}{0,15}}\\approx 27,7m$","difficultySource":"ai"},"ex":[{"exam":392,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Cường độ điện trường của điện tích điểm","answer":"27,7","question":"Khói thải từ một số nhà máy có thể chứa nhiều hạt bụi gây ô nhiễm môi trường. Để giảm thiểu tác hại của hạt bụi người ta dùng máy lọc bụi tĩnh điện theo nguyên tắc cơ bản như sau: Hai bản kim loại phẳng tích điện trái dấu và đặt song song với nhau trong không khí được đặt thẳng đứng, cách nhau 40 cm chiều cao mỗi bản là L, hiệu điện thế giữa hai bản là 3.10<sup>4</sup> V. Không khí chứa các hạt bụi được thổi lên theo phương thẳng đứng qua khoảng giữa hai bản kim loại. Cho khối lượng mỗi hạt bụi là m = 10−9 kg; q = −2.10<sup>−15</sup>C. Khi bắt đầu đi vào giữa hai bản kim loại, các hạt bụi có vận tốc v0 = 12 m/s theo phương thẳng đứng hướng lên. Bỏ qua tác dụng của trọng lực. Để mọi hạt bụi đều bị dính vào bản kim loại thì giá trị nhỏ nhất của L là bao nhiêu mét (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"kho","explanation":"Công thức: hạt bụi chuyển động vào giữa hai bản với vận tốc thẳng đứng v0 không đổi (bỏ qua trọng lực) đồng thời chịu gia tốc ngang do lực điện a = |q|E/m = |q|U/(d.m); thời gian đi hết chiều cao bản t = L/v0; để mọi hạt (kể cả hạt ở sát một bản, cần lệch ngang hết cả khoảng cách d mới chắc chắn dính vào bản còn lại) đều bị hút dính trước khi ra khỏi vùng giữa hai bản: quãng đường lệch ngang x = 0,5.a.t² phải đạt ít nhất d ngay khi t = L/v0 → L_min = v0.√(2d/a).<br>Thay số: E = U/d = 3.10^4/0,4 = 7,5.10^4 V/m; a = |q|E/m = (2.10^-15.7,5.10^4)/10^-9 = 0,15 m/s² → L_min = 12.√(2.0,4/0,15) = 12.√5,333 = 12.2,309 ≈ 27,71 m.<br>Kết quả: làm tròn 1 chữ số thập phân, Đáp số: L_min ≈ 27,7 m.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224499731-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:217.1px;height:auto\" /><br>$E=\\frac{U}{d}=\\frac{3.10^4}{0,4}=75.10^3\\left(V/m\\right)$<br>$F=\\left|q\\right|E=2.10^{−15}.75.10^3=1,5.10^{−10}N$<br>$a=\\frac{F}{m}=\\frac{1,5.10^{−10}}{10^{−9}}=0,15\\left(m/s^2\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\left\\{\\begin{aligned}L\\ge v_0t <br>d=\\frac{1}{2}at^2\\end{aligned}\\right.\\Rightarrow L\\ge v_0\\sqrt{\\frac{2d}{a}}=12.\\sqrt{\\frac{2.0,4}{0,15}}\\approx 27,7m$","difficultySource":"ai"}}]},{"id":669537,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":3,"options":["2, 3.10<sup>6</sup> J là nhiệt nóng chảy của nước đá","2,3, 106 J là nhiệt hóa hơi của nước","2, 3.10<sup>6</sup> J/kg là nhiệt nóng chảy riêng của nước đá","2, 3.10<sup>6</sup> J/kg là nhiệt hóa hơi riêng của nước"],"question":"Mỗi kilôgam nước cần thu một lượng nhiệt là 2,3.10<sup>6</sup>J để bay hơi hoàn toàn ở nhiệt độ sôi và áp suất tiêu chuẩn. Nhận định nào sau đây là đúng?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt hóa hơi riêng $L$ của một chất là nhiệt lượng cần thu vào để $1\\,\\text{kg}$ chất đó hóa hơi hoàn toàn ở nhiệt độ sôi và áp suất tiêu chuẩn. Đơn vị của $L$ là $\\text{J/kg}$.</p><p class=\"text-base leading-relaxed my-2\">Theo đề, $1\\,\\text{kg}$ nước cần thu nhiệt lượng $2{,}3\\cdot 10^{6}\\,\\text{J}$ để bay hơi hoàn toàn ở nhiệt độ sôi và áp suất tiêu chuẩn. Vậy $L = 2{,}3\\cdot 10^{6}\\,\\text{J/kg}$ là nhiệt hóa hơi riêng của nước.</p><p class=\"text-base leading-relaxed my-2\">Xét các phương án:</p><p class=\"text-base leading-relaxed my-2\">A sai: đây không phải nhiệt nóng chảy của nước đá, và thiếu đơn vị $\\text{J/kg}$.</p><p class=\"text-base leading-relaxed my-2\">B sai: nhiệt hóa hơi là đại lượng cho một khối lượng xác định, không phải nhiệt hóa hơi riêng; đơn vị $\\text{J}$ không phù hợp với đại lượng riêng.</p><p class=\"text-base leading-relaxed my-2\">C sai: đây không phải nhiệt nóng chảy riêng của nước đá; quá trình được nêu là bay hơi.</p><p class=\"text-base leading-relaxed my-2\">D đúng.</p>","difficultySource":"ai"},"ex":[{"exam":393,"idx":4,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":3,"options":["2, 3.10<sup>6</sup> J là nhiệt nóng chảy của nước đá","2,3, 106 J là nhiệt hóa hơi của nước","2, 3.10<sup>6</sup> J/kg là nhiệt nóng chảy riêng của nước đá","2, 3.10<sup>6</sup> J/kg là nhiệt hóa hơi riêng của nước"],"question":"Mỗi kilôgam nước cần thu một lượng nhiệt là 2,3.10<sup>6</sup>J để bay hơi hoàn toàn ở nhiệt độ sôi và áp suất tiêu chuẩn. Nhận định nào sau đây là đúng?","difficulty":"de","explanation":"2, 3.10<sup>6</sup> J/kg là nhiệt hóa hơi riêng của nước","difficultySource":"ai"}}]},{"id":669545,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":1,"options":["29,3.10<sup>14</sup> Bq.","23,9.10<sup>11</sup> Bq.","23,9.10<sup>14</sup> Bq.","29,3.10<sup>11</sup> Bq."],"question":"Trong y học hạt nhân, một số bệnh lý về thận và máu có thể được chẩn đoán bằng kỹ thuật sử dụng đồng vị phóng xạ chromium  ${}_{24}^{51}Cr$ . Biết rằng chu kì bán rã của đồng vị này là 27,7 ngày, khối lượng mol nguyên tử của chromium là 51 g/mol. Một mẫu   ${}_{24}^{51}Cr$  nguyên chất có khối lượng 0,7mg thì có độ phóng xạ là","difficulty":"kho","explanation":"$n=\\frac{m}{M}=\\frac{0,7.10^{−3}}{51}\\approx 1,373.10^{−5} mol$<br>$N=nN_A=1,373.10^{−5}.6,02.10^{23}\\approx 8,265.10^{18}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}H=\\lambda N=\\frac{ln2}{T}.nN_A=\\frac{ln2}{27,7.24.60.60}.1,373.10^{−5}.6,02.10^{23}\\approx 23,9.10^{11}BqWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":393,"idx":12,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":1,"options":["29,3.10<sup>14</sup> Bq.","23,9.10<sup>11</sup> Bq.","23,9.10<sup>14</sup> Bq.","29,3.10<sup>11</sup> Bq."],"question":"Trong y học hạt nhân, một số bệnh lý về thận và máu có thể được chẩn đoán bằng kỹ thuật sử dụng đồng vị phóng xạ chromium  ${}_{24}^{51}Cr$ . Biết rằng chu kì bán rã của đồng vị này là 27,7 ngày, khối lượng mol nguyên tử của chromium là 51 g/mol. Một mẫu   ${}_{24}^{51}Cr$  nguyên chất có khối lượng 0,7mg thì có độ phóng xạ là","difficulty":"kho","explanation":"$n=\\frac{m}{M}=\\frac{0,7.10^{−3}}{51}\\approx 1,373.10^{−5} mol$<br>$N=nN_A=1,373.10^{−5}.6,02.10^{23}\\approx 8,265.10^{18}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}H=\\lambda N=\\frac{ln2}{T}.nN_A=\\frac{ln2}{27,7.24.60.60}.1,373.10^{−5}.6,02.10^{23}\\approx 23,9.10^{11}BqWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":669552,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Pin nguyên tử có khả năng duy trì dung lượng ở mức cao trong thời gian dài khi sử dụng nguồn phóng xạ có chu kì bán rã lớn. Một pin nguyên tử (hình bên) sử dụng plutonium-238 ( ${}_{94}^{238}Pu$ ), có chu kì bán rã là 87,8 năm. Tại thời điểm sản xuất, độ phóng xạ của pin này là 2,5Ci. Biết 1Ci = 3,7.10<sup>10</sup> Bq, tính 1 năm có 365 ngày, khối lượng mol nguyên tử của plutonium là 238 g/mol.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046640567-hinh-4.jpg\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Hạt nhân plutonium trong pin có 238 nucleon.","answer":true},{"text":"Sau 87,8 năm thì nguồn phóng xạ bị phân rã hết.","answer":false},{"text":"Pin được sử dụng cho thiết bị điều hòa nhịp tim trong cơ thể bệnh nhân. Suất điện động của pin tỉ lệ thuận với độ phóng xạ. Người ta sẽ thay pin khi công suất điện của pin giảm 50% so với giá trị ban đầu. Sau 43,3 năm người bệnh mới cần phẫu thuật để thay pin khác.","answer":false},{"text":"Tại thời điểm sản xuất, khối lượng của đồng vị phóng xạ   ${}_{94}^{238}Pu$ đưa vào pin là 146 mg.","answer":true}],"explanation":"a) đúng<br>$A=238$<br>b) sai<br>Sau T = 87,8 năm thì nguồn phóng xạ bị phân rã một nửa<br>c) sai<br>$P=\\frac{E^2}{R}\\Rightarrow \\frac{P}{P_0}={\\left(\\frac{E}{E_0}\\right)}^2=0,5\\Rightarrow \\frac{E}{E_0}=\\frac{1}{\\sqrt2}\\approx 0,71$<br>$\\frac{H}{H_0}=\\frac{E}{E_0}=2^{−\\frac{t}{T}}\\Rightarrow \\frac{1}{\\sqrt2}=2^{\\frac{−t}{87,3}}\\Rightarrow t\\approx 43,85$  năm<br>d) đúng<br>$H_0=\\lambda N_0=\\frac{ln2}{T}.N_0\\Rightarrow 2,5.3,7.10^{10}.\\frac{ln2}{87,7.365.24.60.60}.N_0\\Rightarrow N_0\\approx 3,7.10^{20}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$n_0=\\frac{N_0}{N_A}=\\frac{3,7.10^{20}}{6,02.10^{23}}\\approx 6m13.10^{−4}mol$<br>$m_0=n_0M=6,13.10^{−4}.238\\approx 0,146g$","difficultySource":"ai"},"ex":[{"exam":393,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Pin nguyên tử có khả năng duy trì dung lượng ở mức cao trong thời gian dài khi sử dụng nguồn phóng xạ có chu kì bán rã lớn. Một pin nguyên tử (hình bên) sử dụng plutonium-238 ( ${}_{94}^{238}Pu$ ), có chu kì bán rã là 87,8 năm. Tại thời điểm sản xuất, độ phóng xạ của pin này là 2,5Ci. Biết 1Ci = 3,7.10<sup>10</sup> Bq, tính 1 năm có 365 ngày, khối lượng mol nguyên tử của plutonium là 238 g/mol.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046640567-hinh-4.jpg\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Hạt nhân plutonium trong pin có 238 nucleon.","answer":true},{"text":"Sau 87,8 năm thì nguồn phóng xạ bị phân rã hết.","answer":false},{"text":"Pin được sử dụng cho thiết bị điều hòa nhịp tim trong cơ thể bệnh nhân. Suất điện động của pin tỉ lệ thuận với độ phóng xạ. Người ta sẽ thay pin khi công suất điện của pin giảm 50% so với giá trị ban đầu. Sau 43,3 năm người bệnh mới cần phẫu thuật để thay pin khác.","answer":false},{"text":"Tại thời điểm sản xuất, khối lượng của đồng vị phóng xạ   ${}_{94}^{238}Pu$ đưa vào pin là 146 mg.","answer":true}],"explanation":"a) đúng<br>$A=238$<br>b) sai<br>Sau T = 87,8 năm thì nguồn phóng xạ bị phân rã một nửa<br>c) sai<br>$P=\\frac{E^2}{R}\\Rightarrow \\frac{P}{P_0}={\\left(\\frac{E}{E_0}\\right)}^2=0,5\\Rightarrow \\frac{E}{E_0}=\\frac{1}{\\sqrt2}\\approx 0,71$<br>$\\frac{H}{H_0}=\\frac{E}{E_0}=2^{−\\frac{t}{T}}\\Rightarrow \\frac{1}{\\sqrt2}=2^{\\frac{−t}{87,3}}\\Rightarrow t\\approx 43,85$  năm<br>d) đúng<br>$H_0=\\lambda N_0=\\frac{ln2}{T}.N_0\\Rightarrow 2,5.3,7.10^{10}.\\frac{ln2}{87,7.365.24.60.60}.N_0\\Rightarrow N_0\\approx 3,7.10^{20}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$n_0=\\frac{N_0}{N_A}=\\frac{3,7.10^{20}}{6,02.10^{23}}\\approx 6m13.10^{−4}mol$<br>$m_0=n_0M=6,13.10^{−4}.238\\approx 0,146g$","difficultySource":"ai"}}]},{"id":669940,"nq":{"form":"bai_tap","type":"true_false","topic":"Lực từ. Cảm ứng từ","question":"Một máy gia tốc hạt Cyclotron gồm hai hộp rỗng bằng kim loại hình chữ D cách nhau một khe hẹp như hình vẽ. Vùng không gian trong mỗi hộp D có từ trường đều với cảm ứng từ B = 0,6 T, đường sức từ vuông góc với mặt hộp D (như hình vẽ). Đặt một điện áp xoay chiều thích hợp u vào máy để các hạt điện tích được tăng tốc khi mỗi lần chúng bay qua khe. Trong thí nghiệm, một chùm hạt được gia tốc, thời gian mỗi lần một điện tích q chuyển động được 0,5 vòng trong hộp D là 5.10<sup>−8</sup> s. Trong lần cuối cùng trước khi thoát khỏi máy, quỹ đạo dòng hạt có bán kính 0,5 m và cường độ trung bình I = 4,2mA, sau đó chúng bay ra đập vào một cái bia. Biết rằng 80% động năng của hạt chuyển hóa thành nhiệt làm nóng<br>bia;toàn bộ nhiệt lượng bia nhận được lại được hấp thụ bởi dòng nước chảy qua bia có lưu lượng ổn định. Cho khối lượng điện tích là m, bỏ qua tác dụng của trọng lực lên điện tích, không xét đến sự thay đổi khối lượng tương đối tính; lực từ tác dụng lên điện tích q chuyển động với vận tốcvtheo phương vuông góc với cảm ứng từ B có độ lớn là f = Bv|q|; nhiệt dung riêng của nước là c = 4200 J/kgK; khối lượng riêng của nước là 1000 kg/m3.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046646822-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong mỗi hộp D, bán kính quỹ đạo của điện tích được xác định bằng biểu thức  $R=\\frac{mv}{B\\left|q\\right|}$","answer":true},{"text":"Có thể thay đổi bán kính quỹ đạo của điện tích bằng cách điều chỉnh điện áp xoay chiều đặt vào máy.","answer":true},{"text":"Trong mỗi hộp D, lực do từ trường tác dụng lên mỗi điện tích có tác dụng tăng tốc cho điện tích.","answer":false},{"text":"Nếu dòng nước ngay sau khi làm mát bia được tăng thêm 100C thì lưu lượng của dòng nước này là 0,967 lít/giây.","answer":false}],"explanation":"a) đúng<br>$F=ma_{ht}\\Rightarrow \\left|q\\right|vB=m.\\frac{v^2}{R}\\Rightarrow R=\\frac{mv}{\\left|q\\right|B}$<br>b) đúng<br>Thay đổi u  $\\Rightarrow$  Thay đổi v trong điện trường  $\\Rightarrow$  Thay đổi R<br>c) sai<br>Lực do điện trường tác dụng mới có tác dụng tăng tốc, còn lực từ không sinh công<br>d) sai<br>$T=\\frac{2\\pi R}{v}\\Rightarrow 2.5.10^{−8}=\\frac{2\\pi .0,5}{v}\\Rightarrow v=10^7\\pi \\left(m/s\\right)$<br>$\\left|q\\right|=IT=4,2.10^{−3}.2.5.10^{−8}=4,2.10^{−10}C$<br>$W_d=\\frac{1}{2}mv^2=\\frac{1}{2}.\\left|q\\right|vBR=\\frac{1}{2}.4,2.10^{−10}.10^7\\pi .0,6.0,5=6,3\\pi .10^{−4}J$<br>Xét trong  $t=1s$  thì  $N=\\frac{I.t}{\\left|q\\right|}=\\frac{4,2.10^{−3}}{4,2.10^{−10}}=10^7$<br>$Q=0,8NW_d=0,8.10^7.6,3\\pi .10^{−4}=5040\\pi J$<br>$Q=m_nc\\Delta t\\Rightarrow 5040\\pi =m_n.4200.10\\Rightarrow m_n\\approx 0,377kg$<br>$\\begin{aligned}\\end{aligned}V_n=\\frac{m_n}{D_n}=\\frac{0,377}{10^3}m^3=0,377ℓWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":394,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Lực từ. Cảm ứng từ","question":"Một máy gia tốc hạt Cyclotron gồm hai hộp rỗng bằng kim loại hình chữ D cách nhau một khe hẹp như hình vẽ. Vùng không gian trong mỗi hộp D có từ trường đều với cảm ứng từ B = 0,6 T, đường sức từ vuông góc với mặt hộp D (như hình vẽ). Đặt một điện áp xoay chiều thích hợp u vào máy để các hạt điện tích được tăng tốc khi mỗi lần chúng bay qua khe. Trong thí nghiệm, một chùm hạt được gia tốc, thời gian mỗi lần một điện tích q chuyển động được 0,5 vòng trong hộp D là 5.10<sup>−8</sup> s. Trong lần cuối cùng trước khi thoát khỏi máy, quỹ đạo dòng hạt có bán kính 0,5 m và cường độ trung bình I = 4,2mA, sau đó chúng bay ra đập vào một cái bia. Biết rằng 80% động năng của hạt chuyển hóa thành nhiệt làm nóng<br>bia;toàn bộ nhiệt lượng bia nhận được lại được hấp thụ bởi dòng nước chảy qua bia có lưu lượng ổn định. Cho khối lượng điện tích là m, bỏ qua tác dụng của trọng lực lên điện tích, không xét đến sự thay đổi khối lượng tương đối tính; lực từ tác dụng lên điện tích q chuyển động với vận tốcvtheo phương vuông góc với cảm ứng từ B có độ lớn là f = Bv|q|; nhiệt dung riêng của nước là c = 4200 J/kgK; khối lượng riêng của nước là 1000 kg/m3.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046646822-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong mỗi hộp D, bán kính quỹ đạo của điện tích được xác định bằng biểu thức  $R=\\frac{mv}{B\\left|q\\right|}$","answer":true},{"text":"Có thể thay đổi bán kính quỹ đạo của điện tích bằng cách điều chỉnh điện áp xoay chiều đặt vào máy.","answer":true},{"text":"Trong mỗi hộp D, lực do từ trường tác dụng lên mỗi điện tích có tác dụng tăng tốc cho điện tích.","answer":false},{"text":"Nếu dòng nước ngay sau khi làm mát bia được tăng thêm 100C thì lưu lượng của dòng nước này là 0,967 lít/giây.","answer":false}],"explanation":"a) đúng<br>$F=ma_{ht}\\Rightarrow \\left|q\\right|vB=m.\\frac{v^2}{R}\\Rightarrow R=\\frac{mv}{\\left|q\\right|B}$<br>b) đúng<br>Thay đổi u  $\\Rightarrow$  Thay đổi v trong điện trường  $\\Rightarrow$  Thay đổi R<br>c) sai<br>Lực do điện trường tác dụng mới có tác dụng tăng tốc, còn lực từ không sinh công<br>d) sai<br>$T=\\frac{2\\pi R}{v}\\Rightarrow 2.5.10^{−8}=\\frac{2\\pi .0,5}{v}\\Rightarrow v=10^7\\pi \\left(m/s\\right)$<br>$\\left|q\\right|=IT=4,2.10^{−3}.2.5.10^{−8}=4,2.10^{−10}C$<br>$W_d=\\frac{1}{2}mv^2=\\frac{1}{2}.\\left|q\\right|vBR=\\frac{1}{2}.4,2.10^{−10}.10^7\\pi .0,6.0,5=6,3\\pi .10^{−4}J$<br>Xét trong  $t=1s$  thì  $N=\\frac{I.t}{\\left|q\\right|}=\\frac{4,2.10^{−3}}{4,2.10^{−10}}=10^7$<br>$Q=0,8NW_d=0,8.10^7.6,3\\pi .10^{−4}=5040\\pi J$<br>$Q=m_nc\\Delta t\\Rightarrow 5040\\pi =m_n.4200.10\\Rightarrow m_n\\approx 0,377kg$<br>$\\begin{aligned}\\end{aligned}V_n=\\frac{m_n}{D_n}=\\frac{0,377}{10^3}m^3=0,377ℓWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":669943,"nq":{"form":"bai_tap","type":"true_false","topic":"Nóng chảy, đông đặc, hoá hơi, ngưng tụ","question":"Quạt điều hòa hoạt động dựa trên nguyên lý bốc hơi tự nhiên của nước với các bước hoạt động chính như sau: Máy bơm nước dẫn từ khay nước lên tấm làm mát Cooling Pad được thiết kế dạng lưới tổ ong, làm tăng diện tích bề mặt tiếp xúc với không khí, không khí nóng được hút từ bên ngoài vào đi qua tấm làm mát, nước ở bề mặt tấm làm mát sẽ hấp thụ nhiệt của luồng khí nóng để bay hơi tự nhiên, khiến nhiệt độ không khí được giảm xuống và hình thành luồng không khí mát. Xét một quạt điều hòa<br>đang hoạt động ổn định:lưu lượng gió 50 lít/giây, nhiệt độ không khí hút vào là 360C, nhiệt độ không khí thổi ra là 310C, nhiệt hóa hơi riêng của nước là 2,45.10<sup>6</sup> J/kg; khối lượng riêng của không khí trong phòng là 1,2 kg/m3 và nhiệt dung riêng của không khí là 1000 J/(kg.K).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046647185-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Khi quạt hoạt động, nước nhận nhiệt từ động cơ của quạt để bay hơi.","answer":false},{"text":"Chênh lệch nhiệt độ không khí trước và sau khi đi qua quạt bằng 278 K.","answer":false},{"text":"Hoạt động của quạt điều hòa liên quan đến hiện tượng hóa hơi.","answer":true},{"text":"Coi sự thay đổi nhiệt độ không khí đi qua quạt chỉ do sự hấp thụ nhiệt của nước khi bay hơi. Lượng nước bị bay hơi sau 1 giờ quạt hoạt động bằng 0,48 kg. (Kết quả làm tròn đến chữ số hàng phần trăm).","answer":false}],"explanation":"a) sai<br>Nước nhận nhiệt từ không khí nóng<br>b) sai<br>$\\Delta T\\left(K\\right)=\\Delta t\\left({}^0C\\right)=36−31=5$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>Hoạt động của quạt điều hòa liên quan đến hiện tượng hóa hơi.<br>d) sai<br>$m_{kk}=V_{kk}D_{kk}=50.10^{−3}.60.60.1,2=216kg$<br>$m_{kk}c\\Delta t=m_hL\\Rightarrow 216.1000.5=m_h.2,45.10^6\\Rightarrow m_h\\approx 0,44kg$","difficultySource":"ai"},"ex":[{"exam":394,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Nóng chảy, đông đặc, hoá hơi, ngưng tụ","question":"Quạt điều hòa hoạt động dựa trên nguyên lý bốc hơi tự nhiên của nước với các bước hoạt động chính như sau: Máy bơm nước dẫn từ khay nước lên tấm làm mát Cooling Pad được thiết kế dạng lưới tổ ong, làm tăng diện tích bề mặt tiếp xúc với không khí, không khí nóng được hút từ bên ngoài vào đi qua tấm làm mát, nước ở bề mặt tấm làm mát sẽ hấp thụ nhiệt của luồng khí nóng để bay hơi tự nhiên, khiến nhiệt độ không khí được giảm xuống và hình thành luồng không khí mát. Xét một quạt điều hòa<br>đang hoạt động ổn định:lưu lượng gió 50 lít/giây, nhiệt độ không khí hút vào là 360C, nhiệt độ không khí thổi ra là 310C, nhiệt hóa hơi riêng của nước là 2,45.10<sup>6</sup> J/kg; khối lượng riêng của không khí trong phòng là 1,2 kg/m3 và nhiệt dung riêng của không khí là 1000 J/(kg.K).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046647185-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Khi quạt hoạt động, nước nhận nhiệt từ động cơ của quạt để bay hơi.","answer":false},{"text":"Chênh lệch nhiệt độ không khí trước và sau khi đi qua quạt bằng 278 K.","answer":false},{"text":"Hoạt động của quạt điều hòa liên quan đến hiện tượng hóa hơi.","answer":true},{"text":"Coi sự thay đổi nhiệt độ không khí đi qua quạt chỉ do sự hấp thụ nhiệt của nước khi bay hơi. Lượng nước bị bay hơi sau 1 giờ quạt hoạt động bằng 0,48 kg. (Kết quả làm tròn đến chữ số hàng phần trăm).","answer":false}],"explanation":"a) sai<br>Nước nhận nhiệt từ không khí nóng<br>b) sai<br>$\\Delta T\\left(K\\right)=\\Delta t\\left({}^0C\\right)=36−31=5$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>Hoạt động của quạt điều hòa liên quan đến hiện tượng hóa hơi.<br>d) sai<br>$m_{kk}=V_{kk}D_{kk}=50.10^{−3}.60.60.1,2=216kg$<br>$m_{kk}c\\Delta t=m_hL\\Rightarrow 216.1000.5=m_h.2,45.10^6\\Rightarrow m_h\\approx 0,44kg$","difficultySource":"ai"}}]},{"id":669948,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"32","question":"Một cái cổng chào bằng hơi có dạng nửa hình xuyến như hình vẽ bên, chân của cổng chào tiếp xúc với mặt đất theo một đường tròn có đường kính 1 m. Bỏ qua độ dày của lớp vỏ cổng chào. Cổng chào được bơm đầy khí hidro ở áp suất 1,2.10<sup>5</sup> Pa, nhiệt độ 300C. Ban đầu trong cổng không có khí, cổng được bơm khí Hidro với tốc độ 40 g/phút. Cho khối lượng mol phân tử của hidro bằng 2 g. Thời gian bơm cổng bằng bao nhiêu phút (làm tròn kết quả đến chữ số hàng đơn vị)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046647660-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Công thức: cổng chào là nửa hình xuyến (nửa torus) với bán kính ống (bán kính nhỏ) r và bán kính vành (bán kính lớn) R; từ hình vẽ: chiều cao thông thủy (mặt trong) R−r = 5 m và bề rộng ngoài cùng 2(R+r) = 12 m, kết hợp với đường kính chân ống là 1 m (r = 0,5 m) cho R = 5,5 m. Thể tích nửa hình xuyến: V = π².R.r². Dùng phương trình trạng thái khí lí tưởng để tìm số mol và khối lượng khí cần bơm: n = pV/(RT), m = n.M; thời gian bơm t = m/(tốc độ bơm).<br>Thay số: V = π².5,5.0,5² = π².1,375 ≈ 13,57 m³; T = 30+273 = 303 K → n = (1,2.10^5.13,57)/(8,31.303) ≈ 647,0 mol → m = 647,0.2 ≈ 1294,0 g; t = 1294,0/40 ≈ 32,35 phút.<br>Kết quả: làm tròn đến hàng đơn vị, Đáp số: t ≈ 32 phút.<br>Cách 1:<br>Cắt nửa hình, xoay ngược và ghép lại ta được hình vẽ:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046647872-hinh-15.png\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Thực hiện duỗi thẳng tiếp ta được hình trụ có chiều cao bằng  $\\frac{1}{4}$  chu vi đường tròn bé +  $\\frac{1}{4}$  chu vi đường tròn lớn<br>Thể tích:  $V=Sh=\\pi r^2.\\frac{2\\pi R_t+2\\pi R_N}{4}=\\frac{1}{2}\\pi^2r^2\\left(R_t+R_N\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow V=\\frac{1}{2}\\pi^2.0,5^2.\\left(5+6\\right)=1,375\\pi^2$<br>Cách 2: Định lý trọng tâm pappus: V = ad với:<br>A là diện tích của hình phẳng quay, d là quãng đường di chuyển bởi tâm của hình phẳng quay đó<br>* Áp dụng:<br>Diện tích hình phẳng quay là:  $A=\\pi r^2=\\pi .0,5^2=0,25\\pi \\left(m^2\\right)$<br>Khoảng cách từ trọng tâm của hình phẳng đến trục quay là  $R=5,5m$<br>Tâm của hình phẳng quay di chuyển được nửa chu vi đường tròn là  $d=\\pi R=5,5\\pi \\left(m\\right)$<br>Thể tích:  $V=Ad=0,25\\pi .5,5\\pi =1,375\\pi^2$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046648027-hinh-16.png\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Thời gian bơm:  $t=\\frac{1,29.10^3}{40}\\approx$  32 phút<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046648193-hinh-17.png\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":394,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"32","question":"Một cái cổng chào bằng hơi có dạng nửa hình xuyến như hình vẽ bên, chân của cổng chào tiếp xúc với mặt đất theo một đường tròn có đường kính 1 m. Bỏ qua độ dày của lớp vỏ cổng chào. Cổng chào được bơm đầy khí hidro ở áp suất 1,2.10<sup>5</sup> Pa, nhiệt độ 300C. Ban đầu trong cổng không có khí, cổng được bơm khí Hidro với tốc độ 40 g/phút. Cho khối lượng mol phân tử của hidro bằng 2 g. Thời gian bơm cổng bằng bao nhiêu phút (làm tròn kết quả đến chữ số hàng đơn vị)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046647660-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Công thức: cổng chào là nửa hình xuyến (nửa torus) với bán kính ống (bán kính nhỏ) r và bán kính vành (bán kính lớn) R; từ hình vẽ: chiều cao thông thủy (mặt trong) R−r = 5 m và bề rộng ngoài cùng 2(R+r) = 12 m, kết hợp với đường kính chân ống là 1 m (r = 0,5 m) cho R = 5,5 m. Thể tích nửa hình xuyến: V = π².R.r². Dùng phương trình trạng thái khí lí tưởng để tìm số mol và khối lượng khí cần bơm: n = pV/(RT), m = n.M; thời gian bơm t = m/(tốc độ bơm).<br>Thay số: V = π².5,5.0,5² = π².1,375 ≈ 13,57 m³; T = 30+273 = 303 K → n = (1,2.10^5.13,57)/(8,31.303) ≈ 647,0 mol → m = 647,0.2 ≈ 1294,0 g; t = 1294,0/40 ≈ 32,35 phút.<br>Kết quả: làm tròn đến hàng đơn vị, Đáp số: t ≈ 32 phút.<br>Cách 1:<br>Cắt nửa hình, xoay ngược và ghép lại ta được hình vẽ:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046647872-hinh-15.png\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Thực hiện duỗi thẳng tiếp ta được hình trụ có chiều cao bằng  $\\frac{1}{4}$  chu vi đường tròn bé +  $\\frac{1}{4}$  chu vi đường tròn lớn<br>Thể tích:  $V=Sh=\\pi r^2.\\frac{2\\pi R_t+2\\pi R_N}{4}=\\frac{1}{2}\\pi^2r^2\\left(R_t+R_N\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow V=\\frac{1}{2}\\pi^2.0,5^2.\\left(5+6\\right)=1,375\\pi^2$<br>Cách 2: Định lý trọng tâm pappus: V = ad với:<br>A là diện tích của hình phẳng quay, d là quãng đường di chuyển bởi tâm của hình phẳng quay đó<br>* Áp dụng:<br>Diện tích hình phẳng quay là:  $A=\\pi r^2=\\pi .0,5^2=0,25\\pi \\left(m^2\\right)$<br>Khoảng cách từ trọng tâm của hình phẳng đến trục quay là  $R=5,5m$<br>Tâm của hình phẳng quay di chuyển được nửa chu vi đường tròn là  $d=\\pi R=5,5\\pi \\left(m\\right)$<br>Thể tích:  $V=Ad=0,25\\pi .5,5\\pi =1,375\\pi^2$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046648027-hinh-16.png\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Thời gian bơm:  $t=\\frac{1,29.10^3}{40}\\approx$  32 phút<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046648193-hinh-17.png\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":669965,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":1,"options":["5,48.10<sup>9</sup> năm.","6,20.10<sup>9</sup> năm.","4,91.10<sup>9</sup> năm.","7,14.10<sup>9</sup> năm."],"question":"Cho biết  ${}_{92}^{238}U$ và   ${}_{92}^{235}U$ là các chất phóng xạ có chu kì bán rã lần lượt là T1 = 4,5.10<sup>9</sup> năm và T2 = 7,13.10<sup>8</sup> năm. Hiện nay trong quặng urani thiên nhiên có lẫn   ${}_{92}^{238}U$ và   ${}_{92}^{235}U$ theo tỉ lệ số hạt là 160 : 1. Giả thiết ở thời điểm tạo thành Trái đất thì tỉ lệ số hạt   ${}_{92}^{238}U$ và  ${}_{92}^{235}U$ là 1 : 1. Tuổi của Trái đất là bao nhiêu?","difficulty":"trung-binh","explanation":"$N=N_0.2^{−\\frac{t}{T}}\\Rightarrow \\frac{N_1}{N_2}=\\frac{N_{01}}{N_{02}}.\\frac{2^{−\\frac{t}{T_1}}}{2^{−\\frac{t}{T_2}}}\\Rightarrow 160=\\frac{2^{−\\frac{t}{4,5}}}{2^{−\\frac{t}{0,713}}}\\Rightarrow t\\approx 6,20$  (tỉ năm)","difficultySource":"ai"},"ex":[{"exam":395,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":1,"options":["5,48.10<sup>9</sup> năm.","6,20.10<sup>9</sup> năm.","4,91.10<sup>9</sup> năm.","7,14.10<sup>9</sup> năm."],"question":"Cho biết  ${}_{92}^{238}U$ và   ${}_{92}^{235}U$ là các chất phóng xạ có chu kì bán rã lần lượt là T1 = 4,5.10<sup>9</sup> năm và T2 = 7,13.10<sup>8</sup> năm. Hiện nay trong quặng urani thiên nhiên có lẫn   ${}_{92}^{238}U$ và   ${}_{92}^{235}U$ theo tỉ lệ số hạt là 160 : 1. Giả thiết ở thời điểm tạo thành Trái đất thì tỉ lệ số hạt   ${}_{92}^{238}U$ và  ${}_{92}^{235}U$ là 1 : 1. Tuổi của Trái đất là bao nhiêu?","difficulty":"trung-binh","explanation":"$N=N_0.2^{−\\frac{t}{T}}\\Rightarrow \\frac{N_1}{N_2}=\\frac{N_{01}}{N_{02}}.\\frac{2^{−\\frac{t}{T_1}}}{2^{−\\frac{t}{T_2}}}\\Rightarrow 160=\\frac{2^{−\\frac{t}{4,5}}}{2^{−\\frac{t}{0,713}}}\\Rightarrow t\\approx 6,20$  (tỉ năm)","difficultySource":"ai"}}]},{"id":669970,"nq":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Một máy bay chở khách có thể tích cabin 150 m3. Khi máy bay đang ở mặt đất, không khí bên trong cabin có cùng điều kiện với không khí bên ngoài: áp suất 100 kPa và nhiệt độ 250C. Sau đó, máy bay cất cánh và bay lên đến độ cao hành trình. Tại độ cao này, hệ thống điều áp duy trì áp suất không khí bên trong cabin là 80 kPa và nhiệt độ không khí bên trong cabin là 200C. Biết khối lượng mol của không khí 29 g/mol.","difficulty":"trung-binh","statements":[{"text":"Số mol không khí cần có trong cabin ở độ cao hành trình là 4,9.10<sup>3</sup> mol.","answer":true},{"text":"Khối lượng không khí mà hệ thống điều áp đã phải xả bớt ra khỏi cabin là 25 kg.","answer":false},{"text":"Khi lên cao áp suất khí quyển giảm.","answer":true},{"text":"Theo thang nhiệt độ kelvin, nhiệt độ không khí trong cabin giảm 278 K khi lên đến độ cao hành trình.","answer":false}],"explanation":"a) đúng<br>$\\frac{pV^/}{T}=nR\\Rightarrow \\frac{80.10^3.150}{20+273}=n.8,31\\Rightarrow n\\approx 4,93.10^3\\left(mol\\right)$<br>b) sai<br>$\\begin{aligned}\\end{aligned}\\frac{p_0V}{T_0}=n_0R\\Rightarrow \\frac{100.10^3.150}{25+273}=n_0.8,31\\Rightarrow n_0\\approx 6,06.10^3\\left(mol\\right) Website: thukhoadaihoc.vn$<br>c) đúng<br>Khi lên cao áp suất khí quyển giảm.<br>d) sai<br>$\\Delta T\\left(K\\right)=\\Delta t\\left({}^0C\\right)=25−20$","difficultySource":"ai"},"ex":[{"exam":395,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Một máy bay chở khách có thể tích cabin 150 m3. Khi máy bay đang ở mặt đất, không khí bên trong cabin có cùng điều kiện với không khí bên ngoài: áp suất 100 kPa và nhiệt độ 250C. Sau đó, máy bay cất cánh và bay lên đến độ cao hành trình. Tại độ cao này, hệ thống điều áp duy trì áp suất không khí bên trong cabin là 80 kPa và nhiệt độ không khí bên trong cabin là 200C. Biết khối lượng mol của không khí 29 g/mol.","difficulty":"trung-binh","statements":[{"text":"Số mol không khí cần có trong cabin ở độ cao hành trình là 4,9.10<sup>3</sup> mol.","answer":true},{"text":"Khối lượng không khí mà hệ thống điều áp đã phải xả bớt ra khỏi cabin là 25 kg.","answer":false},{"text":"Khi lên cao áp suất khí quyển giảm.","answer":true},{"text":"Theo thang nhiệt độ kelvin, nhiệt độ không khí trong cabin giảm 278 K khi lên đến độ cao hành trình.","answer":false}],"explanation":"a) đúng<br>$\\frac{pV^/}{T}=nR\\Rightarrow \\frac{80.10^3.150}{20+273}=n.8,31\\Rightarrow n\\approx 4,93.10^3\\left(mol\\right)$<br>b) sai<br>$\\begin{aligned}\\end{aligned}\\frac{p_0V}{T_0}=n_0R\\Rightarrow \\frac{100.10^3.150}{25+273}=n_0.8,31\\Rightarrow n_0\\approx 6,06.10^3\\left(mol\\right) Website: thukhoadaihoc.vn$<br>c) đúng<br>Khi lên cao áp suất khí quyển giảm.<br>d) sai<br>$\\Delta T\\left(K\\right)=\\Delta t\\left({}^0C\\right)=25−20$","difficultySource":"ai"}}]},{"id":669971,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Tàu vũ trụ New Horizons, nổi tiếng với chuyến bay ngang qua Sao Diêm Vương, sử dụng một pin đồng vị phóng xạ (RTG) để cung cấp năng lượng. Biết mỗi phân rã alpha của một hạt nhân   ${}_{94}^{238}Pu$ giải phóng một năng lượng nhiệt 5,593MeV. Hiệu suất chuyển đổi từ nhiệt năng do phân rã thành điện năng của RTG là 5,6%. Khối lượng ban đầu của  238Pu trong RTG là 7,8 kg. Chu kỳ bán rã của  238Pu là 87,7 năm. Biết một năm có 3,1536.10<sup>7</sup> giây; khối lượng mol của  238Pu là 238 g/mol.","difficulty":"kho","statements":[{"text":"Sự phóng xạ của   ${}_{94}^{238}Pu$ có thể điều khiển được bằng các thiết bị ở trên tàu.","answer":false},{"text":"Trong quá trình phân rã alpha của   ${}_{94}^{238}Pu$ , hạt nhân con được tạo thành là  ${}_{92}^{234}U$ .","answer":true},{"text":"Độ phóng xạ ban đầu của 7,8 kg  ${}_{94}^{238}Pu$ trong RTG là 4,9.10<sup>15</sup> Bq.","answer":true},{"text":"Công suất điện ban đầu do RTG của tàu New Horizons cung cấp là 327 W.","answer":false}],"explanation":"a) sai<br>Phóng xạ không điều khiển được<br>b) đúng<br>${}_{94}^{238}Pu\\rightarrow {}_2^4\\alpha+{}_{92}^{234}U$<br>c) đúng<br>$n=\\frac{m}{M}=\\frac{7,8.10^3}{238}\\approx 32,77311mol$<br>$N=nN_A=32,77311.6,02.10^{23}\\approx 1,973.10^{25}$<br>$\\begin{aligned}\\end{aligned}H=\\lambda N=\\frac{ln2}{T}.N=\\frac{ln2}{87,7.3,1536.10^7}.1,973.10^{25}\\approx 4,94.10^{15}\\left(Bq\\right) Website: thukhoadaihoc.vn$<br>d) sai<br>$P=\\frac{5,6}{100}H\\Delta E=\\frac{5,6}{100}.4,94.10^{15}.5,593.1,6.10^{−13}\\approx 248W$","difficultySource":"ai"},"ex":[{"exam":395,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Tàu vũ trụ New Horizons, nổi tiếng với chuyến bay ngang qua Sao Diêm Vương, sử dụng một pin đồng vị phóng xạ (RTG) để cung cấp năng lượng. Biết mỗi phân rã alpha của một hạt nhân   ${}_{94}^{238}Pu$ giải phóng một năng lượng nhiệt 5,593MeV. Hiệu suất chuyển đổi từ nhiệt năng do phân rã thành điện năng của RTG là 5,6%. Khối lượng ban đầu của  238Pu trong RTG là 7,8 kg. Chu kỳ bán rã của  238Pu là 87,7 năm. Biết một năm có 3,1536.10<sup>7</sup> giây; khối lượng mol của  238Pu là 238 g/mol.","difficulty":"kho","statements":[{"text":"Sự phóng xạ của   ${}_{94}^{238}Pu$ có thể điều khiển được bằng các thiết bị ở trên tàu.","answer":false},{"text":"Trong quá trình phân rã alpha của   ${}_{94}^{238}Pu$ , hạt nhân con được tạo thành là  ${}_{92}^{234}U$ .","answer":true},{"text":"Độ phóng xạ ban đầu của 7,8 kg  ${}_{94}^{238}Pu$ trong RTG là 4,9.10<sup>15</sup> Bq.","answer":true},{"text":"Công suất điện ban đầu do RTG của tàu New Horizons cung cấp là 327 W.","answer":false}],"explanation":"a) sai<br>Phóng xạ không điều khiển được<br>b) đúng<br>${}_{94}^{238}Pu\\rightarrow {}_2^4\\alpha+{}_{92}^{234}U$<br>c) đúng<br>$n=\\frac{m}{M}=\\frac{7,8.10^3}{238}\\approx 32,77311mol$<br>$N=nN_A=32,77311.6,02.10^{23}\\approx 1,973.10^{25}$<br>$\\begin{aligned}\\end{aligned}H=\\lambda N=\\frac{ln2}{T}.N=\\frac{ln2}{87,7.3,1536.10^7}.1,973.10^{25}\\approx 4,94.10^{15}\\left(Bq\\right) Website: thukhoadaihoc.vn$<br>d) sai<br>$P=\\frac{5,6}{100}H\\Delta E=\\frac{5,6}{100}.4,94.10^{15}.5,593.1,6.10^{−13}\\approx 248W$","difficultySource":"ai"}}]},{"id":669974,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt độ và cân bằng nhiệt","answer":"67,4","question":"Một cốc cách nhiệt chứa 140 g cà phê đã pha ở nhiệt độ 800C. Bỏ vào 12 g nước đá ở 00C vào cốc để làm mát cà phê. Biết nhiệt nóng chảy của nước đá là 3,34.10<sup>5</sup> J/kg. Coi nhiệt dung riêng của nước cà phê và nước thường đều là c = 4200 (J/kg.K) . Bỏ qua sự trao đổi nhiệt với môi trường. Khi cân bằng nhiệt thì nhiệt độ của nước cà phê bằng x0C. Giá trị của x là bao nhiêu (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$m_{cp}c\\left(t_{cp}−t\\right)=m_n\\lambda +m_n\\left(t_n−t\\right)$<br>$\\Rightarrow 140.4200.\\left(80−t\\right)=12.3,34.10^5+12.4200.t\\Rightarrow t\\approx 67,4^0C$","difficultySource":"ai"},"ex":[{"exam":395,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt độ và cân bằng nhiệt","answer":"67,4","question":"Một cốc cách nhiệt chứa 140 g cà phê đã pha ở nhiệt độ 800C. Bỏ vào 12 g nước đá ở 00C vào cốc để làm mát cà phê. Biết nhiệt nóng chảy của nước đá là 3,34.10<sup>5</sup> J/kg. Coi nhiệt dung riêng của nước cà phê và nước thường đều là c = 4200 (J/kg.K) . Bỏ qua sự trao đổi nhiệt với môi trường. Khi cân bằng nhiệt thì nhiệt độ của nước cà phê bằng x0C. Giá trị của x là bao nhiêu (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$m_{cp}c\\left(t_{cp}−t\\right)=m_n\\lambda +m_n\\left(t_n−t\\right)$<br>$\\Rightarrow 140.4200.\\left(80−t\\right)=12.3,34.10^5+12.4200.t\\Rightarrow t\\approx 67,4^0C$","difficultySource":"ai"}}]},{"id":669981,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Suất điện động do thanh dẫn chuyển động","answer":3,"options":["1,4 T/s.","2,8 T/s.","0,7 T/s.","0,014 T/s."],"question":"Một vòng dây đồng có đường kính 20 cm, tiết diện 0,5 cm2 đặt vào trong từ trường đều cảm ứng từ vuông góc với mặt phẳng vòng dây. Biết đồng có điện trở suất là 1,75.10<sup>−8</sup> Ωm dòng điện cảm ứng xuất hiện trong vòng dây là 2 A thì tốc độ biến thiên của cảm ứng từ qua vòng dây là","difficulty":"trung-binh","explanation":"$ℓ=2\\pi r=\\pi .0,2\\left(m\\right)$<br>$R=\\delta .\\frac{ℓ}{S}=1,75.10^{−8}.\\frac{0,2\\pi }{0,5.10^{−4}}=2,2.10^{−4}\\Omega$<br>$\\left|i_{cu}\\right|=\\frac{\\left|e_{cu}\\right|}{R}=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|.\\frac{1}{R}=2\\Rightarrow \\frac{\\left|\\Delta B\\right|.S}{\\Delta t}=2R;\\left(S=\\pi r^2\\right)$<br>$\\Rightarrow \\frac{\\Delta B}{\\Delta t}=0,014\\left(T/s\\right)$","difficultySource":"ai"},"ex":[{"exam":396,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Suất điện động do thanh dẫn chuyển động","answer":3,"options":["1,4 T/s.","2,8 T/s.","0,7 T/s.","0,014 T/s."],"question":"Một vòng dây đồng có đường kính 20 cm, tiết diện 0,5 cm2 đặt vào trong từ trường đều cảm ứng từ vuông góc với mặt phẳng vòng dây. Biết đồng có điện trở suất là 1,75.10<sup>−8</sup> Ωm dòng điện cảm ứng xuất hiện trong vòng dây là 2 A thì tốc độ biến thiên của cảm ứng từ qua vòng dây là","difficulty":"trung-binh","explanation":"$ℓ=2\\pi r=\\pi .0,2\\left(m\\right)$<br>$R=\\delta .\\frac{ℓ}{S}=1,75.10^{−8}.\\frac{0,2\\pi }{0,5.10^{−4}}=2,2.10^{−4}\\Omega$<br>$\\left|i_{cu}\\right|=\\frac{\\left|e_{cu}\\right|}{R}=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|.\\frac{1}{R}=2\\Rightarrow \\frac{\\left|\\Delta B\\right|.S}{\\Delta t}=2R;\\left(S=\\pi r^2\\right)$<br>$\\Rightarrow \\frac{\\Delta B}{\\Delta t}=0,014\\left(T/s\\right)$","difficultySource":"ai"}}]},{"id":669995,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","answer":3,"options":["0,36.10<sup>−12</sup> m.","0,36.10<sup>−15</sup> m.","3,6.10<sup>−12</sup> m.","3,6.10<sup>−15</sup> m."],"question":"Coi hạt nhân nguyên tử như một quả cầu có bán kính  $R=1,2.10^{−15}A^{\\frac{1}{3}}$ (m) với A là số khối. Bán kính của hạt nhân 1 ${}_{13}^{27}Al$   có giá trị bằng","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Bán kính hạt nhân được tính theo công thức $R=1,2.10^{-15}A^{\\frac{1}{3}}$ (m), với $A$ là số khối.</p><p class=\"text-base leading-relaxed my-2\">Với hạt nhân ${}_{13}^{27}Al$ có $A=27$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow R=1,2.10^{-15}.27^{\\frac{1}{3}}=1,2.10^{-15}.3=3,6.10^{-15}\\text{ m}$</p><p class=\"text-base leading-relaxed my-2\">Vậy bán kính hạt nhân ${}_{13}^{27}Al$ là $3,6.10^{-15}$ m, đáp án D.</p>","difficultySource":"ai"},"ex":[{"exam":396,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","answer":3,"options":["0,36.10<sup>−12</sup> m.","0,36.10<sup>−15</sup> m.","3,6.10<sup>−12</sup> m.","3,6.10<sup>−15</sup> m."],"question":"Coi hạt nhân nguyên tử như một quả cầu có bán kính  $R=1,2.10^{−15}A^{\\frac{1}{3}}$ (m) với A là số khối. Bán kính của hạt nhân 1 ${}_{13}^{27}Al$   có giá trị bằng","difficulty":"de","explanation":"$R=1,2.10^{−15}27^{\\frac{1}{3}}=3,6.10^{−15}$","difficultySource":"ai"}}]},{"id":669997,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Một học sinh làm thí nghiệm kiểm tra định luật Charles đối với khối khí lí tưởng chứa trong xi lanh có pit tông đậy kín và di chuyển được như hình bên. Với các dụng cụ gồm:<br>+ Áp kế (1) có mức 0 ứng với áp suất khí quyển, đơn vị đo của áp kế là Bar (1 Bar = 105 Pa).<br>+ Xi lanh (2); Pit tông (3) gắn với tay quay (4); Hộp chứa nước nóng (5): Cảm biến nhiệt độ (6).<br>Bạn học sinh tiến hành thí nghiệm theo các bước sau:<br>+ Đọc giá trị phần thể tích chứa khí của xi lanh ban đầu (V0 = 70 ml).<br>+ Đọc số chỉ của cảm biến nhiệt độ đo nhiệt độ khí trong xi lanh đầu (t0 = 260C).<br>+ Đổ nước nóng vào hộp chứa cho ngập hoàn toàn xi lanh. Quay tay quay để pít tông dịch chuyển từ từ sao cho số chỉ của áp kế không đổi (p0 = 105 Pa). Đọc giá trị của phần thể tích chứa khí và nhiệt độ sau mỗi phút. Bạn học sinh thu được bảng giá trị ở hình 1 sau:<br>Hình 2<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046660097-hinh-12.jpg\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046660271-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Định luật Charles được phát biểu như sau: “Khi áp suất của một khối lượng khí xác định giữ không đổi thì thể tích của khí tỉ lệ thuận với nhiệt độ tuyệt đối của nó”.","answer":true},{"text":"Lượng khí lí tưởng chứa trong xi lanh có số mol xấp xỉ bằng 2,8 mol.","answer":false},{"text":"Tỉ số  $\\frac{V}{T}$ luôn không đổi và xấp xỉ bằng 0,235.10<sup>−6</sup>  $\\left(\\frac{m^3}{K}\\right)$","answer":true},{"text":"Đồ thị biểu diễn mối liên hệ giữa nhiệt độ tuyệt đối và thể tích của khối khí trên như Hình 2","answer":true}],"explanation":"a) đúng<br>Định luật Charles được phát biểu như sau: “Khi áp suất của một khối lượng khí xác định giữ không đổi thì thể tích của khí tỉ lệ thuận với nhiệt độ tuyệt đối của nó”.<br>b) sai<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046660444-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>c) đúng","difficultySource":"ai"},"ex":[{"exam":396,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Một học sinh làm thí nghiệm kiểm tra định luật Charles đối với khối khí lí tưởng chứa trong xi lanh có pit tông đậy kín và di chuyển được như hình bên. Với các dụng cụ gồm:<br>+ Áp kế (1) có mức 0 ứng với áp suất khí quyển, đơn vị đo của áp kế là Bar (1 Bar = 105 Pa).<br>+ Xi lanh (2); Pit tông (3) gắn với tay quay (4); Hộp chứa nước nóng (5): Cảm biến nhiệt độ (6).<br>Bạn học sinh tiến hành thí nghiệm theo các bước sau:<br>+ Đọc giá trị phần thể tích chứa khí của xi lanh ban đầu (V0 = 70 ml).<br>+ Đọc số chỉ của cảm biến nhiệt độ đo nhiệt độ khí trong xi lanh đầu (t0 = 260C).<br>+ Đổ nước nóng vào hộp chứa cho ngập hoàn toàn xi lanh. Quay tay quay để pít tông dịch chuyển từ từ sao cho số chỉ của áp kế không đổi (p0 = 105 Pa). Đọc giá trị của phần thể tích chứa khí và nhiệt độ sau mỗi phút. Bạn học sinh thu được bảng giá trị ở hình 1 sau:<br>Hình 2<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046660097-hinh-12.jpg\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046660271-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Định luật Charles được phát biểu như sau: “Khi áp suất của một khối lượng khí xác định giữ không đổi thì thể tích của khí tỉ lệ thuận với nhiệt độ tuyệt đối của nó”.","answer":true},{"text":"Lượng khí lí tưởng chứa trong xi lanh có số mol xấp xỉ bằng 2,8 mol.","answer":false},{"text":"Tỉ số  $\\frac{V}{T}$ luôn không đổi và xấp xỉ bằng 0,235.10<sup>−6</sup>  $\\left(\\frac{m^3}{K}\\right)$","answer":true},{"text":"Đồ thị biểu diễn mối liên hệ giữa nhiệt độ tuyệt đối và thể tích của khối khí trên như Hình 2","answer":true}],"explanation":"a) đúng<br>Định luật Charles được phát biểu như sau: “Khi áp suất của một khối lượng khí xác định giữ không đổi thì thể tích của khí tỉ lệ thuận với nhiệt độ tuyệt đối của nó”.<br>b) sai<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046660444-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>c) đúng","difficultySource":"ai"}}]},{"id":670003,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nguyên tắc tạo ra dòng điện xoay chiều","answer":"7,1","question":"Một khung dây dẫn phẳng hình chữ nhật có kích thước 20 cm × 30 cm gồm 200 vòng dây được quấn từ một sợi dây đồng có tiết diện S0 = 1 mm2 và có điện trở suất ρ =1,7.10<sup>−8</sup> Ωm. Cho khung quay đều với tốc độ 200 vòng/phút quanh một trục vuông góc với các đường sức từ của một từ trường đều có cảm ứng từ B = 0,4 T. Nối hai đầu khung dây với điện trở R = 6,6 Ω thành mạch kín thì dòng điện chạy qua điện trở có giá trị hiệu dụng là bao nhiêu Ampe (kết quả làm tròn đến chữ số hàng phần mười)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046661627-hinh-20.png\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"$E_0=\\omega NBS$<br>$\\left\\{\\begin{aligned}\\omega =\\frac{200.2\\pi }{60}=\\frac{200\\pi }{3}\\left(rad/s\\right) <br>S=0,2.0,3=0,06m^2 <br>B=0,4J;N=200(vong)\\end{aligned}\\right.\\Rightarrow E_0=32\\pi \\left(V\\right)$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046661793-hinh-21.png\" alt=\"Hình 21\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$I=\\frac{E}{R+r}=\\frac{\\frac{32\\pi }{\\sqrt2}}{6,6+3,4}=7,1\\left(A\\right)$","difficultySource":"ai"},"ex":[{"exam":396,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Nguyên tắc tạo ra dòng điện xoay chiều","answer":"7,1","question":"Một khung dây dẫn phẳng hình chữ nhật có kích thước 20 cm × 30 cm gồm 200 vòng dây được quấn từ một sợi dây đồng có tiết diện S0 = 1 mm2 và có điện trở suất ρ =1,7.10<sup>−8</sup> Ωm. Cho khung quay đều với tốc độ 200 vòng/phút quanh một trục vuông góc với các đường sức từ của một từ trường đều có cảm ứng từ B = 0,4 T. Nối hai đầu khung dây với điện trở R = 6,6 Ω thành mạch kín thì dòng điện chạy qua điện trở có giá trị hiệu dụng là bao nhiêu Ampe (kết quả làm tròn đến chữ số hàng phần mười)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046661627-hinh-20.png\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"$E_0=\\omega NBS$<br>$\\left\\{\\begin{aligned}\\omega =\\frac{200.2\\pi }{60}=\\frac{200\\pi }{3}\\left(rad/s\\right) <br>S=0,2.0,3=0,06m^2 <br>B=0,4J;N=200(vong)\\end{aligned}\\right.\\Rightarrow E_0=32\\pi \\left(V\\right)$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046661793-hinh-21.png\" alt=\"Hình 21\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$I=\\frac{E}{R+r}=\\frac{\\frac{32\\pi }{\\sqrt2}}{6,6+3,4}=7,1\\left(A\\right)$","difficultySource":"ai"}}]},{"id":670205,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":0,"options":["3,01.10<sup>23</sup>.","6,02.10<sup>23</sup>.","1,505.10<sup>23</sup>.","12,04.10<sup>23</sup>."],"question":"Số phân tử hidro chứa trong 1 g khí hidro là, biết 1mol khí có 6,02.10<sup>23</sup> phân tử hidro.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối lượng mol của khí hidro: $M_{H_2} = 2 \\text{ g/mol}$.</p><p class=\"text-base leading-relaxed my-2\">Số mol khí hidro trong 1 g: $n = \\dfrac{m}{M} = \\dfrac{1}{2} = 0{,}5 \\text{ mol}$.</p><p class=\"text-base leading-relaxed my-2\">Số phân tử hidro: $N = n \\cdot N_A$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N = 0{,}5 \\cdot 6{,}02\\cdot 10^{23} = 3{,}01\\cdot 10^{23} \\text{ phân tử}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: số phân tử hidro trong 1 g khí hidro là $3{,}01\\cdot 10^{23}$ phân tử, đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":397,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":0,"options":["3,01.10<sup>23</sup>.","6,02.10<sup>23</sup>.","1,505.10<sup>23</sup>.","12,04.10<sup>23</sup>."],"question":"Số phân tử hidro chứa trong 1 g khí hidro là, biết 1mol khí có 6,02.10<sup>23</sup> phân tử hidro.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối lượng mol của khí hidro: $M_{H_2} = 2 \\text{ g/mol}$.</p><p class=\"text-base leading-relaxed my-2\">Số mol khí hidro trong 1 g: $n = \\dfrac{m}{M} = \\dfrac{1}{2} = 0{,}5 \\text{ mol}$.</p><p class=\"text-base leading-relaxed my-2\">Số phân tử hidro: $N = n \\cdot N_A$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N = 0{,}5 \\cdot 6{,}02\\cdot 10^{23} = 3{,}01\\cdot 10^{23} \\text{ phân tử}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: số phân tử hidro trong 1 g khí hidro là $3{,}01\\cdot 10^{23}$ phân tử, đáp án A.</p>","difficultySource":"ai"}}]},{"id":670227,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"2,3","question":"Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 1kg nước ở 1000C là bao nhiêu MJ, 1MJ = 106J? Cho biết nhiệt hoá hơi riêng của nước là 2,3.10<sup>6</sup> J/kg.","difficulty":"de","explanation":"Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 1kg nước ở 1000C là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}Q=mL=1.2,3.10^6=2,3.10^6\\left(J\\right)=2,3\\left(MJ\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":397,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"2,3","question":"Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 1kg nước ở 1000C là bao nhiêu MJ, 1MJ = 106J? Cho biết nhiệt hoá hơi riêng của nước là 2,3.10<sup>6</sup> J/kg.","difficulty":"de","explanation":"Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 1kg nước ở 1000C là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}Q=mL=1.2,3.10^6=2,3.10^6\\left(J\\right)=2,3\\left(MJ\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":670446,"nq":{"form":"bai_tap","type":"short_answer","topic":"Áp suất và động năng phân tử khí","answer":"1,84","question":"Ở điều kiện tiêu chuẩn (áp suất là 1atm), khối lượng riêng của khí hydrogen là 9.10<sup>−2</sup> kg/m3. Tốc độ căn quân phương của phân tử khí hydrogen là X.10<sup>3</sup> m/s. Tìm X. (Kết quả làm tròn đến 2 chữ số thập phân).","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng công thức tốc độ căn quân phương của phân tử khí lí tưởng, liên hệ với áp suất và khối lượng riêng: $p=\\dfrac{1}{3}\\rho v_{rms}^2$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra: $v_{rms}=\\sqrt{\\dfrac{3p}{\\rho}}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $p=1\\,\\text{atm}=1{,}01325\\cdot 10^{5}\\,\\text{Pa}$, $\\rho=9\\cdot 10^{-2}\\,\\text{kg/m}^3$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $v_{rms}=\\sqrt{\\dfrac{3\\cdot 1{,}01325\\cdot 10^{5}}{9\\cdot 10^{-2}}}=\\sqrt{3{,}3775\\cdot 10^{6}}\\approx 1{,}8378\\cdot 10^{3}\\,\\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy $X\\approx 1{,}84$.</p>","difficultySource":"ai"},"ex":[{"exam":398,"idx":21,"el":{"form":"bai_tap","type":"short_answer","topic":"Áp suất và động năng phân tử khí","answer":"1,84","question":"Ở điều kiện tiêu chuẩn (áp suất là 1atm), khối lượng riêng của khí hydrogen là 9.10<sup>−2</sup> kg/m3. Tốc độ căn quân phương của phân tử khí hydrogen là X.10<sup>3</sup> m/s. Tìm X. (Kết quả làm tròn đến 2 chữ số thập phân).","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng công thức tốc độ căn quân phương của phân tử khí lí tưởng, liên hệ với áp suất và khối lượng riêng: $p=\\dfrac{1}{3}\\rho v_{rms}^2$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra: $v_{rms}=\\sqrt{\\dfrac{3p}{\\rho}}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $p=1\\,\\text{atm}=1{,}01325\\cdot 10^{5}\\,\\text{Pa}$, $\\rho=9\\cdot 10^{-2}\\,\\text{kg/m}^3$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $v_{rms}=\\sqrt{\\dfrac{3\\cdot 1{,}01325\\cdot 10^{5}}{9\\cdot 10^{-2}}}=\\sqrt{3{,}3775\\cdot 10^{6}}\\approx 1{,}8378\\cdot 10^{3}\\,\\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy $X\\approx 1{,}84$.</p>","difficultySource":"ai"}}]},{"id":670753,"nq":{"form":"bai_tap","type":"short_answer","topic":"Điện từ trường và sóng điện từ","answer":"2000","question":"Một sóng điện từ truyền trong chân không có tần số f = 150kHz, tốc độ của ánh sáng trong chân không bằng 3.10<sup>8</sup> m/s. Bước sóng của sóng điện từ đó là bao nhiêu mét?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Sóng điện từ truyền trong chân không có bước sóng được tính theo công thức $\\lambda = \\dfrac{c}{f}$, trong đó $c$ là tốc độ ánh sáng trong chân không và $f$ là tần số của sóng.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $f = 150\\ \\text{kHz} = 150 \\cdot 10^3\\ \\text{Hz}$, $c = 3 \\cdot 10^8\\ \\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $\\lambda = \\dfrac{3 \\cdot 10^8}{150 \\cdot 10^3} = 2000\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: bước sóng của sóng điện từ là $\\lambda = 2000\\ \\text{m}$.</p>","difficultySource":"ai"},"ex":[{"exam":401,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Điện từ trường và sóng điện từ","answer":"2000","question":"Một sóng điện từ truyền trong chân không có tần số f = 150kHz, tốc độ của ánh sáng trong chân không bằng 3.10<sup>8</sup> m/s. Bước sóng của sóng điện từ đó là bao nhiêu mét?","difficulty":"de","explanation":"$\\lambda =\\frac{c}{f}=\\frac{3.10^8}{150.10^3}=2000m$","difficultySource":"ai"}}]},{"id":670754,"nq":{"form":"bai_tap","type":"short_answer","topic":"Lực từ. Cảm ứng từ","answer":"7,1","question":"Một electron đang chuyển động với tốc độ v = 1,5.10<sup>6</sup> m/s trong một từ trường đều theo phương vuông góc với cảm ứng từ có độ lớn B = 0,12mT. Biết lực từ tác dụng lên electron có độ lớn |e|vB,  luôn vuông góc với v; độ lớn điện tích và khối lượng của electron là e = 1,6.10<sup>−19</sup>C và m = 9,1.10<sup>−31</sup> kg. Do tác dụng của lực từ, electron chuyển động theo một đường tròn. Bán kính quỹ đạo bao nhiêu centimet (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Lực từ  $\\vec{F}_t$  đóng vai trò là lực hướng tâm nên:<br>$F_t=ma_{ht}\\Rightarrow evB=m.\\frac{v^2}{R}$<br>$\\Rightarrow R=\\frac{mv}{eB}=\\frac{9,1.10^{−31}.1,5.10^6}{1,6.10^{−19}.0,12.10^{−3}}\\approx 0,071m=7,1cm$","difficultySource":"ai"},"ex":[{"exam":401,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Lực từ. Cảm ứng từ","answer":"7,1","question":"Một electron đang chuyển động với tốc độ v = 1,5.10<sup>6</sup> m/s trong một từ trường đều theo phương vuông góc với cảm ứng từ có độ lớn B = 0,12mT. Biết lực từ tác dụng lên electron có độ lớn |e|vB,  luôn vuông góc với v; độ lớn điện tích và khối lượng của electron là e = 1,6.10<sup>−19</sup>C và m = 9,1.10<sup>−31</sup> kg. Do tác dụng của lực từ, electron chuyển động theo một đường tròn. Bán kính quỹ đạo bao nhiêu centimet (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Lực từ  $\\vec{F}_t$  đóng vai trò là lực hướng tâm nên:<br>$F_t=ma_{ht}\\Rightarrow evB=m.\\frac{v^2}{R}$<br>$\\Rightarrow R=\\frac{mv}{eB}=\\frac{9,1.10^{−31}.1,5.10^6}{1,6.10^{−19}.0,12.10^{−3}}\\approx 0,071m=7,1cm$","difficultySource":"ai"}}]},{"id":670980,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["1,1.10<sup>4</sup> J.","9,9.10<sup>3</sup> J.","9,9.10<sup>6</sup> J.","1,1.10<sup>7</sup> J."],"question":"Biết nhiệt nóng chảy riêng của nước đá ở 00C là 3,3.10<sup>5</sup> J/kg. Nhiệt lượng cần cung cấp để 30 g nước đá tan chảy hoàn toàn ở 00C bằng","difficulty":"de","explanation":"$Q=m\\lambda =\\frac{30}{1000}.3,3.10^5=9900\\left(J\\right)=9,9.10^3\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":402,"idx":0,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["1,1.10<sup>4</sup> J.","9,9.10<sup>3</sup> J.","9,9.10<sup>6</sup> J.","1,1.10<sup>7</sup> J."],"question":"Biết nhiệt nóng chảy riêng của nước đá ở 00C là 3,3.10<sup>5</sup> J/kg. Nhiệt lượng cần cung cấp để 30 g nước đá tan chảy hoàn toàn ở 00C bằng","difficulty":"de","explanation":"$Q=m\\lambda =\\frac{30}{1000}.3,3.10^5=9900\\left(J\\right)=9,9.10^3\\left(J\\right)$","difficultySource":"ai"}}]},{"id":670989,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Vận dụng phương trình trạng thái","answer":0,"options":["7,6 m.","6,6 m.","5,2 m.","3,8 m."],"question":"Bóng thám không được sử dụng để thu thập thông tin về môi trường không khí và thời tiết. Bóng thường được bơm khí hiếm nhẹ hơn không khí, nhờ đó có thể bay lên các tầng không khí khác nhau để thu thập thông tin về nhiệt độ, độ ẩm, áp suất, tốc độ gió. Người ta muốn chế tạo một bóng thám không có thể tăng bán kính lên tới 10 m khi bay ở tầng khí quyển có áp suất 0,3.105 Pa và nhiệt độ 200 K. Biết bóng được bơm ở áp suất 1,02.10<sup>5</sup> Pa và nhiệt độ 300 K. Coi rằng quả bóng luôn có dạng hình cầu, bán kính của bóng khi vừa bơm xong bằng","difficulty":"kho","explanation":"Lượng khí ở trong quả bóng là không đổi  $\\Rightarrow \\frac{p_1V_1}{T_2}=\\frac{p_2V_2}{T_2}\\Rightarrow \\frac{1,02.10^5.R{}_1^3{}}{300}=\\frac{0,3.10^5.R{}_2^3{}10^3}{200}\\left(V=\\frac{4}{3}\\pi R^3\\right)$<br>(Có thể tăng bán kính lên tới 10m  $\\Rightarrow R_2^3=10^3$ )<br>$\\Rightarrow R_1=7,31\\left(m\\right)$<br>(R1 là bán kính lúc đầu là lượng khí được bơm vào. Càng lên cao áp suất bên ngoài khí quyển giảm lúc này bóng dãn nở ra để cho áp suất bên trong và áp suất bên ngoài cân bằng với nhau. Buộc thể tích nở ra)","difficultySource":"ai"},"ex":[{"exam":402,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Vận dụng phương trình trạng thái","answer":0,"options":["7,6 m.","6,6 m.","5,2 m.","3,8 m."],"question":"Bóng thám không được sử dụng để thu thập thông tin về môi trường không khí và thời tiết. Bóng thường được bơm khí hiếm nhẹ hơn không khí, nhờ đó có thể bay lên các tầng không khí khác nhau để thu thập thông tin về nhiệt độ, độ ẩm, áp suất, tốc độ gió. Người ta muốn chế tạo một bóng thám không có thể tăng bán kính lên tới 10 m khi bay ở tầng khí quyển có áp suất 0,3.105 Pa và nhiệt độ 200 K. Biết bóng được bơm ở áp suất 1,02.10<sup>5</sup> Pa và nhiệt độ 300 K. Coi rằng quả bóng luôn có dạng hình cầu, bán kính của bóng khi vừa bơm xong bằng","difficulty":"kho","explanation":"Lượng khí ở trong quả bóng là không đổi  $\\Rightarrow \\frac{p_1V_1}{T_2}=\\frac{p_2V_2}{T_2}\\Rightarrow \\frac{1,02.10^5.R{}_1^3{}}{300}=\\frac{0,3.10^5.R{}_2^3{}10^3}{200}\\left(V=\\frac{4}{3}\\pi R^3\\right)$<br>(Có thể tăng bán kính lên tới 10m  $\\Rightarrow R_2^3=10^3$ )<br>$\\Rightarrow R_1=7,31\\left(m\\right)$<br>(R1 là bán kính lúc đầu là lượng khí được bơm vào. Càng lên cao áp suất bên ngoài khí quyển giảm lúc này bóng dãn nở ra để cho áp suất bên trong và áp suất bên ngoài cân bằng với nhau. Buộc thể tích nở ra)","difficultySource":"ai"}}]},{"id":671000,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một nhóm học sinh làm thí nghiệm để xác định nhiệt hóa hơi của nước như sau: nối oát kế với một ấm siêu tốc chứa nước, đặt ấm lên một cân điện tử, cấp điện cho ấm siêu tốc; khi nước đã sôi nhóm học sinh mở nắp ấm để hơi nước thoát ra, và ghi lại số chỉ của oát kế, của cân theo thời gian thì thu được bảng số liệu sau:<br>Thời gian (phút)\t0\t1\t2<br>Số chỉ oát kế (W)\t1003\t997\t1001<br>Số chỉ cân (gam)\t2500\t2318\t2138","difficulty":"kho","statements":[{"text":"Công suất trung bình của ấm điện bằng 1000 W.","answer":true},{"text":"Lượng nước bị bay hơi trong 3 phút khảo sát bằng 540 g.","answer":true},{"text":"Trong khoảng thời gian nước sôi, nhiệt độ của nước liên tục tăng.","answer":false},{"text":"Coi rằng mất mát nhiệt ra môi trường không đáng kể, từ bảng số liệu trên nhóm học sinh tính toán được nhiệt hóa hơi riêng của nước trong thí nghiệm bằng 3,3.10<sup>5</sup> J/kg (làm tròn kết quả đến chữ số hàng phần mười).","answer":false}],"explanation":"a) đúng<br>$\\overline{P}=\\frac{1003+997+1001+999}{4}=1000W$<br>b) đúng<br>Lượng nước ban đầu (0 phút) là 2500 gam<br>Sau 3 phút còn lại 1960 gam<br>$\\Rightarrow$  Lượng nước bị bay hơi trong 3 phút:  $\\Delta m=2500−1960=540gam$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) sai<br>Trong khoảng thời gian nước sôi, nhiệt độ của nước sẽ không đổi<br>d) sai<br>Sau 3 phút:  $\\frac{Q}{m}=\\frac{1000.180}{540:1000}=3,3.10^5\\left(J/kg\\right)$","difficultySource":"ai"},"ex":[{"exam":402,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một nhóm học sinh làm thí nghiệm để xác định nhiệt hóa hơi của nước như sau: nối oát kế với một ấm siêu tốc chứa nước, đặt ấm lên một cân điện tử, cấp điện cho ấm siêu tốc; khi nước đã sôi nhóm học sinh mở nắp ấm để hơi nước thoát ra, và ghi lại số chỉ của oát kế, của cân theo thời gian thì thu được bảng số liệu sau:<br>Thời gian (phút)\t0\t1\t2<br>Số chỉ oát kế (W)\t1003\t997\t1001<br>Số chỉ cân (gam)\t2500\t2318\t2138","difficulty":"kho","statements":[{"text":"Công suất trung bình của ấm điện bằng 1000 W.","answer":true},{"text":"Lượng nước bị bay hơi trong 3 phút khảo sát bằng 540 g.","answer":true},{"text":"Trong khoảng thời gian nước sôi, nhiệt độ của nước liên tục tăng.","answer":false},{"text":"Coi rằng mất mát nhiệt ra môi trường không đáng kể, từ bảng số liệu trên nhóm học sinh tính toán được nhiệt hóa hơi riêng của nước trong thí nghiệm bằng 3,3.10<sup>5</sup> J/kg (làm tròn kết quả đến chữ số hàng phần mười).","answer":false}],"explanation":"a) đúng<br>$\\overline{P}=\\frac{1003+997+1001+999}{4}=1000W$<br>b) đúng<br>Lượng nước ban đầu (0 phút) là 2500 gam<br>Sau 3 phút còn lại 1960 gam<br>$\\Rightarrow$  Lượng nước bị bay hơi trong 3 phút:  $\\Delta m=2500−1960=540gam$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) sai<br>Trong khoảng thời gian nước sôi, nhiệt độ của nước sẽ không đổi<br>d) sai<br>Sau 3 phút:  $\\frac{Q}{m}=\\frac{1000.180}{540:1000}=3,3.10^5\\left(J/kg\\right)$","difficultySource":"ai"}}]},{"id":671001,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"6,7","question":"Cho nhiệt hóa hơi riêng của nước bằng 2,26.10<sup>6</sup> J/kg, nhiệt dung riêng của nước bằng 4200 J/(kg.K). Nhiệt lượng tỏa ra khi 1 kg hơi nước ngưng tụ đủ để đun sôi bao nhiêu kilôgam nước từ 200C (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"de","explanation":"$Q_{toa}=2,26.10^6\\left(J\\right)=m.c.\\Delta t=m.4200.80$  (đề thiếu nhiệt độ  $t_{soi}=100^0C$ )<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow m=6,7\\left(kg\\right)$","difficultySource":"ai"},"ex":[{"exam":402,"idx":21,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"6,7","question":"Cho nhiệt hóa hơi riêng của nước bằng 2,26.10<sup>6</sup> J/kg, nhiệt dung riêng của nước bằng 4200 J/(kg.K). Nhiệt lượng tỏa ra khi 1 kg hơi nước ngưng tụ đủ để đun sôi bao nhiêu kilôgam nước từ 200C (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"de","explanation":"$Q_{toa}=2,26.10^6\\left(J\\right)=m.c.\\Delta t=m.4200.80$  (đề thiếu nhiệt độ  $t_{soi}=100^0C$ )<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow m=6,7\\left(kg\\right)$","difficultySource":"ai"}}]},{"id":671444,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"4","question":"Khi truyền nhiệt lượng 6.10<sup>6</sup> J cho khí trong một xi-lanh hình trụ thì khí nó nở đây pít-tông lên làm thể tích của khí tăng thêm 0,250 m3. Áp suất của khí trong xi-lanh là 8.10<sup>6</sup> N/m2 và không đổi. Độ biến thiên nội năng của khí có độ lớn bằng bao nhiêu MJ?","difficulty":"trung-binh","explanation":"$A=−p\\Delta V=−8.10^6.0,25=−2.10^6J$<br>$\\Delta U=Q+A=6.10^6−2.10^6=4.10^6J=4\\left(MJ\\right)$","difficultySource":"ai"},"ex":[{"exam":403,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"4","question":"Khi truyền nhiệt lượng 6.10<sup>6</sup> J cho khí trong một xi-lanh hình trụ thì khí nó nở đây pít-tông lên làm thể tích của khí tăng thêm 0,250 m3. Áp suất của khí trong xi-lanh là 8.10<sup>6</sup> N/m2 và không đổi. Độ biến thiên nội năng của khí có độ lớn bằng bao nhiêu MJ?","difficulty":"trung-binh","explanation":"$A=−p\\Delta V=−8.10^6.0,25=−2.10^6J$<br>$\\Delta U=Q+A=6.10^6−2.10^6=4.10^6J=4\\left(MJ\\right)$","difficultySource":"ai"}}]},{"id":671619,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"0,1","question":"Một mol khí lí tưởng ở điều kiện chuẩn có nhiệt độ 273 K; thể tích bằng 0,0224 m3 và áp suất bằng x.10<sup>5</sup> Pa. Giá trị của x bằng bao nhiêu? (Kết quả làm tròn 2 chữ số thập phân).<br>B. TỰ LUẬN","difficulty":"de","explanation":"$\\begin{aligned}\\end{aligned}p.V=nRT\\Rightarrow p.0,0224=1.8,31.273\\Rightarrow p=1,01.10^5Pa\\Rightarrow x=1,01Website: thukhoadaihoc.vn$<br>B. TỰ LUẬN","difficultySource":"ai"},"ex":[{"exam":404,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"0,1","question":"Một mol khí lí tưởng ở điều kiện chuẩn có nhiệt độ 273 K; thể tích bằng 0,0224 m3 và áp suất bằng x.10<sup>5</sup> Pa. Giá trị của x bằng bao nhiêu? (Kết quả làm tròn 2 chữ số thập phân).<br>B. TỰ LUẬN","difficulty":"de","explanation":"$\\begin{aligned}\\end{aligned}p.V=nRT\\Rightarrow p.0,0224=1.8,31.273\\Rightarrow p=1,01.10^5Pa\\Rightarrow x=1,01Website: thukhoadaihoc.vn$<br>B. TỰ LUẬN","difficultySource":"ai"}}]},{"id":671620,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"1650","question":"(0,5 điểm). Biết nhiệt nóng chảy riêng của nước đá là 3,30.10<sup>5</sup> J/kg. Tính nhiệt lượng cần thiết để cung cấp cho 5 kg nước đá ở 00C nóng chảy hoàn toàn.","difficulty":"de","explanation":"Đề cho:  $m=5kg;\\lambda =3,3.10^5\\left(J/kg\\right)$<br>Nhiệt lượng cần thiết để cung cấp cho 5kg nước đá ở 00C nóng chảy hoàn toàn là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}Q=m\\lambda =5.3,3.10^5=1650000JWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":404,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"1650","question":"(0,5 điểm). Biết nhiệt nóng chảy riêng của nước đá là 3,30.10<sup>5</sup> J/kg. Tính nhiệt lượng cần thiết để cung cấp cho 5 kg nước đá ở 00C nóng chảy hoàn toàn.","difficulty":"de","explanation":"Đề cho:  $m=5kg;\\lambda =3,3.10^5\\left(J/kg\\right)$<br>Nhiệt lượng cần thiết để cung cấp cho 5kg nước đá ở 00C nóng chảy hoàn toàn là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}Q=m\\lambda =5.3,3.10^5=1650000JWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":671621,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"a)","question":"(1,0 điểm). Trong một bình kín có có thể tích 0,05 m3 chứa khí oxygen ở nhiệt độ 270C và áp suất là 3,0.10<sup>5</sup> Pa. Khối lượng mol của phân tử khí oxygen bằng 32 g/mol.<br>a) Xác định khối lượng của khí oxygen có trong bình.<br>b) Xác định số phân tử khí oxygen chứa trong bình.","difficulty":"trung-binh","explanation":"Đề cho:  $V=0,05m^3;T=300K;p=3.10^5Pa;M=32\\left(g/mol\\right)$<br>a) Áp dụng phương trình Claperon:  $pV=nRT$<br>Suy ra:  $3.10^5.0,05=n.8,31.300$<br>Nên:  $n=6mol$<br>Từ đó: Khối lượng khí Oxyen là:  $m=nM=6.32=192\\left(gam\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) Số phân tử khí Oxygen trong bình là:  $N=n.N_A=6.6,02.10^{23}=3,612.10^{24}$  (phân tử)","difficultySource":"ai"},"ex":[{"exam":404,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"a)","question":"(1,0 điểm). Trong một bình kín có có thể tích 0,05 m3 chứa khí oxygen ở nhiệt độ 270C và áp suất là 3,0.10<sup>5</sup> Pa. Khối lượng mol của phân tử khí oxygen bằng 32 g/mol.<br>a) Xác định khối lượng của khí oxygen có trong bình.<br>b) Xác định số phân tử khí oxygen chứa trong bình.","difficulty":"trung-binh","explanation":"Đề cho:  $V=0,05m^3;T=300K;p=3.10^5Pa;M=32\\left(g/mol\\right)$<br>a) Áp dụng phương trình Claperon:  $pV=nRT$<br>Suy ra:  $3.10^5.0,05=n.8,31.300$<br>Nên:  $n=6mol$<br>Từ đó: Khối lượng khí Oxyen là:  $m=nM=6.32=192\\left(gam\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) Số phân tử khí Oxygen trong bình là:  $N=n.N_A=6.6,02.10^{23}=3,612.10^{24}$  (phân tử)","difficultySource":"ai"}}]},{"id":671633,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":1,"options":["10,7.10<sup>−6</sup> kg.","9,7.10<sup>−6</sup> kg.","7,1.10<sup>−6</sup> kg.","8,1.10<sup>−6</sup> kg."],"question":"Một bình chứa 4,5 lít khí hydrogen (H2) ở nhiệt độ 240C, áp suất 2.10<sup>5</sup> Pa. Người ta tăng nhiệt độ của khí hiđrô lên tới 280C. Vì bình này không kín nên có một phần khí hydrogen thoát ra ngoài, coi áp suất khí trong bình không thay đổi. Biết khối lượng mol của phân tử hydrogen là M = 2.10<sup>−3</sup> kg/mol. Khối lượng khí hydrogen thoát ra ngoài xấp xỉ","difficulty":"trung-binh","explanation":"$pV=nRT\\Rightarrow \\left\\{\\begin{aligned}2.10^5.4,5.10^{−3}=n.8,31.\\left(24+273\\right) <br>2.10^5.4,5.10^{−3}=n^/.8,31.\\left(28+273\\right) <br>Website: thukhoadaihoc.vn\\end{aligned}\\right.$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow \\left(n−n^/\\right).2gam.\\left(10^{−3}\\right)=9,7.10^{−6}\\left(kg\\right)$","difficultySource":"ai"},"ex":[{"exam":405,"idx":11,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":1,"options":["10,7.10<sup>−6</sup> kg.","9,7.10<sup>−6</sup> kg.","7,1.10<sup>−6</sup> kg.","8,1.10<sup>−6</sup> kg."],"question":"Một bình chứa 4,5 lít khí hydrogen (H2) ở nhiệt độ 240C, áp suất 2.10<sup>5</sup> Pa. Người ta tăng nhiệt độ của khí hiđrô lên tới 280C. Vì bình này không kín nên có một phần khí hydrogen thoát ra ngoài, coi áp suất khí trong bình không thay đổi. Biết khối lượng mol của phân tử hydrogen là M = 2.10<sup>−3</sup> kg/mol. Khối lượng khí hydrogen thoát ra ngoài xấp xỉ","difficulty":"trung-binh","explanation":"$pV=nRT\\Rightarrow \\left\\{\\begin{aligned}2.10^5.4,5.10^{−3}=n.8,31.\\left(24+273\\right) <br>2.10^5.4,5.10^{−3}=n^/.8,31.\\left(28+273\\right) <br>Website: thukhoadaihoc.vn\\end{aligned}\\right.$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow \\left(n−n^/\\right).2gam.\\left(10^{−3}\\right)=9,7.10^{−6}\\left(kg\\right)$","difficultySource":"ai"}}]},{"id":671635,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":1,"options":["1,4 g.","1 g.","2 g.","1,5 g."],"question":"Một bình kín có 1,88.10<sup>22</sup> phân tử khí oxygen. Biết khối lượng mol của khí oxygen là 32 g/mol. Khối lượng khí oxygen trong bình là","difficulty":"de","explanation":"$\\begin{aligned}\\end{aligned}\\frac{N}{N_A}.m=\\frac{1,88.10^{22}}{6,02.10^{23}}.32=1\\left(gam\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":405,"idx":13,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Mol,