p>23</sup>."],"question":"Biết khối lượng mol của phân tử nước (H2O) là 18 g/mol. Số phân tử nước có trong 1 g H2O là","difficulty":"de","explanation":"$N=n.N_A=\\frac{m}{A}.N_A=$   $\\left(\\frac{1}{18}\\right).6,02.10^{23}=3,34.10^{22}Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":405,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":0,"options":["3,34.10<sup>22</sup>.","3,01.10<sup>23</sup>.","3,01.10<sup>22</sup>.","3,34.10<sup>23</sup>."],"question":"Biết khối lượng mol của phân tử nước (H2O) là 18 g/mol. Số phân tử nước có trong 1 g H2O là","difficulty":"de","explanation":"$N=n.N_A=\\frac{m}{A}.N_A=$   $\\left(\\frac{1}{18}\\right).6,02.10^{23}=3,34.10^{22}Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":671640,"nq":{"form":"bai_tap","type":"true_false","topic":"Áp suất và động năng phân tử khí","question":"Áp suất của một khối khí lí tưởng là 2 MPa, số phân tử khí trong 1 cm3 là 4,84.10<sup>20</sup>.","difficulty":"kho","statements":[{"text":"Động năng trung bình của phân tử khí là 8,26.10<sup>−21</sup> J.","answer":false},{"text":"Nếu nhiệt độ khối khí tăng gấp đôi thì tốc độ của phân tử khí cũng tăng gấp đôi.","answer":false},{"text":"Mật độ phân tử của khối khí lí tưởng là 4,84.10<sup>26</sup> phân tử/m3.","answer":true},{"text":"Nhiệt độ của khí là 299,44 Κ.","answer":true}],"explanation":"a) sai<br>$p=\\frac{1}{3}\\frac{Nm}{V}\\overline{v^2}=\\frac{2}{3}.\\frac{N}{V}\\overline{E_d}$<br>$\\begin{aligned}\\end{aligned}p=\\frac{2}{3}.\\mu .\\overline{E}_d=\\frac{2}{3}.\\frac{4,84.10^{20}}{10^{−6}}.\\overline{E}_d=2.10^6\\Rightarrow \\overline{E}_d=6,2.10^{−21}\\left(J\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>$\\overline{E}_d=\\frac{1}{2}m\\overline{v^2}=\\frac{3}{2}kT$<br>$\\Rightarrow T\\sim W_d\\sim v^2$<br>c) đúng<br>Mật độ phân tử của khối khí lý tưởng:  $\\frac{N}{V}=\\frac{4,84.10^{20}}{10^{−6}}=4,84.10^{26}\\left(phan tu/m^3\\right)$<br>d) đúng<br>$\\begin{aligned}\\end{aligned}\\overline{E}_d=\\frac{3}{2}kT\\Rightarrow 6,2.10^{−21}=\\frac{3}{2}.1,38.10^{−23}.T\\Rightarrow T=299,44\\left(K\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":405,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Áp suất và động năng phân tử khí","question":"Áp suất của một khối khí lí tưởng là 2 MPa, số phân tử khí trong 1 cm3 là 4,84.10<sup>20</sup>.","difficulty":"kho","statements":[{"text":"Động năng trung bình của phân tử khí là 8,26.10<sup>−21</sup> J.","answer":false},{"text":"Nếu nhiệt độ khối khí tăng gấp đôi thì tốc độ của phân tử khí cũng tăng gấp đôi.","answer":false},{"text":"Mật độ phân tử của khối khí lí tưởng là 4,84.10<sup>26</sup> phân tử/m3.","answer":true},{"text":"Nhiệt độ của khí là 299,44 Κ.","answer":true}],"explanation":"a) sai<br>$p=\\frac{1}{3}\\frac{Nm}{V}\\overline{v^2}=\\frac{2}{3}.\\frac{N}{V}\\overline{E_d}$<br>$\\begin{aligned}\\end{aligned}p=\\frac{2}{3}.\\mu .\\overline{E}_d=\\frac{2}{3}.\\frac{4,84.10^{20}}{10^{−6}}.\\overline{E}_d=2.10^6\\Rightarrow \\overline{E}_d=6,2.10^{−21}\\left(J\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>$\\overline{E}_d=\\frac{1}{2}m\\overline{v^2}=\\frac{3}{2}kT$<br>$\\Rightarrow T\\sim W_d\\sim v^2$<br>c) đúng<br>Mật độ phân tử của khối khí lý tưởng:  $\\frac{N}{V}=\\frac{4,84.10^{20}}{10^{−6}}=4,84.10^{26}\\left(phan tu/m^3\\right)$<br>d) đúng<br>$\\begin{aligned}\\end{aligned}\\overline{E}_d=\\frac{3}{2}kT\\Rightarrow 6,2.10^{−21}=\\frac{3}{2}.1,38.10^{−23}.T\\Rightarrow T=299,44\\left(K\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":671644,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"40","question":"Khí cầu có dung tích 328 m3 được bơm khí hydrogen. Khi bơm xong, hydrogen trong khí cầu có nhiệt độ 270C, áp suất 1,5 atm (1 atm = 1,013.10<sup>5</sup> Pa). Cho khối lượng mol của khí hydrogen là 2 g/mol. Tính khối lượng khí hydrogen trong khí cầu theo đơn vị kg (làm tròn kết quả đến hàng đơn vị).","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\end{aligned}pV=nRT=\\frac{m}{M}RTWebsite: thukhoadaihoc.vn\\Rightarrow \\left(1,5.1,012.10^5\\right).328=\\frac{m}{2}.8,31.300$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow m=40kg$","difficultySource":"ai"},"ex":[{"exam":405,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"40","question":"Khí cầu có dung tích 328 m3 được bơm khí hydrogen. Khi bơm xong, hydrogen trong khí cầu có nhiệt độ 270C, áp suất 1,5 atm (1 atm = 1,013.10<sup>5</sup> Pa). Cho khối lượng mol của khí hydrogen là 2 g/mol. Tính khối lượng khí hydrogen trong khí cầu theo đơn vị kg (làm tròn kết quả đến hàng đơn vị).","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\end{aligned}pV=nRT=\\frac{m}{M}RTWebsite: thukhoadaihoc.vn\\Rightarrow \\left(1,5.1,012.10^5\\right).328=\\frac{m}{2}.8,31.300$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow m=40kg$","difficultySource":"ai"}}]},{"id":672141,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":1,"options":["1,2%.","0,033%.","0,18%.","0,023%."],"question":"Trong chuỗi phản ứng prton-proton trong lòng Mặt Trời có hai phản ứng riêng biệt trong đó 4 hạt nhân hydro cuối cùng có thể dẫn đến 1 hạt nhân Heli. Trong chuỗi phản ứng này, phản ứng  ${}_1^2D+{}_1^1H\\rightarrow {}_2^3He+\\gamma$  tạo ra bức xạ điện từ gamma. Biết mP = 1,00728u; mD = 2,0135u; mHe = 3,0149u. Lấy 1u = 931,5 MeV/c2. Giả sử hạt nhân Heli sinh ra trong lõi Mặt Trời chuyển động nhiệt ở nhiệt độ trung bình vào khoảng 13,6.10<sup>6</sup>(0C) (nhiệt độ trong lòng Mặt Trời ). Động năng trung bình của chuyển động nhiệt của khí  ${}_2^3He$ chiếm xấp xỉ  bao nhiêu phần trăm so với năng lượng phản ứng tỏa ra? (Coi các hạt nhân  ${}_2^3He$  là các phân tử khí lí tưởng)","difficulty":"kho","explanation":"Năng lượng tỏa ra của phản ứng:<br>$E=\\left(m_D+m_P−m_{He}\\right).931,5\\approx 5,48\\left(MeV\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Động năng trung bình của chuyển động nhiệt:<br>$E=\\frac{3}{2}kT=\\frac{3}{2}.1,38.10^{−23}.\\left(273+13,6.10^6\\right);\\left(1,6.10^{−13}\\right)\\approx 0,0018\\left(MeV\\right)$<br>Phần trăm động năng hạt nhân  ${}_2^3He$  so với năng lượng phản ứng tỏa ra là:<br>$\\frac{0,0018}{5,48}.100%$   = 0,033%","difficultySource":"ai"},"ex":[{"exam":406,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":1,"options":["1,2%.","0,033%.","0,18%.","0,023%."],"question":"Trong chuỗi phản ứng prton-proton trong lòng Mặt Trời có hai phản ứng riêng biệt trong đó 4 hạt nhân hydro cuối cùng có thể dẫn đến 1 hạt nhân Heli. Trong chuỗi phản ứng này, phản ứng  ${}_1^2D+{}_1^1H\\rightarrow {}_2^3He+\\gamma$  tạo ra bức xạ điện từ gamma. Biết mP = 1,00728u; mD = 2,0135u; mHe = 3,0149u. Lấy 1u = 931,5 MeV/c2. Giả sử hạt nhân Heli sinh ra trong lõi Mặt Trời chuyển động nhiệt ở nhiệt độ trung bình vào khoảng 13,6.10<sup>6</sup>(0C) (nhiệt độ trong lòng Mặt Trời ). Động năng trung bình của chuyển động nhiệt của khí  ${}_2^3He$ chiếm xấp xỉ  bao nhiêu phần trăm so với năng lượng phản ứng tỏa ra? (Coi các hạt nhân  ${}_2^3He$  là các phân tử khí lí tưởng)","difficulty":"kho","explanation":"Năng lượng tỏa ra của phản ứng:<br>$E=\\left(m_D+m_P−m_{He}\\right).931,5\\approx 5,48\\left(MeV\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Động năng trung bình của chuyển động nhiệt:<br>$E=\\frac{3}{2}kT=\\frac{3}{2}.1,38.10^{−23}.\\left(273+13,6.10^6\\right);\\left(1,6.10^{−13}\\right)\\approx 0,0018\\left(MeV\\right)$<br>Phần trăm động năng hạt nhân  ${}_2^3He$  so với năng lượng phản ứng tỏa ra là:<br>$\\frac{0,0018}{5,48}.100%$   = 0,033%","difficultySource":"ai"}}]},{"id":672145,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Radon là khí không màu, không mùi và không vị. Do đó không thể phát hiện chỉ bằng giác quan con người.  Radon  ${}_{86}^{222}Rn$   là một đồng vị phân rã alpha và sinh ra hạt nhân con X với chu kỳ 3,82 ngày. Nguyên tố  ${}_{86}^{222}Rn$ tích tụ trong các ngôi nhà được WHO cho là nguyên nhân thứ hai gây ra bệnh ung thư phổi sau thuốc lá.<br>Trong một khảo sát tại Bình Dương, Việt Nam người ta đo được độ phóng xạ trong 1m3 không khí chứa khoảng 11,4 triệu nguyên tử khí radon. Biết rằng độ phóng xạ an toàn của radon trong không khí vào khoảng 150 Bq/m3.","difficulty":"trung-binh","statements":[{"text":"Hằng số phân rã phóng xạ của  ${}_{86}^{222}Rn$  là 2,1.10<sup>−6</sup> (s-1)","answer":true},{"text":"Độ phóng xạ của khí radong tại vị trí khảo sát là 200 Bq/m3.","answer":false},{"text":"Độ phóng xạ của khí radon tại Bình Dương ở mức nguy hiểm.","answer":false},{"text":"Biết  $m_{{}_{88}^{222}Rn}$  = 222,0175u;  $m_{{}_2^4He}$ 4,0026u ; mX = 218,0089u . Phản ứng toả ra năng lượng là 5,587 MeV (bỏ qua phóng xạ gamma).","answer":true}],"explanation":"a) đúng<br>Hằng số phân rã là:  $\\lambda =\\frac{ln2}{T}=\\frac{ln2}{3,82.24.3600}\\approx 2,1.10^{−6}\\left(s^{−1}\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>Áp dụng công thức:  $H=\\lambda .N\\approx 24\\left(Bq/m^3\\right)$<br>c) sai<br>Độ phóng xạ nhỏ hơn mức giới hạn (24 Bq/m3 < 150 Bq/m3) nên nồng độ khí radon tại Bình Dương ở mức an toàn.<br>d) đúng<br>Năng lượng của phản ứng:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$E=\\left(m_{Rn}−m_{He}−m_X\\right).931\\left(MeV\\right)=5,587\\left(MeV\\right)$","difficultySource":"ai"},"ex":[{"exam":406,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Radon là khí không màu, không mùi và không vị. Do đó không thể phát hiện chỉ bằng giác quan con người.  Radon  ${}_{86}^{222}Rn$   là một đồng vị phân rã alpha và sinh ra hạt nhân con X với chu kỳ 3,82 ngày. Nguyên tố  ${}_{86}^{222}Rn$ tích tụ trong các ngôi nhà được WHO cho là nguyên nhân thứ hai gây ra bệnh ung thư phổi sau thuốc lá.<br>Trong một khảo sát tại Bình Dương, Việt Nam người ta đo được độ phóng xạ trong 1m3 không khí chứa khoảng 11,4 triệu nguyên tử khí radon. Biết rằng độ phóng xạ an toàn của radon trong không khí vào khoảng 150 Bq/m3.","difficulty":"trung-binh","statements":[{"text":"Hằng số phân rã phóng xạ của  ${}_{86}^{222}Rn$  là 2,1.10<sup>−6</sup> (s-1)","answer":true},{"text":"Độ phóng xạ của khí radong tại vị trí khảo sát là 200 Bq/m3.","answer":false},{"text":"Độ phóng xạ của khí radon tại Bình Dương ở mức nguy hiểm.","answer":false},{"text":"Biết  $m_{{}_{88}^{222}Rn}$  = 222,0175u;  $m_{{}_2^4He}$ 4,0026u ; mX = 218,0089u . Phản ứng toả ra năng lượng là 5,587 MeV (bỏ qua phóng xạ gamma).","answer":true}],"explanation":"a) đúng<br>Hằng số phân rã là:  $\\lambda =\\frac{ln2}{T}=\\frac{ln2}{3,82.24.3600}\\approx 2,1.10^{−6}\\left(s^{−1}\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>Áp dụng công thức:  $H=\\lambda .N\\approx 24\\left(Bq/m^3\\right)$<br>c) sai<br>Độ phóng xạ nhỏ hơn mức giới hạn (24 Bq/m3 < 150 Bq/m3) nên nồng độ khí radon tại Bình Dương ở mức an toàn.<br>d) đúng<br>Năng lượng của phản ứng:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$E=\\left(m_{Rn}−m_{He}−m_X\\right).931\\left(MeV\\right)=5,587\\left(MeV\\right)$","difficultySource":"ai"}}]},{"id":672148,"nq":{"form":"bai_tap","type":"short_answer","topic":"Lực từ. Cảm ứng từ","answer":"9,1","question":"Trong phóng thí nghiệm Lawrence Berkeley người ta tiến hành xác định đo bản chất của hạt X là loại hạt gì. Các nhà thực nghiệm đã phóng hạt X vào từ trường đều có độ lớn 5 mT, có phương vuông góc với mặt phẳng chuyển động của các điện tích và hướng từ trong ra ngoài mặt phẳng hình vẽ. Hạt đi vào trong vù từ trường với tốc độ 2.10<sup>7</sup> (m /s). Đường kính của hạt khi chuyển động được nửa vòng quỹ đạo là 4,55 cm. Bỏ qua sức cản của buồng bọt lên chuyển động của hạt trong nửa đầu quỹ đạo chuyển động. Biết điện tích của hạt có độ lớn 1,6.10<sup>−19</sup>(C) . Khối lượng hạt X là bao nhiêu? (x10-31 (kg), lấy hai chữ số có nghĩa)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046790732-hinh-13.jpg\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Khi hạt mang điện chuyển động vuông góc với đường sức từ trường, bán kính quỹ đạo được tính theo công  thức:<br>$\\begin{aligned}\\end{aligned}R=\\left|\\frac{mv}{qB}\\right|\\Rightarrow m=\\left|\\frac{qBR}{v}\\right|=\\frac{1,6.10^{−19}.5.10^{−3}.\\left(\\frac{4,55}{2}.10^{−2}\\right)}{2.10^7}=9,1.10^{−31}\\left(kg\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Vì hạt mang điện tích dương nên hạt X là hạt Positron.","difficultySource":"ai"},"ex":[{"exam":406,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Lực từ. Cảm ứng từ","answer":"9,1","question":"Trong phóng thí nghiệm Lawrence Berkeley người ta tiến hành xác định đo bản chất của hạt X là loại hạt gì. Các nhà thực nghiệm đã phóng hạt X vào từ trường đều có độ lớn 5 mT, có phương vuông góc với mặt phẳng chuyển động của các điện tích và hướng từ trong ra ngoài mặt phẳng hình vẽ. Hạt đi vào trong vù từ trường với tốc độ 2.10<sup>7</sup> (m /s). Đường kính của hạt khi chuyển động được nửa vòng quỹ đạo là 4,55 cm. Bỏ qua sức cản của buồng bọt lên chuyển động của hạt trong nửa đầu quỹ đạo chuyển động. Biết điện tích của hạt có độ lớn 1,6.10<sup>−19</sup>(C) . Khối lượng hạt X là bao nhiêu? (x10-31 (kg), lấy hai chữ số có nghĩa)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046790732-hinh-13.jpg\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Khi hạt mang điện chuyển động vuông góc với đường sức từ trường, bán kính quỹ đạo được tính theo công  thức:<br>$\\begin{aligned}\\end{aligned}R=\\left|\\frac{mv}{qB}\\right|\\Rightarrow m=\\left|\\frac{qBR}{v}\\right|=\\frac{1,6.10^{−19}.5.10^{−3}.\\left(\\frac{4,55}{2}.10^{−2}\\right)}{2.10^7}=9,1.10^{−31}\\left(kg\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Vì hạt mang điện tích dương nên hạt X là hạt Positron.","difficultySource":"ai"}}]},{"id":672151,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"5,12","question":"Cho rằng khi một hạt nhân urani 29325U phân hạch thì toả ra năng lượng trung bình là 200 MeV, Lấy NA = 6,023.10<sup>23</sup> mol-1, khối lượng mol của urani 29325U là 235 g/mol. Năng lượng tỏa ra khi phân hạch hết 1 kg urani   ${}_{92}^{235}U$  là bao nhiêu? (×1026 MeV, làm tròn đến số thập phân thứ hai)","difficulty":"trung-binh","explanation":"Số hạt nhân  ${}^{235}U$ trong 1kg:  $N=\\frac{N_A.m}{\\mu }=\\frac{6,023.10^{23}.1}{0,235}=25,63.10^{23}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Năng lượng tỏa ra khi phân hạch hết 1 kg  ${}^{235}U$ là:  E = 200.N = 5,12.10<sup>26</sup>MeV.","difficultySource":"ai"},"ex":[{"exam":406,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"5,12","question":"Cho rằng khi một hạt nhân urani 29325U phân hạch thì toả ra năng lượng trung bình là 200 MeV, Lấy NA = 6,023.10<sup>23</sup> mol-1, khối lượng mol của urani 29325U là 235 g/mol. Năng lượng tỏa ra khi phân hạch hết 1 kg urani   ${}_{92}^{235}U$  là bao nhiêu? (×1026 MeV, làm tròn đến số thập phân thứ hai)","difficulty":"trung-binh","explanation":"Số hạt nhân  ${}^{235}U$ trong 1kg:  $N=\\frac{N_A.m}{\\mu }=\\frac{6,023.10^{23}.1}{0,235}=25,63.10^{23}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Năng lượng tỏa ra khi phân hạch hết 1 kg  ${}^{235}U$ là:  E = 200.N = 5,12.10<sup>26</sup>MeV.","difficultySource":"ai"}}]},{"id":672161,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":0,"options":["3,33 m.","33,3 km.","33,3 m.","3,33 km."],"question":"Một sóng điện từ có tần số 90 MHz truyền trong không khí với tốc độ 3.10<sup>8</sup> m/s. Bước sóng của sóng này là","difficulty":"de","explanation":"Công thức liên hệ bước sóng, tốc độ và tần số sóng điện từ: λ = c/f.<br>Thay số: λ = 3.10⁸ / (90.10⁶) = 3,33 (m).<br>Kết luận: bước sóng của sóng là 3,33 m. Đáp số: A.<br>$\\lambda =\\frac{c}{f}=\\frac{3.10^8}{90.10^6}=3,33\\left(m\\right)$","difficultySource":"ai"},"ex":[{"exam":407,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":0,"options":["3,33 m.","33,3 km.","33,3 m.","3,33 km."],"question":"Một sóng điện từ có tần số 90 MHz truyền trong không khí với tốc độ 3.10<sup>8</sup> m/s. Bước sóng của sóng này là","difficulty":"de","explanation":"Công thức liên hệ bước sóng, tốc độ và tần số sóng điện từ: λ = c/f.<br>Thay số: λ = 3.10⁸ / (90.10⁶) = 3,33 (m).<br>Kết luận: bước sóng của sóng là 3,33 m. Đáp số: A.<br>$\\lambda =\\frac{c}{f}=\\frac{3.10^8}{90.10^6}=3,33\\left(m\\right)$","difficultySource":"ai"}}]},{"id":672163,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["13,4 J.","1,34 J.","2,68 J.","26,8 J."],"question":"Nhiệt nóng chảy riêng của đồng là 1,34.10<sup>5</sup> J/kg. Tại nhiệt độ nóng chảy, nhiệt lượng cần cung cấp để 200 mg đồng nóng chảy hoàn toàn là","difficulty":"de","explanation":"Công thức nhiệt lượng nóng chảy: Q = λ.m, với λ là nhiệt nóng chảy riêng.<br>Thay số: m = 200 mg = 200.10⁻⁶ kg ⇒ Q = 1,34.10⁵ . 200.10⁻⁶ = 26,8 (J).<br>Kết luận: nhiệt lượng cần cung cấp để 200 mg đồng nóng chảy hoàn toàn là 26,8 J. Đáp số: D.<br>$Q=\\lambda m=1,34.10^5.200.10^{−6}=26,8\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":407,"idx":11,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["13,4 J.","1,34 J.","2,68 J.","26,8 J."],"question":"Nhiệt nóng chảy riêng của đồng là 1,34.10<sup>5</sup> J/kg. Tại nhiệt độ nóng chảy, nhiệt lượng cần cung cấp để 200 mg đồng nóng chảy hoàn toàn là","difficulty":"de","explanation":"Công thức nhiệt lượng nóng chảy: Q = λ.m, với λ là nhiệt nóng chảy riêng.<br>Thay số: m = 200 mg = 200.10⁻⁶ kg ⇒ Q = 1,34.10⁵ . 200.10⁻⁶ = 26,8 (J).<br>Kết luận: nhiệt lượng cần cung cấp để 200 mg đồng nóng chảy hoàn toàn là 26,8 J. Đáp số: D.<br>$Q=\\lambda m=1,34.10^5.200.10^{−6}=26,8\\left(J\\right)$","difficultySource":"ai"}}]},{"id":672175,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"24,7","question":"Một bình kín chứa 2,0 mol khí lý tưởng. Áp suất, nhiệt độ của khí trong bình lần lượt là 2.10<sup>5</sup> Pa và<br>240C. Thể tích của bình bằng bao nhiêu lít? (làm tròn kết quả đến chữ số hàng phần mười)","difficulty":"de","explanation":"Công thức: phương trình trạng thái khí lí tưởng pV = nRT.<br>Thay số: T = 24+273 = 297 K ⇒ V = nRT/p = (2.8,31.297)/(2.10⁵) = 0,024681 m³ = 24,681 lít.<br>Kết luận: làm tròn đến hàng phần mười, V ≈ 24,7 lít. Đáp số: 24,7.<br>$pV=nRT$<br>$\\Rightarrow 2.10^5.V=2.8,31.\\left(24+273\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow V=0,0246807m^3=24,7\\left(lit\\right)$","difficultySource":"ai"},"ex":[{"exam":407,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"24,7","question":"Một bình kín chứa 2,0 mol khí lý tưởng. Áp suất, nhiệt độ của khí trong bình lần lượt là 2.10<sup>5</sup> Pa và<br>240C. Thể tích của bình bằng bao nhiêu lít? (làm tròn kết quả đến chữ số hàng phần mười)","difficulty":"de","explanation":"Công thức: phương trình trạng thái khí lí tưởng pV = nRT.<br>Thay số: T = 24+273 = 297 K ⇒ V = nRT/p = (2.8,31.297)/(2.10⁵) = 0,024681 m³ = 24,681 lít.<br>Kết luận: làm tròn đến hàng phần mười, V ≈ 24,7 lít. Đáp số: 24,7.<br>$pV=nRT$<br>$\\Rightarrow 2.10^5.V=2.8,31.\\left(24+273\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow V=0,0246807m^3=24,7\\left(lit\\right)$","difficultySource":"ai"}}]},{"id":672177,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":"35","question":"Hình bên mô tả một chiếc bàn là hơi nước. Nước từ một bình chứa nhỏ giọt vào một tấm kim loại được nung nóng bằng điện. Bộ phận làm nóng tiêu thụ công suất điện 1,5 kW. Giả sử rằng toàn bộ năng lượng từ bộ phận làm nóng được truyền đến tấm kim loại. Tấm kim loại được duy trì ở nhiệt độ làm việc của nó. Nước ở 300C nhỏ giọt vào tấm kim loại làm hơi nước ở 1000C liên tục thoát ra từ bản là.<br>Nhiệt hóa hơi riêng của nước là 2,3.10<sup>6</sup> J/kg, nhiệt dung riêng của nước là 4180 J/kg.K. Mỗi phút bàn là tạo ra bao nhiêu gam hơi nước? (làm tròn kết quả đến chữ số hàng đơn vị)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046803735-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Công thức: năng lượng điện chuyển hết thành nhiệt để đun nước từ 30°C lên 100°C rồi hóa hơi hoàn toàn ở 100°C: Q = P.t = m.c.Δt + m.L.<br>Thay số: t = 60 s (1 phút), Δt = 100−30 = 70°C ⇒ 1500.60 = m.4180.70 + m.2,3.10⁶ = m.(292600+2300000) ⇒ m = 90000/2592600 ≈ 0,0347 kg = 34,7 g.<br>Kết luận: làm tròn đến hàng đơn vị, mỗi phút bàn là tạo ra khoảng 35 g hơi nước. Đáp số: 35.<br>$Q=P.t=mc\\Delta t$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow 1500.60=m.4180.70+m.2,3.10^6Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow m=0,0347\\left(kg\\right)\\Rightarrow 35gam$","difficultySource":"ai"},"ex":[{"exam":407,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":"35","question":"Hình bên mô tả một chiếc bàn là hơi nước. Nước từ một bình chứa nhỏ giọt vào một tấm kim loại được nung nóng bằng điện. Bộ phận làm nóng tiêu thụ công suất điện 1,5 kW. Giả sử rằng toàn bộ năng lượng từ bộ phận làm nóng được truyền đến tấm kim loại. Tấm kim loại được duy trì ở nhiệt độ làm việc của nó. Nước ở 300C nhỏ giọt vào tấm kim loại làm hơi nước ở 1000C liên tục thoát ra từ bản là.<br>Nhiệt hóa hơi riêng của nước là 2,3.10<sup>6</sup> J/kg, nhiệt dung riêng của nước là 4180 J/kg.K. Mỗi phút bàn là tạo ra bao nhiêu gam hơi nước? (làm tròn kết quả đến chữ số hàng đơn vị)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046803735-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Công thức: năng lượng điện chuyển hết thành nhiệt để đun nước từ 30°C lên 100°C rồi hóa hơi hoàn toàn ở 100°C: Q = P.t = m.c.Δt + m.L.<br>Thay số: t = 60 s (1 phút), Δt = 100−30 = 70°C ⇒ 1500.60 = m.4180.70 + m.2,3.10⁶ = m.(292600+2300000) ⇒ m = 90000/2592600 ≈ 0,0347 kg = 34,7 g.<br>Kết luận: làm tròn đến hàng đơn vị, mỗi phút bàn là tạo ra khoảng 35 g hơi nước. Đáp số: 35.<br>$Q=P.t=mc\\Delta t$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow 1500.60=m.4180.70+m.2,3.10^6Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow m=0,0347\\left(kg\\right)\\Rightarrow 35gam$","difficultySource":"ai"}}]},{"id":672412,"nq":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một nhóm học sinh ở một trường THPT tại Nghệ An đã tiến hành thí nghiệm đo nhiệt nóng chảy riêng của nước đá. Bố trí thí nghiệm, số liệu đo được và vẽ được đồ thị như hình dưới đây.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046810871-hinh-18.webp\" alt=\"Hình 18\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046811241-hinh-19.png\" alt=\"Hình 19\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Đo công suất tỏa nhiệt của điện trở là dụng cụ (2) trong sơ đồ bên.","answer":true},{"text":"Oát kế đo công suất trong thí nghiệm có độ chính xác 0,01 W.","answer":true},{"text":"Các bước tiến hành thí nghiệm là như sau: Đầu tiên bật biến thế nguồn, tiếp đến cho nước đá vào nhiệt lượng kế và hứng nước chảy ra bằng một chiếc cốc, tiến hành đo thời gian và đo công suất nhiệt, cân khối lượng nước chảy vào cốc.","answer":false},{"text":"Khối lượng nước đá dùng trong thí nghiệm là m = 25 g. Nhiệt nóng chảy riêng đo được trong thí nghiệm này có giá trị trung bình là λ = 3,42.10<sup>5</sup> J/kg.","answer":true}],"explanation":"a) đúng<br>(2) là oát kế tích hợp bộ đếm thời gian → đo thời gian cung cấp công suất P cho điện trở bên trong nhiệt lượng kế (4) và điện trở toả nhiệt ra cho nước<br>b) đúng<br>Nhìn từ bảng công suất P(W) làm tròn đến hàng phần trăm → Độ chính xác 0,01 W là chính xác<br>c) sai<br>Dạng thí nghiệm này không phải là hứng lượng nước chảy ra mà là thí nghiệm người ta sẽ đo thời gian từ lúc đun đến khi nào nó vượt qua  $0^0C$  (Từ  $0\\rightarrow 600s)$<br>d) đúng<br>$P=\\frac{14,25+14,23+14,19+14,25+14,23+14,24+14,22}{7}=14,23\\left(W\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$P.\\tau =m\\lambda \\Rightarrow \\lambda =\\frac{14,23.600}{25.10^{−3}}=341520\\left(J/kg\\right)$","difficultySource":"ai"},"ex":[{"exam":408,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Một nhóm học sinh ở một trường THPT tại Nghệ An đã tiến hành thí nghiệm đo nhiệt nóng chảy riêng của nước đá. Bố trí thí nghiệm, số liệu đo được và vẽ được đồ thị như hình dưới đây.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046810871-hinh-18.webp\" alt=\"Hình 18\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046811241-hinh-19.png\" alt=\"Hình 19\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Đo công suất tỏa nhiệt của điện trở là dụng cụ (2) trong sơ đồ bên.","answer":true},{"text":"Oát kế đo công suất trong thí nghiệm có độ chính xác 0,01 W.","answer":true},{"text":"Các bước tiến hành thí nghiệm là như sau: Đầu tiên bật biến thế nguồn, tiếp đến cho nước đá vào nhiệt lượng kế và hứng nước chảy ra bằng một chiếc cốc, tiến hành đo thời gian và đo công suất nhiệt, cân khối lượng nước chảy vào cốc.","answer":false},{"text":"Khối lượng nước đá dùng trong thí nghiệm là m = 25 g. Nhiệt nóng chảy riêng đo được trong thí nghiệm này có giá trị trung bình là λ = 3,42.10<sup>5</sup> J/kg.","answer":true}],"explanation":"a) đúng<br>(2) là oát kế tích hợp bộ đếm thời gian → đo thời gian cung cấp công suất P cho điện trở bên trong nhiệt lượng kế (4) và điện trở toả nhiệt ra cho nước<br>b) đúng<br>Nhìn từ bảng công suất P(W) làm tròn đến hàng phần trăm → Độ chính xác 0,01 W là chính xác<br>c) sai<br>Dạng thí nghiệm này không phải là hứng lượng nước chảy ra mà là thí nghiệm người ta sẽ đo thời gian từ lúc đun đến khi nào nó vượt qua  $0^0C$  (Từ  $0\\rightarrow 600s)$<br>d) đúng<br>$P=\\frac{14,25+14,23+14,19+14,25+14,23+14,24+14,22}{7}=14,23\\left(W\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$P.\\tau =m\\lambda \\Rightarrow \\lambda =\\frac{14,23.600}{25.10^{−3}}=341520\\left(J/kg\\right)$","difficultySource":"ai"}}]},{"id":672414,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"6","question":"Trà đá vỉa hè đã là một nét đặc trưng của phố phường Hà Nội. Khi có khách gọi trà, người bán hàng rót nước trà từ ấm vào cốc, sau đó bỏ ít viên nước đá vào cốc, du khách sẽ được thưởng thức một cốc trà đá thơm mát. Mỗi viên nước đá trước khi bỏ vào cốc trà có khối lượng 30 g, nhiệt độ –3°C. Nhiệt dung riêng của nước đá là 1800 J/kg.K; nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg. Mỗi cốc nước trà có khối lượng 250 g, nhiệt độ của nước trà trước khi rót vào cốc là 95°C, nhiệt dung riêng của nước là 4200 J/kg.K; nhiệt dung riêng của nước trà là<br>4090 J/kg.K. Nếu bỏ qua sự mất nhiệt cho thành cốc và không khí xung quanh, sau khi đá tan hoàn toàn để có một cốc nước trà có nhiệt độ 19,70C thì người bán nước phải bỏ vào cốc mấy viên nước đá? (kết quả làm tròn đến hàng đơn vị)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046812212-hinh-24.jpg\" alt=\"Hình 24\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"$Q_{thu}=Q_{toa}$<br>$\\Rightarrow m_{da}.c_{da}.\\Delta t_{da}+m_d\\lambda +m_d.c_{nc}.\\Delta t_{nc}=m_T.c_T.\\Delta t_T$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow m_d\\left[1800.3+3,4.10^5+4200.19,7\\right]=0,25.4090.\\left(95−19,4\\right)$<br>$\\Rightarrow m_{da}\\approx 0,18\\left(kg\\right)=180g$<br>1 viên 30g  $\\Rightarrow 180g\\approx$  6 viên","difficultySource":"ai"},"ex":[{"exam":408,"idx":21,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"6","question":"Trà đá vỉa hè đã là một nét đặc trưng của phố phường Hà Nội. Khi có khách gọi trà, người bán hàng rót nước trà từ ấm vào cốc, sau đó bỏ ít viên nước đá vào cốc, du khách sẽ được thưởng thức một cốc trà đá thơm mát. Mỗi viên nước đá trước khi bỏ vào cốc trà có khối lượng 30 g, nhiệt độ –3°C. Nhiệt dung riêng của nước đá là 1800 J/kg.K; nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg. Mỗi cốc nước trà có khối lượng 250 g, nhiệt độ của nước trà trước khi rót vào cốc là 95°C, nhiệt dung riêng của nước là 4200 J/kg.K; nhiệt dung riêng của nước trà là<br>4090 J/kg.K. Nếu bỏ qua sự mất nhiệt cho thành cốc và không khí xung quanh, sau khi đá tan hoàn toàn để có một cốc nước trà có nhiệt độ 19,70C thì người bán nước phải bỏ vào cốc mấy viên nước đá? (kết quả làm tròn đến hàng đơn vị)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046812212-hinh-24.jpg\" alt=\"Hình 24\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"$Q_{thu}=Q_{toa}$<br>$\\Rightarrow m_{da}.c_{da}.\\Delta t_{da}+m_d\\lambda +m_d.c_{nc}.\\Delta t_{nc}=m_T.c_T.\\Delta t_T$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow m_d\\left[1800.3+3,4.10^5+4200.19,7\\right]=0,25.4090.\\left(95−19,4\\right)$<br>$\\Rightarrow m_{da}\\approx 0,18\\left(kg\\right)=180g$<br>1 viên 30g  $\\Rightarrow 180g\\approx$  6 viên","difficultySource":"ai"}}]},{"id":672519,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":0,"options":["38,2 kJ.","19,1 kJ.","3,82 kJ.","1,91 kJ."],"question":"Cho biết nước đá có nhiệt nóng chảy riêng là 3,4.10<sup>5</sup> J/kg, nhiệt dung riêng là 2,1.10<sup>3</sup> J/kg.K. Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn 100 g nước đá ở nhiệt độ -200C là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Nước đá ở $-20^\\circ C$ phải qua hai giai đoạn: nóng lên đến $0^\\circ C$ (dùng $Q=mc\\Delta t$), rồi nóng chảy ở $0^\\circ C$ (dùng $Q=m\\lambda$, nhiệt độ không đổi). Tổng nhiệt là tổng hai phần.</p><p class=\"text-base leading-relaxed my-2\">$m=100\\ g=0{,}1\\ kg$. $Q_1=mc\\Delta t=0{,}1\\cdot2{,}1\\cdot10^3\\cdot20=4200\\ J$.</p><p class=\"text-base leading-relaxed my-2\">$Q_2=m\\lambda=0{,}1\\cdot3{,}4\\cdot10^5=34000\\ J$.</p><p class=\"text-base leading-relaxed my-2\">$Q=Q_1+Q_2=4200+34000=38200\\ J=38{,}2\\ kJ$.</p><p class=\"text-base leading-relaxed my-2\">Sai vì: B, C, D chỉ bằng $\\dfrac12$, $\\dfrac1{10}$, $\\dfrac1{20}$ kết quả; do $Q$ tỉ lệ với $m$ nên các giá trị này ứng với khối lượng $50\\ g$, $10\\ g$, $5\\ g$, không phải $100\\ g$. Nếu bỏ nhiệt đưa nước đá lên $0^\\circ C$ cũng chỉ được $34\\ kJ$, không có trong đáp án.</p><p class=\"text-base leading-relaxed my-2\">Chọn A.</p>","difficultySource":"ai"},"ex":[{"exam":409,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":0,"options":["38,2 kJ.","19,1 kJ.","3,82 kJ.","1,91 kJ."],"question":"Cho biết nước đá có nhiệt nóng chảy riêng là 3,4.10<sup>5</sup> J/kg, nhiệt dung riêng là 2,1.10<sup>3</sup> J/kg.K. Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn 100 g nước đá ở nhiệt độ -200C là","difficulty":"trung-binh","explanation":"Công thức: nhiệt lượng gồm hai giai đoạn — làm nóng nước đá từ −20°C lên 0°C: Q1 = m.c.Δt; làm nóng chảy hoàn toàn nước đá ở 0°C: Q2 = m.λ. Tổng Q = Q1 + Q2.<br>Thay số: m = 100 g = 0,1 kg; Q1 = 0,1.2100.20 = 4200 (J); Q2 = 0,1.3,4.10⁵ = 34000 (J); Q = 4200+34000 = 38200 (J) = 38,2 kJ.<br>Kết luận: nhiệt lượng cần cung cấp là 38,2 kJ. Đáp số: A.<br>$Q=0,1.2100.20+0,1+3,4.10^5=38,2\\left(kJ\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>(Cho nhiệt nóng chảy của nước đá  $t_{nc}=0^0C$ )","difficultySource":"ai"}}]},{"id":672545,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":3,"options":["0,4 mol.","0,1 mol.","0,2 mol.","0,5 mol."],"question":"Một bình kín chứa N = 3,01.10<sup>23</sup> phân tử khí helium. Số mol khí helium có trong bình là","difficulty":"de","explanation":"Công thức: số mol khí liên hệ với số phân tử qua số Avogadro: n = N/N_A.<br>Thay số: n = 3,01.10²³ / 6,02.10²³ = 0,5 (mol).<br>Kết luận: số mol khí helium trong bình là 0,5 mol. Đáp số: D.<br>$n=\\frac{N}{N_A}=0,5\\left(mol\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":410,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":3,"options":["0,4 mol.","0,1 mol.","0,2 mol.","0,5 mol."],"question":"Một bình kín chứa N = 3,01.10<sup>23</sup> phân tử khí helium. Số mol khí helium có trong bình là","difficulty":"de","explanation":"Công thức: số mol khí liên hệ với số phân tử qua số Avogadro: n = N/N_A.<br>Thay số: n = 3,01.10²³ / 6,02.10²³ = 0,5 (mol).<br>Kết luận: số mol khí helium trong bình là 0,5 mol. Đáp số: D.<br>$n=\\frac{N}{N_A}=0,5\\left(mol\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":672549,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Khi bắt đầu chu kỳ nén của một động cơ đốt trong thì một trong các xi-lanh chứa không khí có V1 = 500 cm3, áp suất p1 = 105 Pa và nhiệt độ t1 = 270C. Khi kết thúc chu kỳ, không khí đã được nén đến thể tích V2 = 45 cm3, áp suất là p2 và nhiệt độ t2 = 4670C. Biết khối lượng mol của không khí là 29 g/mol.","difficulty":"kho","statements":[{"text":"Trong quá trình nén nhiệt độ không khí tăng thêm 440 K.","answer":true},{"text":"Khối lượng không khí có trong xi-lanh là 58,6 mg.","answer":false},{"text":"Áp suất khí cuối cùng chu kì nén là 27,4.10<sup>5</sup> Pa.","answer":true},{"text":"Mối liên hệ giữa các thông số trạng thái là  $\\frac{p_1V_1}{t_1}=\\frac{p_2V_2}{t_2}$","answer":false}],"explanation":"a) Đúng. Độ tăng nhiệt độ theo thang Kelvin bằng độ tăng theo thang Celsius (cùng độ chia): Δt = t2 − t1 = 467 − 27 = 440 (K hoặc °C).<br>b) Sai. Từ pV = (m/M)RT ⇒ m = pVM/(RT) = (10⁵.500.10⁻⁶.29)/(8,31.300) = 0,5816 g = 581,6 mg, không phải 58,6 mg (lệch 10 lần).<br>c) Đúng. Áp dụng phương trình trạng thái tổng quát: (p1V1)/T1 = (p2V2)/T2 ⇒ (10⁵.500)/300 = (p2.45)/740 ⇒ p2 = 27,4.10⁵ Pa.<br>d) Sai. Phương trình trạng thái khí lí tưởng phải dùng nhiệt độ tuyệt đối T (Kelvin): p1V1/T1 = p2V2/T2, không được dùng trực tiếp nhiệt độ Celsius t1, t2 như phát biểu nêu.<br>a) đúng<br>$t_2−t_1=467−27=440K$<br>b) sai<br>$pV=nRT=\\frac{m}{M}RT\\Rightarrow 10^5.500.10^{−6}=\\frac{m}{29}.8,31.300\\Rightarrow m=0,5816\\left(gam\\right)=581,6\\left(mg\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}\\Rightarrow \\frac{10^5.500}{300}=\\frac{p_2.45}{740}\\Rightarrow p_2=27,4.10^5\\left(Pa\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}$","difficultySource":"ai"},"ex":[{"exam":410,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Khi bắt đầu chu kỳ nén của một động cơ đốt trong thì một trong các xi-lanh chứa không khí có V1 = 500 cm3, áp suất p1 = 105 Pa và nhiệt độ t1 = 270C. Khi kết thúc chu kỳ, không khí đã được nén đến thể tích V2 = 45 cm3, áp suất là p2 và nhiệt độ t2 = 4670C. Biết khối lượng mol của không khí là 29 g/mol.","difficulty":"kho","statements":[{"text":"Trong quá trình nén nhiệt độ không khí tăng thêm 440 K.","answer":true},{"text":"Khối lượng không khí có trong xi-lanh là 58,6 mg.","answer":false},{"text":"Áp suất khí cuối cùng chu kì nén là 27,4.10<sup>5</sup> Pa.","answer":true},{"text":"Mối liên hệ giữa các thông số trạng thái là  $\\frac{p_1V_1}{t_1}=\\frac{p_2V_2}{t_2}$","answer":false}],"explanation":"a) Đúng. Độ tăng nhiệt độ theo thang Kelvin bằng độ tăng theo thang Celsius (cùng độ chia): Δt = t2 − t1 = 467 − 27 = 440 (K hoặc °C).<br>b) Sai. Từ pV = (m/M)RT ⇒ m = pVM/(RT) = (10⁵.500.10⁻⁶.29)/(8,31.300) = 0,5816 g = 581,6 mg, không phải 58,6 mg (lệch 10 lần).<br>c) Đúng. Áp dụng phương trình trạng thái tổng quát: (p1V1)/T1 = (p2V2)/T2 ⇒ (10⁵.500)/300 = (p2.45)/740 ⇒ p2 = 27,4.10⁵ Pa.<br>d) Sai. Phương trình trạng thái khí lí tưởng phải dùng nhiệt độ tuyệt đối T (Kelvin): p1V1/T1 = p2V2/T2, không được dùng trực tiếp nhiệt độ Celsius t1, t2 như phát biểu nêu.<br>a) đúng<br>$t_2−t_1=467−27=440K$<br>b) sai<br>$pV=nRT=\\frac{m}{M}RT\\Rightarrow 10^5.500.10^{−6}=\\frac{m}{29}.8,31.300\\Rightarrow m=0,5816\\left(gam\\right)=581,6\\left(mg\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}\\Rightarrow \\frac{10^5.500}{300}=\\frac{p_2.45}{740}\\Rightarrow p_2=27,4.10^5\\left(Pa\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}$","difficultySource":"ai"}}]},{"id":672550,"nq":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Một chiếc xe tải vượt qua sa mạc Sahara. Chuyến đi bắt đầu vào sáng sớm khi nhiệt độ là 3,00C thì áp suất khí trong các lốp xe là 3,41.10<sup>5</sup> Pa. Đến giữa trưa, nhiệt độ tăng lên đến 420C. Coi khí trong lốp xe là khí lí tưởng và có nhiệt độ như ngoài trời, thể tích của mỗi lốp xe không đổi là 1,50 m3.","difficulty":"kho","statements":[{"text":"Số mol khí trong mỗi lốp xe là 273 mol.","answer":false},{"text":"Đến giữa trưa, áp suất của khí trong lốp xe là 3,89.10<sup>5</sup> Pa.","answer":true},{"text":"Các phân tử khí va chạm vào thành lốp gây ra áp suất khí lên lốp.","answer":true},{"text":"Nhiệt độ khi bắt đầu chuyến đi là 315 K.","answer":false}],"explanation":"a) Sai. Áp dụng pV = nRT với T1 = 3+273 = 276 K: n = p1V1/(RT1) = (3,41.10⁵.1,5)/(8,31.276) ≈ 223 mol, không phải 273 mol.<br>b) Đúng. Thể tích không đổi (đẳng tích): p1/T1 = p2/T2 ⇒ p2 = p1.T2/T1 = 3,41.10⁵.(42+273)/276 ≈ 3,89.10⁵ Pa.<br>c) Đúng. Theo thuyết động học phân tử chất khí, áp suất khí lên thành bình (lốp xe) chính là do các phân tử khí liên tục va chạm vào thành lốp gây ra.<br>d) Sai. Nhiệt độ khi bắt đầu chuyến đi (sáng sớm, 3°C) là T = 3+273 = 276 K, không phải 315 K (315 K là nhiệt độ lúc giữa trưa, 42+273).<br>a) sai<br>$pV=nRT\\Rightarrow 3,41.10^5.1,5=n.8,31.276\\Rightarrow n=223\\left(mol\\right)$<br>b) đúng<br>Thể tích không đổi:  $\\frac{p_1}{T_1}=\\frac{p_2}{T_2}\\Rightarrow \\frac{3,41.10^5}{273}=\\frac{p_2}{42+273}\\Rightarrow p_2=3,89.10^5\\left(Pa\\right)$<br>c) đúng<br>Các phân tử khí va chạm vào thành lốp gây ra áp suất khí lên lốp.<br>d) sai<br>$3+273=276\\left(K\\right)$","difficultySource":"ai"},"ex":[{"exam":410,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Một chiếc xe tải vượt qua sa mạc Sahara. Chuyến đi bắt đầu vào sáng sớm khi nhiệt độ là 3,00C thì áp suất khí trong các lốp xe là 3,41.10<sup>5</sup> Pa. Đến giữa trưa, nhiệt độ tăng lên đến 420C. Coi khí trong lốp xe là khí lí tưởng và có nhiệt độ như ngoài trời, thể tích của mỗi lốp xe không đổi là 1,50 m3.","difficulty":"kho","statements":[{"text":"Số mol khí trong mỗi lốp xe là 273 mol.","answer":false},{"text":"Đến giữa trưa, áp suất của khí trong lốp xe là 3,89.10<sup>5</sup> Pa.","answer":true},{"text":"Các phân tử khí va chạm vào thành lốp gây ra áp suất khí lên lốp.","answer":true},{"text":"Nhiệt độ khi bắt đầu chuyến đi là 315 K.","answer":false}],"explanation":"a) Sai. Áp dụng pV = nRT với T1 = 3+273 = 276 K: n = p1V1/(RT1) = (3,41.10⁵.1,5)/(8,31.276) ≈ 223 mol, không phải 273 mol.<br>b) Đúng. Thể tích không đổi (đẳng tích): p1/T1 = p2/T2 ⇒ p2 = p1.T2/T1 = 3,41.10⁵.(42+273)/276 ≈ 3,89.10⁵ Pa.<br>c) Đúng. Theo thuyết động học phân tử chất khí, áp suất khí lên thành bình (lốp xe) chính là do các phân tử khí liên tục va chạm vào thành lốp gây ra.<br>d) Sai. Nhiệt độ khi bắt đầu chuyến đi (sáng sớm, 3°C) là T = 3+273 = 276 K, không phải 315 K (315 K là nhiệt độ lúc giữa trưa, 42+273).<br>a) sai<br>$pV=nRT\\Rightarrow 3,41.10^5.1,5=n.8,31.276\\Rightarrow n=223\\left(mol\\right)$<br>b) đúng<br>Thể tích không đổi:  $\\frac{p_1}{T_1}=\\frac{p_2}{T_2}\\Rightarrow \\frac{3,41.10^5}{273}=\\frac{p_2}{42+273}\\Rightarrow p_2=3,89.10^5\\left(Pa\\right)$<br>c) đúng<br>Các phân tử khí va chạm vào thành lốp gây ra áp suất khí lên lốp.<br>d) sai<br>$3+273=276\\left(K\\right)$","difficultySource":"ai"}}]},{"id":672552,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Người ta đun nóng chảy hoàn toàn 2 kg đồng (Copper) từ nhiệt độ ban đầu 300C. Biết đồng có nhiệt độ nóng chảy là 10850C, nhiệt dung riêng là 380 J/kg.K, nhiệt nóng chảy riêng là 1,8.10<sup>5</sup> J/kg.","difficulty":"trung-binh","statements":[{"text":"Khi đang nóng chảy, nhiệt độ của đồng không đổi và bằng 10850C","answer":true},{"text":"Ở nhiệt độ độ nóng chảy, nhiệt lượng cần cung cấp để 2 kg đồng nóng chảy hoàn toàn là 6,3.10<sup>4</sup> J.","answer":false},{"text":"Khi nóng chảy các nguyên tử đồng nhận năng lượng để phá vỡ liên kết với các nguyên tử xung quanh.","answer":true},{"text":"Nhiệt lượng cần cung cấp để nung nóng 2 kg đồng từ nhiệt độ ban đầu đến nhiệt độ nóng chảy là 801,8 kJ.","answer":true}],"explanation":"a) Đúng. Trong suốt quá trình nóng chảy (chuyển thể rắn–lỏng), nhiệt độ của đồng giữ nguyên không đổi và bằng nhiệt độ nóng chảy 1085°C.<br>b) Sai. Nhiệt lượng nóng chảy: Q = λ.m = 1,8.10⁵.2 = 3,6.10⁵ J, không phải 6,3.10⁴ J.<br>c) Đúng. Trong quá trình nóng chảy, năng lượng nhận vào không làm tăng động năng (nhiệt độ không đổi) mà dùng để phá vỡ liên kết giữa các nguyên tử, chuyển từ cấu trúc rắn sang lỏng.<br>d) Đúng. Nhiệt lượng làm nóng đồng từ 30°C lên 1085°C: Q = m.c.Δt = 2.380.(1085−30) = 801800 J = 801,8 kJ.<br>a) đúng<br>Khi đang nóng chảy, nhiệt độ của đồng không đổi và bằng 10850C (áp suất xác định)<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>$Q=2.1,8.10^5=3,6.10^5\\left(J\\right)$<br>c) đúng<br>Lúc này năng lượng nhiệt nhận vào không làm để tăng nhiệt độ nữa mà để dùng phá vỡ liên kết giữa các phân tử xung quanh<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>$Q=mc\\Delta t=2.380.\\left(1085−30\\right)=801,8\\left(kJ\\right)$","difficultySource":"ai"},"ex":[{"exam":410,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Người ta đun nóng chảy hoàn toàn 2 kg đồng (Copper) từ nhiệt độ ban đầu 300C. Biết đồng có nhiệt độ nóng chảy là 10850C, nhiệt dung riêng là 380 J/kg.K, nhiệt nóng chảy riêng là 1,8.10<sup>5</sup> J/kg.","difficulty":"trung-binh","statements":[{"text":"Khi đang nóng chảy, nhiệt độ của đồng không đổi và bằng 10850C","answer":true},{"text":"Ở nhiệt độ độ nóng chảy, nhiệt lượng cần cung cấp để 2 kg đồng nóng chảy hoàn toàn là 6,3.10<sup>4</sup> J.","answer":false},{"text":"Khi nóng chảy các nguyên tử đồng nhận năng lượng để phá vỡ liên kết với các nguyên tử xung quanh.","answer":true},{"text":"Nhiệt lượng cần cung cấp để nung nóng 2 kg đồng từ nhiệt độ ban đầu đến nhiệt độ nóng chảy là 801,8 kJ.","answer":true}],"explanation":"a) Đúng. Trong suốt quá trình nóng chảy (chuyển thể rắn–lỏng), nhiệt độ của đồng giữ nguyên không đổi và bằng nhiệt độ nóng chảy 1085°C.<br>b) Sai. Nhiệt lượng nóng chảy: Q = λ.m = 1,8.10⁵.2 = 3,6.10⁵ J, không phải 6,3.10⁴ J.<br>c) Đúng. Trong quá trình nóng chảy, năng lượng nhận vào không làm tăng động năng (nhiệt độ không đổi) mà dùng để phá vỡ liên kết giữa các nguyên tử, chuyển từ cấu trúc rắn sang lỏng.<br>d) Đúng. Nhiệt lượng làm nóng đồng từ 30°C lên 1085°C: Q = m.c.Δt = 2.380.(1085−30) = 801800 J = 801,8 kJ.<br>a) đúng<br>Khi đang nóng chảy, nhiệt độ của đồng không đổi và bằng 10850C (áp suất xác định)<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>$Q=2.1,8.10^5=3,6.10^5\\left(J\\right)$<br>c) đúng<br>Lúc này năng lượng nhiệt nhận vào không làm để tăng nhiệt độ nữa mà để dùng phá vỡ liên kết giữa các phân tử xung quanh<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>$Q=mc\\Delta t=2.380.\\left(1085−30\\right)=801,8\\left(kJ\\right)$","difficultySource":"ai"}}]},{"id":672557,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"1,13","question":"Đun 500 g nước đến 1000C thì nước sôi. Biết nước có nhiệt hóa hơi riêng là 2,26.10<sup>6</sup> J/kg. Để hóa hơi hoàn toàn khối nước này ở 1000C thì nhiệt lượng cần cung cấp là x.10<sup>6</sup> J. Giá trị của x là bao nhiêu?","difficulty":"de","explanation":"Công thức: nhiệt lượng cần để hóa hơi hoàn toàn một khối lượng nước ở nhiệt độ sôi Q = m.L, với L là nhiệt hóa hơi riêng.<br>Thay số: m = 500 g = 0,5 kg, L = 2,26.10⁶ J/kg ⇒ Q = 0,5.2,26.10⁶ = 1,13.10⁶ (J).<br>Kết luận: x = 1,13. Đáp số: 1,13.<br>$Q=mL=0,5.2,26.10^6=1,13.10^6\\left(J/kg\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":410,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"1,13","question":"Đun 500 g nước đến 1000C thì nước sôi. Biết nước có nhiệt hóa hơi riêng là 2,26.10<sup>6</sup> J/kg. Để hóa hơi hoàn toàn khối nước này ở 1000C thì nhiệt lượng cần cung cấp là x.10<sup>6</sup> J. Giá trị của x là bao nhiêu?","difficulty":"de","explanation":"Công thức: nhiệt lượng cần để hóa hơi hoàn toàn một khối lượng nước ở nhiệt độ sôi Q = m.L, với L là nhiệt hóa hơi riêng.<br>Thay số: m = 500 g = 0,5 kg, L = 2,26.10⁶ J/kg ⇒ Q = 0,5.2,26.10⁶ = 1,13.10⁶ (J).<br>Kết luận: x = 1,13. Đáp số: 1,13.<br>$Q=mL=0,5.2,26.10^6=1,13.10^6\\left(J/kg\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":672558,"nq":{"form":"bai_tap","type":"short_answer","topic":"Động năng trung bình phân tử và nhiệt độ","answer":"12,4","question":"Vành nhật hoa của mặt trời có nhiệt độ là 6.10<sup>5</sup> K. Lấy hằng số Boltzmann k = 1,38.10<sup>−23</sup> J/mol.K. Động năng tịnh tiến trung bình của mỗi nguyên tử heli trong vùng này là x.10<sup>−18</sup> J. Giá trị của x là bao nhiêu? (kết quả làm tròn đến chữ số hàng phần mười)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046833416-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"Công thức: động năng tịnh tiến trung bình của một phân tử (nguyên tử) khí lí tưởng Wđ = (3/2).k.T.<br>Thay số: k = 1,38.10⁻²³ J/K, T = 6.10⁵ K ⇒ Wđ = 1,5.1,38.10⁻²³.6.10⁵ = 12,42.10⁻¹⁸ (J).<br>Kết luận: làm tròn đến hàng phần mười, x ≈ 12,4. Đáp số: 12,4.<br>$\\overline{E}_d=\\frac{3}{2}kT=1,5.1,38.10^{−23}.6.10^5=12,4.10^{−18}\\left(J\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow x=12,4$","difficultySource":"ai"},"ex":[{"exam":410,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Động năng trung bình phân tử và nhiệt độ","answer":"12,4","question":"Vành nhật hoa của mặt trời có nhiệt độ là 6.10<sup>5</sup> K. Lấy hằng số Boltzmann k = 1,38.10<sup>−23</sup> J/mol.K. Động năng tịnh tiến trung bình của mỗi nguyên tử heli trong vùng này là x.10<sup>−18</sup> J. Giá trị của x là bao nhiêu? (kết quả làm tròn đến chữ số hàng phần mười)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046833416-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"Công thức: động năng tịnh tiến trung bình của một phân tử (nguyên tử) khí lí tưởng Wđ = (3/2).k.T.<br>Thay số: k = 1,38.10⁻²³ J/K, T = 6.10⁵ K ⇒ Wđ = 1,5.1,38.10⁻²³.6.10⁵ = 12,42.10⁻¹⁸ (J).<br>Kết luận: làm tròn đến hàng phần mười, x ≈ 12,4. Đáp số: 12,4.<br>$\\overline{E}_d=\\frac{3}{2}kT=1,5.1,38.10^{−23}.6.10^5=12,4.10^{−18}\\left(J\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow x=12,4$","difficultySource":"ai"}}]},{"id":672583,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"15","question":"Một khối khí được cung cấp nhiệt lượng 4,98 kJ, khi giãn nở làm tăng thể tích một lượng ΔV (dm3). Trong quá trình này, nội năng của khối khí tăng 1,23 kJ nhưng áp suất của khối khí không đổi và p = 2,5.10<sup>5</sup> Pa. Giá trị của ΔV là bao nhiêu dm3?","difficulty":"trung-binh","explanation":"$\\Delta U=A+Q$<br>$\\Rightarrow 1,23=A+4,98$<br>$\\Rightarrow A=−3,75\\left(kJ\\right)$<br>$\\Rightarrow$  Khối khí thực hiện công<br>$\\Rightarrow A^/=p.\\left(v_s−v_t\\right)=3,75\\left(kJ\\right)$<br>$\\Rightarrow \\Delta V=v_s−v_t=\\frac{3,75.10^3}{2,5.10^5}=0,015\\left(m^3\\right)$<br>$\\Rightarrow \\Delta V=15\\left(dm^3\\right)$","difficultySource":"ai"},"ex":[{"exam":411,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"15","question":"Một khối khí được cung cấp nhiệt lượng 4,98 kJ, khi giãn nở làm tăng thể tích một lượng ΔV (dm3). Trong quá trình này, nội năng của khối khí tăng 1,23 kJ nhưng áp suất của khối khí không đổi và p = 2,5.10<sup>5</sup> Pa. Giá trị của ΔV là bao nhiêu dm3?","difficulty":"trung-binh","explanation":"$\\Delta U=A+Q$<br>$\\Rightarrow 1,23=A+4,98$<br>$\\Rightarrow A=−3,75\\left(kJ\\right)$<br>$\\Rightarrow$  Khối khí thực hiện công<br>$\\Rightarrow A^/=p.\\left(v_s−v_t\\right)=3,75\\left(kJ\\right)$<br>$\\Rightarrow \\Delta V=v_s−v_t=\\frac{3,75.10^3}{2,5.10^5}=0,015\\left(m^3\\right)$<br>$\\Rightarrow \\Delta V=15\\left(dm^3\\right)$","difficultySource":"ai"}}]},{"id":672603,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Trong bữa ăn tối một gia đình dùng bếp từ này để chiên một lát thịt sườn khối lượng 250 gam. Giả sử lượng nước trong lát thị chiếm 70% tổng khối lượng. Biết rằng lát thịt chín khi 40% khối lượng nước bay hơi. Hiệu suất của bếp từ là 80%. Công suất điện của bếp là 1200W. Vì nước chứa trong lát thịt có tốc độ bay hơi thấp, nhiệt hóa hơi riêng của nước trong lát thịt ở nhiệt độ bề mặt chảo nóng 300oC là 13,8.10<sup>6</sup> J/kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046868200-hinh-8.webp\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối lượng nước trong lát thịt là 0,25 kg.","answer":false},{"text":"Nhiệt lượng để nấu chín lát thịt là 0,966 MJ.","answer":true},{"text":"Điện năng của bếp cung cấp để nấu chín lát thịt xấp xỉ 1,2 MJ.","answer":true},{"text":"Thời gian để nấu chín lát thịt gần đúng 17 phút.","answer":true}],"explanation":"a) sai<br>Khối lượng nước trong lát thịt là 0,25.0,7 = 0,175 kg.<br>b) đúng<br>Nhiệt lượng nấu chín lát thịt là Q = L.m = 966000 J = 0,966 MJ.<br>c) đúng<br>Điện năng của bếp để nấu chín lát thịt là 0,966 : 0,8 = 1,2 MJ.<br>d) đúng<br>Thời gian nấu  $t=\\frac{A}{P}=\\frac{1.200.000}{1200}≃17$ (phút)<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":412,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Trong bữa ăn tối một gia đình dùng bếp từ này để chiên một lát thịt sườn khối lượng 250 gam. Giả sử lượng nước trong lát thị chiếm 70% tổng khối lượng. Biết rằng lát thịt chín khi 40% khối lượng nước bay hơi. Hiệu suất của bếp từ là 80%. Công suất điện của bếp là 1200W. Vì nước chứa trong lát thịt có tốc độ bay hơi thấp, nhiệt hóa hơi riêng của nước trong lát thịt ở nhiệt độ bề mặt chảo nóng 300oC là 13,8.10<sup>6</sup> J/kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046868200-hinh-8.webp\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối lượng nước trong lát thịt là 0,25 kg.","answer":false},{"text":"Nhiệt lượng để nấu chín lát thịt là 0,966 MJ.","answer":true},{"text":"Điện năng của bếp cung cấp để nấu chín lát thịt xấp xỉ 1,2 MJ.","answer":true},{"text":"Thời gian để nấu chín lát thịt gần đúng 17 phút.","answer":true}],"explanation":"a) sai<br>Khối lượng nước trong lát thịt là 0,25.0,7 = 0,175 kg.<br>b) đúng<br>Nhiệt lượng nấu chín lát thịt là Q = L.m = 966000 J = 0,966 MJ.<br>c) đúng<br>Điện năng của bếp để nấu chín lát thịt là 0,966 : 0,8 = 1,2 MJ.<br>d) đúng<br>Thời gian nấu  $t=\\frac{A}{P}=\\frac{1.200.000}{1200}≃17$ (phút)<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":672655,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Một bình cách nhiệt chứa 500 g nước ở nhiệt độ  $t_0$  = 25 °C. Người ta lần lượt thả vào bình này những quả cầu sắt giống nhau đã được đốt nóng đến 200 °C. Sau khi thả quả cầu thứ nhất thì nhiệt độ của nước trong bình khi xảy ra cân bằng nhiệt là  $t_1$  = 29 °C. Bỏ qua sự trao đổi nhiệt với bình và môi trường, bỏ qua sự bay hơi của nước. Giả thiết nước không bị tràn ra ngoài và lượng nước bị rút vào quả cầu sắt không đáng kể. Cho nhiệt dung riêng của sắt và nước lần lượt là 460 J/(kg.K) và 4 200 J/(kg.K); nhiệt nóng chảy riêng của nước đá là 3,34.10<sup>5</sup> J/kg.","difficulty":"kho","statements":[{"text":"Khối lượng của mỗi quả cầu sắt xấp xỉ bằng 0,1 kg.","answer":true},{"text":"Nếu tiếp tục thả thêm 4 quả cầu sắt nữa thì nhiệt độ của nước khi xảy ra cân bằng nhiệt xấp xỉ bằng 43 C.","answer":true},{"text":"Để nhiệt độ của nước đạt 58 C khi xảy ra cân bằng nhiệt thì cần thả thêm vào bình 10 quả cầu sắt nữa.","answer":false},{"text":"Sau đó, người ta muốn giảm nhiệt độ của nước trong bình xuống còn 40 C nên người ta đã thả tiếp vào bình 200 g nước đá ở 0 C (không lấy quả cầu sắt ra).","answer":false}],"explanation":"a) đúng<br>Khi thả 1 quả cầu sắt vào nước, ta có: $Q_{tỏa}=Q_{thu}$    $m_s.460.\\left(200-29\\right)=0,5.4200.\\left(29-25\\right)$<br>$m_s=\\frac{140}{1311} kg \\approx 106,8 g$ .<br>Vậy khối lượng mỗi quả cầu xấp xỉ bằng 106,8 g.<br>b) đúng<br>Khi thả thêm 4 quả cầu nữa, ta có:  $Q_{tỏa}=Q_{thu}$    $\\left(1+4\\right).\\frac{140}{1311}.460.\\left(200-t_2\\right)=0,5.4200.\\left(t_2-25\\right)$<br>$t_2=\\frac{8275}{191} ℃\\approx 43 ℃$ .<br>Vậy khi thả thêm 4 quả cầu sắt vào nước thì nhiệt độ của nước khi xảy ra cân bằng nhiệt xấp xỉ bằng 43 C.<br>c) sai<br>Để nhiệt độ của nước đạt 58 C khi xảy ra cân bằng nhiệt thì số quả cầu sắt đã thêm vào bình là:<br>$Q_{tỏa}=Q_{thu}$    $n.\\frac{140}{1311}.460.\\left(200-58\\right)=0,5.4200.\\left(58-25\\right)$<br>$n=10$<br>Vậy số quả cầu sắt cần thêm vào bình nữa là  $10-1-4=5$  quả.<br>d) sai<br>Để nhiệt độ của nước trong bình giảm xuống còn 50 C thì lượng nước đá ở 0 C cần thêm vào là:<br>$Q_{tỏa}=Q_{thu}$    $10.\\frac{140}{1311}.460.\\left(58-40\\right)+0,5.4200.\\left(58-40\\right)=m_n.3,34.{10}^5+m_n.4200.\\left(40-0\\right)$<br>$m_n=\\frac{4431}{47690} kg \\approx 0,093 kg$ .","difficultySource":"ai"},"ex":[{"exam":414,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Một bình cách nhiệt chứa 500 g nước ở nhiệt độ  $t_0$  = 25 °C. Người ta lần lượt thả vào bình này những quả cầu sắt giống nhau đã được đốt nóng đến 200 °C. Sau khi thả quả cầu thứ nhất thì nhiệt độ của nước trong bình khi xảy ra cân bằng nhiệt là  $t_1$  = 29 °C. Bỏ qua sự trao đổi nhiệt với bình và môi trường, bỏ qua sự bay hơi của nước. Giả thiết nước không bị tràn ra ngoài và lượng nước bị rút vào quả cầu sắt không đáng kể. Cho nhiệt dung riêng của sắt và nước lần lượt là 460 J/(kg.K) và 4 200 J/(kg.K); nhiệt nóng chảy riêng của nước đá là 3,34.10<sup>5</sup> J/kg.","difficulty":"kho","statements":[{"text":"Khối lượng của mỗi quả cầu sắt xấp xỉ bằng 0,1 kg.","answer":true},{"text":"Nếu tiếp tục thả thêm 4 quả cầu sắt nữa thì nhiệt độ của nước khi xảy ra cân bằng nhiệt xấp xỉ bằng 43 C.","answer":true},{"text":"Để nhiệt độ của nước đạt 58 C khi xảy ra cân bằng nhiệt thì cần thả thêm vào bình 10 quả cầu sắt nữa.","answer":false},{"text":"Sau đó, người ta muốn giảm nhiệt độ của nước trong bình xuống còn 40 C nên người ta đã thả tiếp vào bình 200 g nước đá ở 0 C (không lấy quả cầu sắt ra).","answer":false}],"explanation":"a) đúng<br>Khi thả 1 quả cầu sắt vào nước, ta có: $Q_{tỏa}=Q_{thu}$    $m_s.460.\\left(200-29\\right)=0,5.4200.\\left(29-25\\right)$<br>$m_s=\\frac{140}{1311} kg \\approx 106,8 g$ .<br>Vậy khối lượng mỗi quả cầu xấp xỉ bằng 106,8 g.<br>b) đúng<br>Khi thả thêm 4 quả cầu nữa, ta có:  $Q_{tỏa}=Q_{thu}$    $\\left(1+4\\right).\\frac{140}{1311}.460.\\left(200-t_2\\right)=0,5.4200.\\left(t_2-25\\right)$<br>$t_2=\\frac{8275}{191} ℃\\approx 43 ℃$ .<br>Vậy khi thả thêm 4 quả cầu sắt vào nước thì nhiệt độ của nước khi xảy ra cân bằng nhiệt xấp xỉ bằng 43 C.<br>c) sai<br>Để nhiệt độ của nước đạt 58 C khi xảy ra cân bằng nhiệt thì số quả cầu sắt đã thêm vào bình là:<br>$Q_{tỏa}=Q_{thu}$    $n.\\frac{140}{1311}.460.\\left(200-58\\right)=0,5.4200.\\left(58-25\\right)$<br>$n=10$<br>Vậy số quả cầu sắt cần thêm vào bình nữa là  $10-1-4=5$  quả.<br>d) sai<br>Để nhiệt độ của nước trong bình giảm xuống còn 50 C thì lượng nước đá ở 0 C cần thêm vào là:<br>$Q_{tỏa}=Q_{thu}$    $10.\\frac{140}{1311}.460.\\left(58-40\\right)+0,5.4200.\\left(58-40\\right)=m_n.3,34.{10}^5+m_n.4200.\\left(40-0\\right)$<br>$m_n=\\frac{4431}{47690} kg \\approx 0,093 kg$ .","difficultySource":"ai"}}]},{"id":672680,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":0,"options":["0,23.106 J.","2,3.10<sup>6</sup> J.","23.106 J.","2,3.10<sup>6</sup> J."],"question":"Biệt nhiệt hoá hơi riêng của nước là L = 2,3.10<sup>6</sup> J/Kg. Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 100g nước ở 1000C là","difficulty":"de","explanation":"$Q=mL=0,1.2,3.10^6=2,3.10^5\\left(J\\right) Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":415,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":0,"options":["0,23.106 J.","2,3.10<sup>6</sup> J.","23.106 J.","2,3.10<sup>6</sup> J."],"question":"Biệt nhiệt hoá hơi riêng của nước là L = 2,3.10<sup>6</sup> J/Kg. Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 100g nước ở 1000C là","difficulty":"de","explanation":"$Q=mL=0,1.2,3.10^6=2,3.10^5\\left(J\\right) Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":672686,"nq":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Ngày 26 tháng 10 năm 2024 đã diễn ra lễ hội khinh khí cầu Tràng An – Cúc Phương năm 2024 tại Ninh Bình. Một khí cầu có thể tích V = 336 m3 và khối lượng vỏ m = 82 kg được bơm không khí nóng tới áp suất bằng áp suất không khí bên ngoài. Biết không khí bên ngoài có nhiệt độ 300C và áp suất 1 atm (1 atm = 101325 Pa) ; khối lượng mol của không khí ở điều kiện chuẩn là 29.10<sup>−3</sup>kg/mol<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046900694-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nhiệt độ của không khí bên ngoài khí cầu là 303 K.","answer":true},{"text":"Cho rằng lực của gió không đáng kể lực chính đẩy khí cầu bay lên là lực Archimedes (Ắc- xi- mét) tác dụng vào khí cầu.","answer":true},{"text":"Cho rằng lực của gió không đáng kể để khí cầu bắt đầu bay lên thì nhiệt độ không khí nóng bên trong khí cầu là 368 K.","answer":false},{"text":"Khối lượng riêng của không khí ở nhiệt độ 300C và áp suất 1atm là 1,17 g/l.","answer":true}],"explanation":"Khối lượng mol là không đổi dù nhiệt độ có khác đi. Khi ta thay đổi nhiệt đô → chỉ làm thay đổi khối lượng riêng.<br>a) đúng<br>$\\begin{aligned}t\\left(K\\right)=t\\left({}^0C\\right)+273=30+273=303K <br>Website: thukhoadaihoc.vn\\end{aligned}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>Cho rằng lực của gió không đáng kể lực chính đẩy khí cầu bay lên là lực Archimedes (Ắc- xi- mét) tác dụng vào khí cầu<br>→ Lúc này Lực Acsimet thắng được trọng lượng của vỏ khinh khí cầu và thắng được trọng lượng của khối lượng khí bên trong và đẩy khinh khí cầu lên<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) sai<br>Tính ý d trước, sau mới tính ý C (tính khối lượng riêng thì mới tính được lực đẩy Acsimet.<br>Lực đẩy Acsimet:  $F_A=\\delta .V.g$<br>Để bay lên  $F_A=P_{cau}+P_{khi}$<br>$\\Rightarrow \\delta .V.g=m.g+m_K.g$<br>$\\Rightarrow 1,17.336=82+m_k$<br>$\\Rightarrow m_k=311,12\\left(kg\\right)$  (khối lượng khí bên trong quả cầu)<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow pV=nRT\\Rightarrow 101325.336=\\frac{311,12}{29.10^{−3}}.8,31.T Website: thukhoadaihoc.vn$<br>$\\Rightarrow T=381,88K$<br>d) đúng<br>$pV=nRT\\Rightarrow 101325.V=\\frac{m}{29.10^{−3}}.8,31.303$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}\\delta =\\frac{m}{V}=\\frac{101325.29.10^{−3}}{8,31.303}=1,167\\left(kg/m^3\\right)\\approx 1,17\\left(g/lit\\right) Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":415,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Ngày 26 tháng 10 năm 2024 đã diễn ra lễ hội khinh khí cầu Tràng An – Cúc Phương năm 2024 tại Ninh Bình. Một khí cầu có thể tích V = 336 m3 và khối lượng vỏ m = 82 kg được bơm không khí nóng tới áp suất bằng áp suất không khí bên ngoài. Biết không khí bên ngoài có nhiệt độ 300C và áp suất 1 atm (1 atm = 101325 Pa) ; khối lượng mol của không khí ở điều kiện chuẩn là 29.10<sup>−3</sup>kg/mol<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046900694-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nhiệt độ của không khí bên ngoài khí cầu là 303 K.","answer":true},{"text":"Cho rằng lực của gió không đáng kể lực chính đẩy khí cầu bay lên là lực Archimedes (Ắc- xi- mét) tác dụng vào khí cầu.","answer":true},{"text":"Cho rằng lực của gió không đáng kể để khí cầu bắt đầu bay lên thì nhiệt độ không khí nóng bên trong khí cầu là 368 K.","answer":false},{"text":"Khối lượng riêng của không khí ở nhiệt độ 300C và áp suất 1atm là 1,17 g/l.","answer":true}],"explanation":"Khối lượng mol là không đổi dù nhiệt độ có khác đi. Khi ta thay đổi nhiệt đô → chỉ làm thay đổi khối lượng riêng.<br>a) đúng<br>$\\begin{aligned}t\\left(K\\right)=t\\left({}^0C\\right)+273=30+273=303K <br>Website: thukhoadaihoc.vn\\end{aligned}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>Cho rằng lực của gió không đáng kể lực chính đẩy khí cầu bay lên là lực Archimedes (Ắc- xi- mét) tác dụng vào khí cầu<br>→ Lúc này Lực Acsimet thắng được trọng lượng của vỏ khinh khí cầu và thắng được trọng lượng của khối lượng khí bên trong và đẩy khinh khí cầu lên<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) sai<br>Tính ý d trước, sau mới tính ý C (tính khối lượng riêng thì mới tính được lực đẩy Acsimet.<br>Lực đẩy Acsimet:  $F_A=\\delta .V.g$<br>Để bay lên  $F_A=P_{cau}+P_{khi}$<br>$\\Rightarrow \\delta .V.g=m.g+m_K.g$<br>$\\Rightarrow 1,17.336=82+m_k$<br>$\\Rightarrow m_k=311,12\\left(kg\\right)$  (khối lượng khí bên trong quả cầu)<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow pV=nRT\\Rightarrow 101325.336=\\frac{311,12}{29.10^{−3}}.8,31.T Website: thukhoadaihoc.vn$<br>$\\Rightarrow T=381,88K$<br>d) đúng<br>$pV=nRT\\Rightarrow 101325.V=\\frac{m}{29.10^{−3}}.8,31.303$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}\\delta =\\frac{m}{V}=\\frac{101325.29.10^{−3}}{8,31.303}=1,167\\left(kg/m^3\\right)\\approx 1,17\\left(g/lit\\right) Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":672687,"nq":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"2,41","question":"Khi thở ra, dung tích của phổi là 2,400 lít và áp suất của không khí trong phổi là 101,70.10<sup>3</sup> Pa. Cho biết khi hít vào, áp suất này trở thành 101,12.10<sup>3</sup> Pa. Dung tích của phổi khi hít vào là bao nhiêu lít? (kết quả lấy 2 chữ số sau dấu phẩy thập phân)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046900862-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"Ta có:  $\\left\\{\\begin{aligned}V_1=2,400lit <br>p_1=101,70.10^3Pa <br>V_2=101,12.10^3Pa <br>p_2=?\\end{aligned}\\right.$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Hít vào → thở ra → Coi như đẳng nhiệt.<br>$\\Rightarrow p_1V_1=p_2V_2$<br>$\\Rightarrow 101,7.10^3.2,4=101,12.10^3.V_2$<br>$\\Rightarrow V_2=2,41\\left(lit\\right)$","difficultySource":"ai"},"ex":[{"exam":415,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"2,41","question":"Khi thở ra, dung tích của phổi là 2,400 lít và áp suất của không khí trong phổi là 101,70.10<sup>3</sup> Pa. Cho biết khi hít vào, áp suất này trở thành 101,12.10<sup>3</sup> Pa. Dung tích của phổi khi hít vào là bao nhiêu lít? (kết quả lấy 2 chữ số sau dấu phẩy thập phân)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046900862-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"Ta có:  $\\left\\{\\begin{aligned}V_1=2,400lit <br>p_1=101,70.10^3Pa <br>V_2=101,12.10^3Pa <br>p_2=?\\end{aligned}\\right.$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Hít vào → thở ra → Coi như đẳng nhiệt.<br>$\\Rightarrow p_1V_1=p_2V_2$<br>$\\Rightarrow 101,7.10^3.2,4=101,12.10^3.V_2$<br>$\\Rightarrow V_2=2,41\\left(lit\\right)$","difficultySource":"ai"}}]},{"id":672688,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"0,22","question":"Vào mùa hè, người Hà Nội thường có thói quen thưởng thức trà đá trong các quán vỉa hè. Để có một cốc trà đá chất lượng, người chủ quán rót khoảng 0,250 kg trà nóng ở 80,00C vào cốc, sau đó cho tiếp m kg nước đá 00C. Cuối cùng được cốc trà đá ở nhiệt độ phù hợp nhất là 10,00C (hệ vừa đạt đến trạng thái cân bằng nhiệt). Biết phần nhiệt lượng mà hệ (nước và nước đá) nhận thêm của môi trường xung quanh bằng 10% nhiệt lượng mà các cục nước đá nhận để làm tăng nội năng của chúng. Nhiệt dung riêng của nước là 4,20 kJ/kg0C; nhiệt nóng chảy của nước đá là 3,33.10<sup>5</sup> J/Kg. Tính m (Theo đơn vị kg. Lấy 2 chữ số ở phần thập phân).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046901117-hinh-15.png\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"$Q_{thu}=m\\lambda +m.c.\\Delta t$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow Q_{thu}=m.\\left(3,33.10^5+4200.10\\right)=375000m Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q_{toa}=m^/.c.\\Delta t+10%Q_{thu}$<br>$\\Rightarrow Q_{thu}=0,25.4200.70+0,1.\\left(375000m\\right)=73500+37500m$<br>$Q_{thu}=Q_{toa}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow 375000m=73500+37500m$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow m=0,2178\\left(kg\\right)\\approx 0,222\\left(kg\\right) Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":415,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"0,22","question":"Vào mùa hè, người Hà Nội thường có thói quen thưởng thức trà đá trong các quán vỉa hè. Để có một cốc trà đá chất lượng, người chủ quán rót khoảng 0,250 kg trà nóng ở 80,00C vào cốc, sau đó cho tiếp m kg nước đá 00C. Cuối cùng được cốc trà đá ở nhiệt độ phù hợp nhất là 10,00C (hệ vừa đạt đến trạng thái cân bằng nhiệt). Biết phần nhiệt lượng mà hệ (nước và nước đá) nhận thêm của môi trường xung quanh bằng 10% nhiệt lượng mà các cục nước đá nhận để làm tăng nội năng của chúng. Nhiệt dung riêng của nước là 4,20 kJ/kg0C; nhiệt nóng chảy của nước đá là 3,33.10<sup>5</sup> J/Kg. Tính m (Theo đơn vị kg. Lấy 2 chữ số ở phần thập phân).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046901117-hinh-15.png\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"$Q_{thu}=m\\lambda +m.c.\\Delta t$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow Q_{thu}=m.\\left(3,33.10^5+4200.10\\right)=375000m Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q_{toa}=m^/.c.\\Delta t+10%Q_{thu}$<br>$\\Rightarrow Q_{thu}=0,25.4200.70+0,1.\\left(375000m\\right)=73500+37500m$<br>$Q_{thu}=Q_{toa}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow 375000m=73500+37500m$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow m=0,2178\\left(kg\\right)\\approx 0,222\\left(kg\\right) Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":672691,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"3,1","question":"Một bình đựng 2,5 g khí hêli có thể tích 5 lít và nhiệt độ ở 270C. Áp suất khí trong bình là x.10<sup>5</sup> (N/m2). Giá trị của x bằng bao nhiêu? (kết quả lấy 1 chữ số sau dấu phẩy thập phân).","difficulty":"trung-binh","explanation":"$n=\\frac{m}{M}=\\frac{2,5}{4}$<br>$pV=nRT$<br>$\\Rightarrow p.5.10^{−3}=\\frac{2,5}{4}.8,31.\\left(27+273\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow p=3,1.10^5\\left(N/m^2\\right)$","difficultySource":"ai"},"ex":[{"exam":415,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"3,1","question":"Một bình đựng 2,5 g khí hêli có thể tích 5 lít và nhiệt độ ở 270C. Áp suất khí trong bình là x.10<sup>5</sup> (N/m2). Giá trị của x bằng bao nhiêu? (kết quả lấy 1 chữ số sau dấu phẩy thập phân).","difficulty":"trung-binh","explanation":"$n=\\frac{m}{M}=\\frac{2,5}{4}$<br>$pV=nRT$<br>$\\Rightarrow p.5.10^{−3}=\\frac{2,5}{4}.8,31.\\left(27+273\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow p=3,1.10^5\\left(N/m^2\\right)$","difficultySource":"ai"}}]},{"id":672710,"nq":{"form":"bai_tap","type":"true_false","topic":"Lực từ. Cảm ứng từ","question":"Trong máy quang phổ khối (Mass Spectrometry), một ion đơn tích (q = +e), có khối lượng m = 3,2×10<sup>−26</sup> kg, được tăng tốc bởi hiệu điện thế U=200 V trước khi bay vào vùng từ trường đều B=0,5 T. Trong vùng từ trường, ion chuyển động theo quỹ đạo tròn. Cho biết điện tích của e = 1,6×10<sup>−19</sup> C.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046909091-hinh-9.webp\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Điện tích của ion là điện tích dương.","answer":true},{"text":"Bán kính quỹ đạo của ion trong từ trường này là 10 cm.","answer":false},{"text":"Chu kỳ chuyển động của ion trong từ trường xấp xỉ π (μs).","answer":false},{"text":"Nếu có một ion khác với khối lượng m′=6,4×10<sup>−26</sup> kg nhưng cùng điện tích q=+e thì bán kính quỹ đạo của ion này xấp xỉ là 1,27 cm.","answer":true}],"explanation":"a) đúng<br>Điện tích của ion là dương, q = 1,6.10<sup>−19</sup> C.<br>b) sai<br>Ta áp dụng công thức:   $\\frac{1}{2}mv^2=qU\\Rightarrow v=\\sqrt{\\frac{2qU}{m}}=\\sqrt{\\frac{2\\cdot 1,6\\times 10^{−19}\\cdot 200}{3,2\\times 10^{−26}}}=\\sqrt2\\times 10^5(m/s)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Bán kính  $r=\\frac{mv}{qB}=\\frac{3,2\\times 10^{26}\\cdot \\sqrt2\\times 10^5}{1,6\\times 10^{−19}\\cdot 0,5}=\\approx 0,0564(m)=5,64(cm)$<br>c) sai<br>Chu kỳ chuyển động của ion trong từ trường  $T=\\frac{2\\pi m}{qB}=\\frac{2\\pi \\cdot (3,2\\times 10^{−26})}{(1,6\\times 10^{−19})\\cdot 0,5}\\approx 3,14\\times 10^{−7}(s)$<br>d) đúng<br>Tốc độ của ion mới:  $\\frac{1}{2}mv^2=qU\\Rightarrow v=\\sqrt{\\frac{2qU}{m'}}=\\sqrt{\\frac{2\\cdot 1,6\\times 10^{−19}\\cdot 200}{6,4\\times 10^{−26}}}=\\sqrt{10^9}(m/s)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Bán kính  $r'=\\frac{mv'}{qB}=\\frac{3,2\\times 10^{−26}\\cdot \\sqrt{10^9}}{1,6\\times 10^{−19}\\cdot 0,5}\\approx 0,0127(m)=1,27(cm)$","difficultySource":"ai"},"ex":[{"exam":416,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Lực từ. Cảm ứng từ","question":"Trong máy quang phổ khối (Mass Spectrometry), một ion đơn tích (q = +e), có khối lượng m = 3,2×10<sup>−26</sup> kg, được tăng tốc bởi hiệu điện thế U=200 V trước khi bay vào vùng từ trường đều B=0,5 T. Trong vùng từ trường, ion chuyển động theo quỹ đạo tròn. Cho biết điện tích của e = 1,6×10<sup>−19</sup> C.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046909091-hinh-9.webp\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Điện tích của ion là điện tích dương.","answer":true},{"text":"Bán kính quỹ đạo của ion trong từ trường này là 10 cm.","answer":false},{"text":"Chu kỳ chuyển động của ion trong từ trường xấp xỉ π (μs).","answer":false},{"text":"Nếu có một ion khác với khối lượng m′=6,4×10<sup>−26</sup> kg nhưng cùng điện tích q=+e thì bán kính quỹ đạo của ion này xấp xỉ là 1,27 cm.","answer":true}],"explanation":"a) đúng<br>Điện tích của ion là dương, q = 1,6.10<sup>−19</sup> C.<br>b) sai<br>Ta áp dụng công thức:   $\\frac{1}{2}mv^2=qU\\Rightarrow v=\\sqrt{\\frac{2qU}{m}}=\\sqrt{\\frac{2\\cdot 1,6\\times 10^{−19}\\cdot 200}{3,2\\times 10^{−26}}}=\\sqrt2\\times 10^5(m/s)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Bán kính  $r=\\frac{mv}{qB}=\\frac{3,2\\times 10^{26}\\cdot \\sqrt2\\times 10^5}{1,6\\times 10^{−19}\\cdot 0,5}=\\approx 0,0564(m)=5,64(cm)$<br>c) sai<br>Chu kỳ chuyển động của ion trong từ trường  $T=\\frac{2\\pi m}{qB}=\\frac{2\\pi \\cdot (3,2\\times 10^{−26})}{(1,6\\times 10^{−19})\\cdot 0,5}\\approx 3,14\\times 10^{−7}(s)$<br>d) đúng<br>Tốc độ của ion mới:  $\\frac{1}{2}mv^2=qU\\Rightarrow v=\\sqrt{\\frac{2qU}{m'}}=\\sqrt{\\frac{2\\cdot 1,6\\times 10^{−19}\\cdot 200}{6,4\\times 10^{−26}}}=\\sqrt{10^9}(m/s)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Bán kính  $r'=\\frac{mv'}{qB}=\\frac{3,2\\times 10^{−26}\\cdot \\sqrt{10^9}}{1,6\\times 10^{−19}\\cdot 0,5}\\approx 0,0127(m)=1,27(cm)$","difficultySource":"ai"}}]},{"id":672712,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Nguồn phóng xạ α americium  ${}_{95}^{241}Am$  có hằng số phóng xạ 5,081.10<sup>−11</sup> (1/s) được đặt giữa hai bản kim loại kết nối với một pin. Các hạt α phóng ra làm ion hóa không khí giữa hai bản kim loại, cho phép một dòng điện nhỏ chạy giữa hai bản kim loại đó và chuông báo không kêu. Nếu có khói bay vào giữa hai bản kim loại, các ion trong này sẽ kết hợp với những phân tử khói và dịch chuyển chậm hơn làm cường độ dòng điện chạy giữa hai bản kim loại giảm đi. Khi dòng điện giảm tới mức nhất định thì cảm biến báo khói sẽ gửi tín hiệu kích hoạt chuông báo cháy.","difficulty":"kho","statements":[{"text":"Tia α phát ra từ nguồn phóng xạ bị lệch về phía bản kim loại nhiễm điện dương.","answer":false},{"text":"Chu kì bán rã của americium  ${}_{95}^{241}Am$  là 1,58.10<sup>5</sup> ngày.","answer":true},{"text":"Độ phóng xạ của nguồn americium  ${}_{95}^{241}Am$  có khối lượng 0,125 μg là 25,7 kBq.","answer":false},{"text":"Sau khi sử dụng 15 năm, độ phóng xạ của nguồn americium  ${}_{95}^{241}Am$  trong cảm biến giảm còn 3,47% so với độ phóng xạ ban đâu lúc mới mua.","answer":false}],"explanation":"a) sai<br>Tia α mang điện tích dương nên bị lệch về phía bản kim loại nhiễm điện âm.<br>b) đúng<br>$T=\\frac{ln2}{\\lambda }=1,58.10^5$ ngày .<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) sai<br>$H_0=\\lambda .N_0=15,9.10^3Bq$<br>d) sai<br>$H=H_0.e^{−\\lambda t}=97,6%H_0$","difficultySource":"ai"},"ex":[{"exam":416,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Nguồn phóng xạ α americium  ${}_{95}^{241}Am$  có hằng số phóng xạ 5,081.10<sup>−11</sup> (1/s) được đặt giữa hai bản kim loại kết nối với một pin. Các hạt α phóng ra làm ion hóa không khí giữa hai bản kim loại, cho phép một dòng điện nhỏ chạy giữa hai bản kim loại đó và chuông báo không kêu. Nếu có khói bay vào giữa hai bản kim loại, các ion trong này sẽ kết hợp với những phân tử khói và dịch chuyển chậm hơn làm cường độ dòng điện chạy giữa hai bản kim loại giảm đi. Khi dòng điện giảm tới mức nhất định thì cảm biến báo khói sẽ gửi tín hiệu kích hoạt chuông báo cháy.","difficulty":"kho","statements":[{"text":"Tia α phát ra từ nguồn phóng xạ bị lệch về phía bản kim loại nhiễm điện dương.","answer":false},{"text":"Chu kì bán rã của americium  ${}_{95}^{241}Am$  là 1,58.10<sup>5</sup> ngày.","answer":true},{"text":"Độ phóng xạ của nguồn americium  ${}_{95}^{241}Am$  có khối lượng 0,125 μg là 25,7 kBq.","answer":false},{"text":"Sau khi sử dụng 15 năm, độ phóng xạ của nguồn americium  ${}_{95}^{241}Am$  trong cảm biến giảm còn 3,47% so với độ phóng xạ ban đâu lúc mới mua.","answer":false}],"explanation":"a) sai<br>Tia α mang điện tích dương nên bị lệch về phía bản kim loại nhiễm điện âm.<br>b) đúng<br>$T=\\frac{ln2}{\\lambda }=1,58.10^5$ ngày .<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) sai<br>$H_0=\\lambda .N_0=15,9.10^3Bq$<br>d) sai<br>$H=H_0.e^{−\\lambda t}=97,6%H_0$","difficultySource":"ai"}}]},{"id":672715,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"2,5","question":"Giả sử tại vị trí khảo sát, từ trường Trái Đất là 5.10<sup>−5</sup> T. Xét một đoạn dây dẫn có chiều dài 500 m tại đoạn có dòng điện xoay chiều cực đại 100A xem như vuông góc với từ trường của Trái Đất, thì tổng lực từ cực đại do từ trường Trái Đất tác dụng lên toàn bộ chiều dài dây dẫn là bao nhiêu Newton? (Làm tròn kết quả đến chữ số hàng đơn vị).","difficulty":"de","explanation":"Lực từ cực đại tác dụng lên mỗi mét chiều dài của dây dẫn được tính bằng công thức:<br>$F=B.I.L.sin\\theta =5.10^{−5}.100.500.sin90^0=2,5(N)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":416,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"2,5","question":"Giả sử tại vị trí khảo sát, từ trường Trái Đất là 5.10<sup>−5</sup> T. Xét một đoạn dây dẫn có chiều dài 500 m tại đoạn có dòng điện xoay chiều cực đại 100A xem như vuông góc với từ trường của Trái Đất, thì tổng lực từ cực đại do từ trường Trái Đất tác dụng lên toàn bộ chiều dài dây dẫn là bao nhiêu Newton? (Làm tròn kết quả đến chữ số hàng đơn vị).","difficulty":"de","explanation":"Lực từ cực đại tác dụng lên mỗi mét chiều dài của dây dẫn được tính bằng công thức:<br>$F=B.I.L.sin\\theta =5.10^{−5}.100.500.sin90^0=2,5(N)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":672718,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"46,4","question":"Một nhà máy điện hạt nhân có công suất phát điện 2000 MW, dùng năng lượng phân hạch của hạt nhân  ${}_{92}^{235}U$  với hiệu suất 30%. Lấy mỗi năm có 365 ngày; mỗi phân hạch sinh ra năng lượng khoảng 200 MeV. Cho biết số Avogadro là NA = 6,02.10<sup>23</sup> (hạt/mol). Khối lượng  ${}_{92}^{235}U$  mà nhà máy điện hạt nhân tiêu thụ mỗi năm là bao nhiêu tấn (làm tròn một chữ số thập phân)?","difficulty":"kho","explanation":"Năng lượng có ích:  $A_i=2000.10^6.365.86400=6,3072.10^{16}J$ .<br>Vì hiệu suất nhà máy là 30% nên năng lượng toàn phần cần sử dụng trong một năm là:<br>$A_{tp}=\\frac{A_i}{0,3}=2,1024.10^{17}J$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Số hạt  ${}_{92}^{235}U$  cần dùng:  $N=\\frac{A_{tp}}{200.1,6.10^{−13}}=6,57.10^{27}$ (hạt).<br>Khối lượng <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224537644-hinh-11.png\" alt=\"Hình 11\" class=\"eq\" style=\"width:39px;height:25.5px\" /> cần dùng:  $m=\\frac{N}{N_A.A_U}=\\frac{6,57.10^{27}}{6,02.10^{23}.235}=46,44(g)$ .","difficultySource":"ai"},"ex":[{"exam":416,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"46,4","question":"Một nhà máy điện hạt nhân có công suất phát điện 2000 MW, dùng năng lượng phân hạch của hạt nhân  ${}_{92}^{235}U$  với hiệu suất 30%. Lấy mỗi năm có 365 ngày; mỗi phân hạch sinh ra năng lượng khoảng 200 MeV. Cho biết số Avogadro là NA = 6,02.10<sup>23</sup> (hạt/mol). Khối lượng  ${}_{92}^{235}U$  mà nhà máy điện hạt nhân tiêu thụ mỗi năm là bao nhiêu tấn (làm tròn một chữ số thập phân)?","difficulty":"kho","explanation":"Năng lượng có ích:  $A_i=2000.10^6.365.86400=6,3072.10^{16}J$ .<br>Vì hiệu suất nhà máy là 30% nên năng lượng toàn phần cần sử dụng trong một năm là:<br>$A_{tp}=\\frac{A_i}{0,3}=2,1024.10^{17}J$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Số hạt  ${}_{92}^{235}U$  cần dùng:  $N=\\frac{A_{tp}}{200.1,6.10^{−13}}=6,57.10^{27}$ (hạt).<br>Khối lượng <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224537644-hinh-11.png\" alt=\"Hình 11\" class=\"eq\" style=\"width:39px;height:25.5px\" /> cần dùng:  $m=\\frac{N}{N_A.A_U}=\\frac{6,57.10^{27}}{6,02.10^{23}.235}=46,44(g)$ .","difficultySource":"ai"}}]},{"id":672726,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":0,"options":["7,83.10<sup>12</sup> J.","7,83.10<sup>9</sup> MeV.","7,83.10<sup>9</sup> J.","7,83.10<sup>12</sup> MeV."],"question":"Xét phản ứng nhiệt hạch:  ${}_1^2H+_1^2H\\rightarrow_2^4He+3,25MeV$ . Nếu quá trình nhiệt hạch sử dụng hết 100 g  ${}_1^2H$ thì tổng năng lượng tỏa ra là bao nhiêu? Biết khối lượng mol của  ${}_1^2H$  là 2 g/mol và NA = 6,02.10<sup>23</sup> mol-1.","difficulty":"kho","explanation":"Tổng năng lượng = Số phản ứng x  Năng lượng toả ra của 1 phản ứng  $\\Rightarrow =∑N_{pu}.\\Delta E$<br>1 phản ứng tốn 2 hạt  ${}_1^2H$   $\\Rightarrow N_{pu}=\\frac{N_{H_2}}{2}$<br>$N_{H_2}=n_{H_2}.N_A=\\frac{m}{M}.N_A=\\frac{100}{2}.6,02.10^{23}$   ${}_{}^{}$<br>$\\Rightarrow N_{pu}=\\frac{N_{H_2}}{2}=\\frac{100}{4}.6,02.10^{23}$<br>$\\Rightarrow E=\\frac{100}{4}.6,02.10^{23}.3,25=4,89.10^{25}\\left(MeV\\right)$<br>$1J=1,6.10^{−19}eV\\Rightarrow E\\left(J\\right)=4,89.10^{25}.10^6.10^{−19}.1,6=7,824.10^{12}J$","difficultySource":"ai"},"ex":[{"exam":417,"idx":7,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":0,"options":["7,83.10<sup>12</sup> J.","7,83.10<sup>9</sup> MeV.","7,83.10<sup>9</sup> J.","7,83.10<sup>12</sup> MeV."],"question":"Xét phản ứng nhiệt hạch:  ${}_1^2H+_1^2H\\rightarrow_2^4He+3,25MeV$ . Nếu quá trình nhiệt hạch sử dụng hết 100 g  ${}_1^2H$ thì tổng năng lượng tỏa ra là bao nhiêu? Biết khối lượng mol của  ${}_1^2H$  là 2 g/mol và NA = 6,02.10<sup>23</sup> mol-1.","difficulty":"kho","explanation":"Tổng năng lượng = Số phản ứng x  Năng lượng toả ra của 1 phản ứng  $\\Rightarrow =∑N_{pu}.\\Delta E$<br>1 phản ứng tốn 2 hạt  ${}_1^2H$   $\\Rightarrow N_{pu}=\\frac{N_{H_2}}{2}$<br>$N_{H_2}=n_{H_2}.N_A=\\frac{m}{M}.N_A=\\frac{100}{2}.6,02.10^{23}$   ${}_{}^{}$<br>$\\Rightarrow N_{pu}=\\frac{N_{H_2}}{2}=\\frac{100}{4}.6,02.10^{23}$<br>$\\Rightarrow E=\\frac{100}{4}.6,02.10^{23}.3,25=4,89.10^{25}\\left(MeV\\right)$<br>$1J=1,6.10^{−19}eV\\Rightarrow E\\left(J\\right)=4,89.10^{25}.10^6.10^{−19}.1,6=7,824.10^{12}J$","difficultySource":"ai"}}]},{"id":672728,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt độ và cân bằng nhiệt","answer":1,"options":["2200C","2750C","3270C","3070C"],"question":"Một miếng đồng có khối lượng 2 kg ở nhiệt độ t0(C) và 1,5 kg nước đá ở -150C được đặt vào bình cách nhiệt có khối lượng không đáng kể. Sau khi đạt cân bằng nhiệt, trong bình có 0,5 kg nước. Biết nhiệt dung riêng của nước đá là 2100 J/(kg.K), của đồng là 390 J/(kg.K) và nhiệt nóng chảy riêng của nước đá là 3,34.10<sup>5</sup> J/kg. Nhiệt độ ban đầu của miếng đồng gần nhất với giá trị nào sau đây?","difficulty":"kho","explanation":"Đá chưa tan hết  $\\Rightarrow$  Nhiệt độ cân bằng  $t_{CB}=0^0C$<br>$Q_{toa}=Q_{thu}\\Rightarrow Q_{Cu}=Q\\left(−15−0\\right)+Q_{nong chay}$<br>$\\Rightarrow 2.390.\\left(t_{cu}\\right)=1,5.2100.\\left(0+15\\right)+0,5.3,34.10^5$<br>$\\Rightarrow t_{cu}\\approx 274,69^0C$","difficultySource":"ai"},"ex":[{"exam":417,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt độ và cân bằng nhiệt","answer":1,"options":["2200C","2750C","3270C","3070C"],"question":"Một miếng đồng có khối lượng 2 kg ở nhiệt độ t0(C) và 1,5 kg nước đá ở -150C được đặt vào bình cách nhiệt có khối lượng không đáng kể. Sau khi đạt cân bằng nhiệt, trong bình có 0,5 kg nước. Biết nhiệt dung riêng của nước đá là 2100 J/(kg.K), của đồng là 390 J/(kg.K) và nhiệt nóng chảy riêng của nước đá là 3,34.10<sup>5</sup> J/kg. Nhiệt độ ban đầu của miếng đồng gần nhất với giá trị nào sau đây?","difficulty":"kho","explanation":"Đá chưa tan hết  $\\Rightarrow$  Nhiệt độ cân bằng  $t_{CB}=0^0C$<br>$Q_{toa}=Q_{thu}\\Rightarrow Q_{Cu}=Q\\left(−15−0\\right)+Q_{nong chay}$<br>$\\Rightarrow 2.390.\\left(t_{cu}\\right)=1,5.2100.\\left(0+15\\right)+0,5.3,34.10^5$<br>$\\Rightarrow t_{cu}\\approx 274,69^0C$","difficultySource":"ai"}}]},{"id":672729,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["334 kJ.","33,4 kJ.","33,4 J.","33,4 MJ."],"question":"Nhiệt nóng chảy riêng của nước đá bằng 3,34.10<sup>5</sup> J/kg, nhiệt lượng cần thiết để làm nóng chảy hoàn toàn 100 g nước đá ở nhiệt độ nóng chảy là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần để làm nóng chảy hoàn toàn một vật rắn ở nhiệt độ nóng chảy được tính theo công thức: $Q = \\lambda m$, trong đó $\\lambda$ là nhiệt nóng chảy riêng (J/kg) và $m$ là khối lượng (kg).</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 100\\ \\text{g} = 0{,}1\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 3{,}34 \\cdot 10^{5} \\cdot 0{,}1 = 3{,}34 \\cdot 10^{4}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q = 3{,}34 \\cdot 10^{4}\\ \\text{J} = 33{,}4\\ \\text{kJ}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: nhiệt lượng cần thiết là $33{,}4$ kJ, đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":417,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["334 kJ.","33,4 kJ.","33,4 J.","33,4 MJ."],"question":"Nhiệt nóng chảy riêng của nước đá bằng 3,34.10<sup>5</sup> J/kg, nhiệt lượng cần thiết để làm nóng chảy hoàn toàn 100 g nước đá ở nhiệt độ nóng chảy là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần để làm nóng chảy hoàn toàn một vật rắn ở nhiệt độ nóng chảy được tính theo công thức: $Q = \\lambda m$, trong đó $\\lambda$ là nhiệt nóng chảy riêng (J/kg) và $m$ là khối lượng (kg).</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 100\\ \\text{g} = 0{,}1\\ \\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 3{,}34 \\cdot 10^{5} \\cdot 0{,}1 = 3{,}34 \\cdot 10^{4}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q = 3{,}34 \\cdot 10^{4}\\ \\text{J} = 33{,}4\\ \\text{kJ}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: nhiệt lượng cần thiết là $33{,}4$ kJ, đáp án B.</p>","difficultySource":"ai"}}]},{"id":672744,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nguyên tắc tạo ra dòng điện xoay chiều","answer":"7","question":"Một khung dây hình chữ nhật có N = 400 vòng với chiều dài các cạnh lần lượt là ab = 20 cm và bc = 10 cm quay đều với tốc độ  $\\frac{3000}{\\pi }$  vòng/phút trong từ trường đều B = 0,25 T. Biết dây dẫn của khung được làm bằng vật liệu có điện trở suất 1,5.10<sup>−8</sup> Ωm, và có tiết diện là 0,4 mm2. Cuộn dây được kết nối với hệ thống bộ góp với chổi quét để tiếp xúc và nối với điện trở R = 11 Ω như hình vẽ. Bỏ qua điện trở của dây nối, cường độ dòng điện hiệu dụng trong mạch bằng bao nhiêu A? (Kết quả làm tròn đến chữ số hàng đơn vị).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046921132-hinh-20.png\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"$I=\\frac{E}{R+r}$<br>$C=0,6\\Rightarrow$  Tổng  $L=400.0,6=240\\left(m\\right)$<br>+  $r=\\frac{\\rho L}{S}=1,5.10^{−8}.\\frac{240}{0,4.10^{−6}}=9\\Omega$<br>+  $R=11\\left(\\Omega \\right)$<br>$2\\pi f=\\omega =\\frac{3000.2\\pi }{\\pi .60}=100\\left(rad/s\\right)$<br>+  $E=\\frac{NBS\\omega }{\\sqrt2}=\\frac{400.0,25.0,2.0,1.100}{\\sqrt2}=100\\sqrt2$<br>$\\Rightarrow I=\\frac{E}{R+r}=\\frac{100\\sqrt2}{11+9}\\approx 7,07A$","difficultySource":"ai"},"ex":[{"exam":417,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Nguyên tắc tạo ra dòng điện xoay chiều","answer":"7","question":"Một khung dây hình chữ nhật có N = 400 vòng với chiều dài các cạnh lần lượt là ab = 20 cm và bc = 10 cm quay đều với tốc độ  $\\frac{3000}{\\pi }$  vòng/phút trong từ trường đều B = 0,25 T. Biết dây dẫn của khung được làm bằng vật liệu có điện trở suất 1,5.10<sup>−8</sup> Ωm, và có tiết diện là 0,4 mm2. Cuộn dây được kết nối với hệ thống bộ góp với chổi quét để tiếp xúc và nối với điện trở R = 11 Ω như hình vẽ. Bỏ qua điện trở của dây nối, cường độ dòng điện hiệu dụng trong mạch bằng bao nhiêu A? (Kết quả làm tròn đến chữ số hàng đơn vị).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046921132-hinh-20.png\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"$I=\\frac{E}{R+r}$<br>$C=0,6\\Rightarrow$  Tổng  $L=400.0,6=240\\left(m\\right)$<br>+  $r=\\frac{\\rho L}{S}=1,5.10^{−8}.\\frac{240}{0,4.10^{−6}}=9\\Omega$<br>+  $R=11\\left(\\Omega \\right)$<br>$2\\pi f=\\omega =\\frac{3000.2\\pi }{\\pi .60}=100\\left(rad/s\\right)$<br>+  $E=\\frac{NBS\\omega }{\\sqrt2}=\\frac{400.0,25.0,2.0,1.100}{\\sqrt2}=100\\sqrt2$<br>$\\Rightarrow I=\\frac{E}{R+r}=\\frac{100\\sqrt2}{11+9}\\approx 7,07A$","difficultySource":"ai"}}]},{"id":672859,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":3,"options":["22,6 MJ.","16,95 MJ.","31,5 MJ.","25,75 MJ."],"question":"Một bệnh viện cần khử trùng dụng cụ y tế bằng hơi nước. Họ đã sử dụng nồi hơi để làm nóng nước từ nhiệt độ phòng 250C đến khi nước chuyển hoàn toàn thành hơi ở 1000C. Biết rằng mỗi lần khử trùng, bệnh viện cần đun sôi 10 kg nước. Nhiệt hóa hơi riêng của nước ở 1000C là 2,26.10<sup>6</sup> J/kg và nhiệt dung riêng của nước là 4200 J/kg.K. Nhiệt lượng cần thiết để làm cho 10 kg nước ở 250C chuyển hoàn toàn thành hơi nước ở 1000C là:","difficulty":"de","explanation":"$Q=mc\\Delta t+mL$<br>$\\Rightarrow Q=10.4200.\\left(100−25\\right)+10.2,26.10^6$<br>$\\Rightarrow Q=25,75.10^6\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":422,"idx":1,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":3,"options":["22,6 MJ.","16,95 MJ.","31,5 MJ.","25,75 MJ."],"question":"Một bệnh viện cần khử trùng dụng cụ y tế bằng hơi nước. Họ đã sử dụng nồi hơi để làm nóng nước từ nhiệt độ phòng 250C đến khi nước chuyển hoàn toàn thành hơi ở 1000C. Biết rằng mỗi lần khử trùng, bệnh viện cần đun sôi 10 kg nước. Nhiệt hóa hơi riêng của nước ở 1000C là 2,26.10<sup>6</sup> J/kg và nhiệt dung riêng của nước là 4200 J/kg.K. Nhiệt lượng cần thiết để làm cho 10 kg nước ở 250C chuyển hoàn toàn thành hơi nước ở 1000C là:","difficulty":"de","explanation":"$Q=mc\\Delta t+mL$<br>$\\Rightarrow Q=10.4200.\\left(100−25\\right)+10.2,26.10^6$<br>$\\Rightarrow Q=25,75.10^6\\left(J\\right)$","difficultySource":"ai"}}]},{"id":672881,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"78,6","question":"Một bình chứa oxygen (O2) sử dụng trong y tế có thể tích 14 lít, áp suất 15.106 Pa và nhiệt độ phòng 270C. Theo thông tin từ bộ y tế, thông thường đối với một bệnh nhân mắc bệnh hô hấp được chỉ định dùng liệu pháp oxi, thì người bệnh cần được cung cấp trung bình 6 lít oxygen (ở điều kiện tiêu chuẩn, nhiệt độ 00C áp suất 1,013.10<sup>5</sup> Pa) trong 15 phút. Với tốc độ thở như vậy người đó dùng hết bình oxygen 14 lít sau bao nhiêu giờ? (Kết quả làm tròn đến chữ số thập phân thứ 1 sau dấu phẩy).","difficulty":"kho","explanation":"+ Số mol Oxi trong bình:  $n_{Oxi}=\\frac{p_bV_b}{RT_b}$<br>+ Số mol sử dụng trong 15 phút:  $\\Delta n15phut=\\frac{pV}{RT}=\\frac{pV}{RT}$<br>$\\Rightarrow \\tau =15.\\frac{n_{Oxi}}{\\Delta n}=15.\\frac{p_bV_b}{PV}\\frac{T}{T_b}$<br>$\\Rightarrow \\tau =15.\\frac{15.10^6.14}{1,013.10^5.6}.\\frac{0+273}{27+273}$<br>$\\Rightarrow \\tau =4716,2\\left(phut\\right)\\approx 78,6\\left(h\\right)$","difficultySource":"ai"},"ex":[{"exam":422,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"78,6","question":"Một bình chứa oxygen (O2) sử dụng trong y tế có thể tích 14 lít, áp suất 15.106 Pa và nhiệt độ phòng 270C. Theo thông tin từ bộ y tế, thông thường đối với một bệnh nhân mắc bệnh hô hấp được chỉ định dùng liệu pháp oxi, thì người bệnh cần được cung cấp trung bình 6 lít oxygen (ở điều kiện tiêu chuẩn, nhiệt độ 00C áp suất 1,013.10<sup>5</sup> Pa) trong 15 phút. Với tốc độ thở như vậy người đó dùng hết bình oxygen 14 lít sau bao nhiêu giờ? (Kết quả làm tròn đến chữ số thập phân thứ 1 sau dấu phẩy).","difficulty":"kho","explanation":"+ Số mol Oxi trong bình:  $n_{Oxi}=\\frac{p_bV_b}{RT_b}$<br>+ Số mol sử dụng trong 15 phút:  $\\Delta n15phut=\\frac{pV}{RT}=\\frac{pV}{RT}$<br>$\\Rightarrow \\tau =15.\\frac{n_{Oxi}}{\\Delta n}=15.\\frac{p_bV_b}{PV}\\frac{T}{T_b}$<br>$\\Rightarrow \\tau =15.\\frac{15.10^6.14}{1,013.10^5.6}.\\frac{0+273}{27+273}$<br>$\\Rightarrow \\tau =4716,2\\left(phut\\right)\\approx 78,6\\left(h\\right)$","difficultySource":"ai"}}]},{"id":672882,"nq":{"form":"bai_tap","type":"short_answer","topic":"Mol, số Avogadro và lượng chất khí","answer":"2,97","question":"Một hộp hình lập phương có cạnh 10 cm chứa khí lí tưởng ở nhiệt độ 20°C và áp suất 1,2.10<sup>6</sup> Pa. Cho số Avogadro NA = 6,2.10<sup>23</sup> mol‒1. Hằng số Boltzmann k = 1,38.10‒23 (J/K). Số phân tử khí trong hộp là a.10<sup>23</sup> phân tử. Tìm a. Làm tròn đến số thập phân thứ hai sau dấu phẩy.","difficulty":"trung-binh","explanation":"$n=\\frac{pV}{RT}$<br>$N=nN_A=\\frac{pV}{RT}.N_A=\\frac{pV}{\\frac{R}{N_A}.T}$<br>$\\frac{R}{N_A}=k\\rightarrow N=\\frac{pV}{KT}$<br>$N=\\frac{1,2.10^6.0,1^3}{1,38.10^{−23}.\\left(20+273\\right)}=2,97.10^{23}$  (phân tử)","difficultySource":"ai"},"ex":[{"exam":422,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Mol, số Avogadro và lượng chất khí","answer":"2,97","question":"Một hộp hình lập phương có cạnh 10 cm chứa khí lí tưởng ở nhiệt độ 20°C và áp suất 1,2.10<sup>6</sup> Pa. Cho số Avogadro NA = 6,2.10<sup>23</sup> mol‒1. Hằng số Boltzmann k = 1,38.10‒23 (J/K). Số phân tử khí trong hộp là a.10<sup>23</sup> phân tử. Tìm a. Làm tròn đến số thập phân thứ hai sau dấu phẩy.","difficulty":"trung-binh","explanation":"$n=\\frac{pV}{RT}$<br>$N=nN_A=\\frac{pV}{RT}.N_A=\\frac{pV}{\\frac{R}{N_A}.T}$<br>$\\frac{R}{N_A}=k\\rightarrow N=\\frac{pV}{KT}$<br>$N=\\frac{1,2.10^6.0,1^3}{1,38.10^{−23}.\\left(20+273\\right)}=2,97.10^{23}$  (phân tử)","difficultySource":"ai"}}]},{"id":672884,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":"11,5","question":"Hương vị của bia Hà nội đã trở thành một thương hiệu mà nhiều người yêu thích. Mở nắp một chai bia rồi rót 200 g bia vào cốc. Cho vào cốc 40 g nước đá ở nhiệt độ ‒2,80C thì ta sẽ được một cốc bia mát. Biết nhiệt dung riêng của bia là 3830 J/kg.K; nhiệt dung riêng của nước đá là 1800 J/kg.K; nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg; nhiệt dung riêng của nước là 4200 J/kg.K. Ban đầu bia có nhiệt độ là 320C. Bỏ qua sự trao đổi nhiệt với môi trường và sự trao đổi nhiệt với thành cốc. Sau khi nước đã tan hết, nhiệt độ của cốc bia là bao nhiêu 0C (Kết quả làm tròn đến chữ số thập phân thứ 1 sau dấu phẩy).","difficulty":"kho","explanation":"$Q_{thu}=Q_{toa}$<br>$\\Rightarrow m_d.c_d.\\Delta t_d+m_d\\lambda +m_d.c_{nc}\\Delta t_{nc}=m_b.c_b.\\Delta t_b$<br>$\\Rightarrow 40.1800.2,8+40.3,4.10^5+40.4200\\left(t_{CB}−0\\right)=200.3830.\\left(32−t_{cb}\\right)$<br>$\\Rightarrow t_{CB}=11,5^0C$","difficultySource":"ai"},"ex":[{"exam":422,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":"11,5","question":"Hương vị của bia Hà nội đã trở thành một thương hiệu mà nhiều người yêu thích. Mở nắp một chai bia rồi rót 200 g bia vào cốc. Cho vào cốc 40 g nước đá ở nhiệt độ ‒2,80C thì ta sẽ được một cốc bia mát. Biết nhiệt dung riêng của bia là 3830 J/kg.K; nhiệt dung riêng của nước đá là 1800 J/kg.K; nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg; nhiệt dung riêng của nước là 4200 J/kg.K. Ban đầu bia có nhiệt độ là 320C. Bỏ qua sự trao đổi nhiệt với môi trường và sự trao đổi nhiệt với thành cốc. Sau khi nước đã tan hết, nhiệt độ của cốc bia là bao nhiêu 0C (Kết quả làm tròn đến chữ số thập phân thứ 1 sau dấu phẩy).","difficulty":"kho","explanation":"$Q_{thu}=Q_{toa}$<br>$\\Rightarrow m_d.c_d.\\Delta t_d+m_d\\lambda +m_d.c_{nc}\\Delta t_{nc}=m_b.c_b.\\Delta t_b$<br>$\\Rightarrow 40.1800.2,8+40.3,4.10^5+40.4200\\left(t_{CB}−0\\right)=200.3830.\\left(32−t_{cb}\\right)$<br>$\\Rightarrow t_{CB}=11,5^0C$","difficultySource":"ai"}}]},{"id":672987,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Hình 1 là sơ đồ hoạt động của hệ thống máy lọc nước RO đặt dưới chậu rửa. Sau khi lọc, nước tinh khiết được dẫn vào bình áp để tích trữ trước khi đưa lên vòi sử dụng. Trong bình áp có bóng chứa nước và bóng chứa khí ngăn cách với nhau bằng màng đàn hồi (Hình 2). Tổng thể tích của hai bóng bằng thể tích trong của bình. Coi khối khí trong bóng khí là khí lí tưởng có nhiệt độ không đổi, bỏ qua thể tích ống dẫn nước.<br>Ban đầu trong bình áp chưa có nước, khí trong bóng khí chiếm toàn bộ thể tích trong của bình (khí có nhiệt độ 250C và áp suất 0,75p0 với p0 = 105 Pa ), cho máy bơm hoạt động (vòi nước tinh khiết đóng) thì nước được đẩy vào trong bóng nước.  Khi áp suất khí trong bóng khí tăng đến 6p0 thì máy bơm tự ngắt. Mở vòi sử dụng để nước trong bóng nước chảy ra, khi áp suất khí trong bóng khí giảm đến p0 thì máy bơm lại khởi động để bơm nước vào bóng nước. Biết thể tích trong của bình áp là 20 lít.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046996635-hinh-12.jpg\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046996845-hinh-13.jpg\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khi bơm nước vào trong bóng nước lần đầu thì thể tích của bóng khí giảm.","answer":true},{"text":"Số phân tử khí trong bóng khí là 3,65.10<sup>23</sup> phân tử.","answer":true},{"text":"Quá trình biến đổi trạng thái của khí trong bóng khí tuân theo định luật Charles.","answer":false},{"text":"Giữa hai lần kế tiếp máy bơm làm việc (từ lúc máy tự ngắt đến lúc máy bắt đầu bơm lại), lượng nước lấy ra từ bình là 12,5 lít.","answer":true}],"explanation":"a) đúng<br>Khối khí kín, quá trình đẳng nhiệt, p và V tỉ lệ nghịch.<br>b) đúng<br>Số phân tử khí trong bóng khí là 3,65.10<sup>23</sup> phân tử.<br>c) sai<br>Quá trình biến đổi trạng thái của khí trong bóng khí tuân theo định luật Boyle.<br>d) đúng<br>- Thể tích khí khi máy bơm tự ngắt là:  $0,75p_0V_0=3p_0V_1\\Rightarrow V_1=\\frac{0,75.V_0}{3}=5ℓ$<br>- Thể tích của khí trong bình khi bơm bắt đầu hoạt động lại là:<br>$0,75p_0V_0=p_0V_2\\Rightarrow V_2=0,75V_0=15ℓ$<br>- Thể tích nước lấy ra lúc này bằng:<br>$\\Delta V_{nuoc}=\\Delta V_{khi}=15=2,5=12,5\\left(ℓ\\right)$","difficultySource":"ai"},"ex":[{"exam":426,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Hình 1 là sơ đồ hoạt động của hệ thống máy lọc nước RO đặt dưới chậu rửa. Sau khi lọc, nước tinh khiết được dẫn vào bình áp để tích trữ trước khi đưa lên vòi sử dụng. Trong bình áp có bóng chứa nước và bóng chứa khí ngăn cách với nhau bằng màng đàn hồi (Hình 2). Tổng thể tích của hai bóng bằng thể tích trong của bình. Coi khối khí trong bóng khí là khí lí tưởng có nhiệt độ không đổi, bỏ qua thể tích ống dẫn nước.<br>Ban đầu trong bình áp chưa có nước, khí trong bóng khí chiếm toàn bộ thể tích trong của bình (khí có nhiệt độ 250C và áp suất 0,75p0 với p0 = 105 Pa ), cho máy bơm hoạt động (vòi nước tinh khiết đóng) thì nước được đẩy vào trong bóng nước.  Khi áp suất khí trong bóng khí tăng đến 6p0 thì máy bơm tự ngắt. Mở vòi sử dụng để nước trong bóng nước chảy ra, khi áp suất khí trong bóng khí giảm đến p0 thì máy bơm lại khởi động để bơm nước vào bóng nước. Biết thể tích trong của bình áp là 20 lít.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046996635-hinh-12.jpg\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046996845-hinh-13.jpg\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khi bơm nước vào trong bóng nước lần đầu thì thể tích của bóng khí giảm.","answer":true},{"text":"Số phân tử khí trong bóng khí là 3,65.10<sup>23</sup> phân tử.","answer":true},{"text":"Quá trình biến đổi trạng thái của khí trong bóng khí tuân theo định luật Charles.","answer":false},{"text":"Giữa hai lần kế tiếp máy bơm làm việc (từ lúc máy tự ngắt đến lúc máy bắt đầu bơm lại), lượng nước lấy ra từ bình là 12,5 lít.","answer":true}],"explanation":"a) đúng<br>Khối khí kín, quá trình đẳng nhiệt, p và V tỉ lệ nghịch.<br>b) đúng<br>Số phân tử khí trong bóng khí là 3,65.10<sup>23</sup> phân tử.<br>c) sai<br>Quá trình biến đổi trạng thái của khí trong bóng khí tuân theo định luật Boyle.<br>d) đúng<br>- Thể tích khí khi máy bơm tự ngắt là:  $0,75p_0V_0=3p_0V_1\\Rightarrow V_1=\\frac{0,75.V_0}{3}=5ℓ$<br>- Thể tích của khí trong bình khi bơm bắt đầu hoạt động lại là:<br>$0,75p_0V_0=p_0V_2\\Rightarrow V_2=0,75V_0=15ℓ$<br>- Thể tích nước lấy ra lúc này bằng:<br>$\\Delta V_{nuoc}=\\Delta V_{khi}=15=2,5=12,5\\left(ℓ\\right)$","difficultySource":"ai"}}]}]$j$::jsonb) loop
    h := public.question_content_hash(r->'nq');
    if exists (select 1 from public.question_bank where content_hash = h and id <> (r->>'id')::bigint) then raise notice 'TRUNG %', r->>'id'; continue; end if;
    update public.question_bank set question = r->'nq', content_hash = h, updated_at = now() where id = (r->>'id')::bigint;
    for e in select * from jsonb_array_elements(r->'ex') loop
      update public.exams set questions = jsonb_set(questions, array[e->>'idx'], e->'el') where id = (e->>'exam')::bigint;
    end loop;
  end loop;
end $do$;
alter table public.exams enable trigger trg_exams_sync_bank;
commit;
